    void SF_GCntRun(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        if (av.length() - 1 != 1) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script SF_GCntRun"_a));
        }
        std::int32_t Index = Globals::FindScriptTemplateIndex(av[1]->GetString());
        if (Index < 0) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script.NotFound SF_GCntRun"_a));
        }
        av[0]->SetInt(pas::list_at<Globals::TScriptTemplUnit>(Globals::ScriptTemplates, Index)->UseCount);
    }

    void SF_GLastTurnRun(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        if (av.length() - 1 < 1) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script SF_GCntRun"_a));
        }
        std::int32_t Index = Globals::FindScriptTemplateIndex(av[1]->GetString());
        if (Index < 0) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script.NotFound SF_GLastTurnRun"_a));
        }
        if (av.length() - 1 >= 2 && pas::list_at<Globals::TScriptTemplUnit>(Globals::ScriptTemplates, Index)->UseCount < 1) {
            av[0]->SetInt(av[2]->GetInt());
        } else {
            av[0]->SetInt(pas::list_at<Globals::TScriptTemplUnit>(Globals::ScriptTemplates, Index)->LastTurn);
        }
    }

    void SF_GAllCntRun(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        std::int32_t Count{};
        std::int32_t ClassId{};
        std::int32_t I{};
        if (av.length() - 1 >= 1) {
            ClassId = av[1]->GetInt();
            Count = 0;
            for (auto cpp_range = pas::for_to<std::int32_t>(0, pas::list_count(aGalaxy::Galaxy->Scripts) - 1); cpp_range.next(I); ) {
                if (pas::list_at<aScript::TScript>(aGalaxy::Galaxy->Scripts, I)->ClassId == ClassId) {
                    ++Count;
                }
            }
            av[0]->SetInt(Count);
        } else {
            av[0]->SetInt(pas::list_count(aGalaxy::Galaxy->Scripts));
        }
    }

    void SF_IsScriptActive(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        if (av.length() - 1 < 1) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script IsScriptActive"_a));
        }
        av[0]->SetInt(0);
        std::int32_t Index = Globals::FindScriptTemplateIndex(av[1]->GetString());
        if (Index >= 0) {
            av[0]->SetInt(pas::list_at<Globals::TScriptTemplUnit>(Globals::ScriptTemplates, Index)->ActiveScriptIndex >= 0);
        }
    }

    void SF_GetValueFromScript(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        std::int32_t Index{};
        aScript::TScript* Script{};
        EC_Expression::TVarEC* Value{};
        std::int32_t LastArg = av.length() - 1;
        if (LastArg < 2) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script GetValueFromScript"_a));
        }
        if (av[1]->GetString() == u"") {
            Value = ([&] {
                const pas::WideString& string = av[2]->GetString();
                EC_Expression::TVarArrayEC* scriptFunctionScope = aScript::ScriptFunctionScope;
                return scriptFunctionScope->GetVarNE(string);
            }());
            if (Value == nullptr) {
                pas::raise(pas::make_exception<pas::Exception>(static_cast<pas::AnsiString>(pas::concat_wide({u"Error.Script GetValueFromScript - var ", av[2]->GetString(), u" not found"}))));
            }
        } else {
            Index = Globals::FindScriptTemplateIndex(av[1]->GetString());
            if (Index < 0) {
                return;
            }
            Index = pas::list_at<Globals::TScriptTemplUnit>(Globals::ScriptTemplates, Index)->ActiveScriptIndex;
            if (Index < 0) {
                return;
            }
            Script = pas::list_at<aScript::TScript>(aGalaxy::Galaxy->Scripts, Index);
            Value = ([&] {
                const pas::WideString& string_2 = av[2]->GetString();
                EC_Expression::TVarArrayEC* localVar = Script->InitCode->LocalVar;
                return localVar->GetVarNE(string_2);
            }());
            if (Value == nullptr) {
                Value = ([&] {
                    const pas::WideString& string_3 = av[2]->GetString();
                    EC_Expression::TVarArrayEC* localVar_2 = Script->TurnCode->LocalVar;
                    return localVar_2->GetVarNE(string_3);
                }());
            }
            if (Value == nullptr) {
                Value = ([&] {
                    const pas::WideString& string_4 = av[2]->GetString();
                    EC_Expression::TVarArrayEC* scriptFunctionScope_2 = aScript::ScriptFunctionScope;
                    return scriptFunctionScope_2->GetVarNE(string_4);
                }());
            }
            if (Value == nullptr) {
                pas::raise(pas::make_exception<pas::Exception>(static_cast<pas::AnsiString>(pas::concat_wide({u"Error.Script GetValueFromScript - var ", av[2]->GetString(), u" not found in script ", av[1]->GetString()}))));
            }
        }
        Index = 2;
        while (Value->RealVType() == EC_Expression::vkArray && Index < LastArg) {
            ++Index;
            if (av[Index]->RealVType() == EC_Expression::vkString) {
                Value = ([&] {
                    const pas::WideString& string_5 = av[Index]->GetString();
                    EC_Expression::TVarArrayEC* array = Value->GetArray();
                    return array->GetVar(string_5);
                }());
            } else {
                std::int32_t pasint = av[Index]->GetInt();
                EC_Expression::TVarArrayEC* array_2 = Value->GetArray();
                Value = EC_Expression::TVarArrayEC_GetItem(array_2, pasint);
            }
        }
        switch (Value->RealVType()) {
            case EC_Expression::vkInt: av[0]->SetInt(Value->GetInt()); break;
            case EC_Expression::vkDword: av[0]->SetDword(Value->GetDword()); break;
            case EC_Expression::vkFloat: av[0]->SetFloat(Value->GetFloat()); break;
            case EC_Expression::vkString: {
                const pas::WideString& string_6 = Value->GetString();
                EC_Expression::TVarEC* cpp_arg = av[0];
                cpp_arg->SetString(string_6);
                break;
            }
            case EC_Expression::vkArray: av[0]->SetInt(Value->GetArray()->Count); break;
        }
    }

    void SF_RunFunctionFromScript(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        std::int32_t I{};
        pas::WideString Name{};
        std::int32_t LastArg = av.length() - 1;
        if (LastArg < 2) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script RunFunctionFromScript"_a));
        }
        std::int32_t Index = Globals::FindScriptTemplateIndex(av[1]->GetString());
        if (Index < 0) {
            return;
        }
        Index = pas::list_at<Globals::TScriptTemplUnit>(Globals::ScriptTemplates, Index)->ActiveScriptIndex;
        if (Index < 0) {
            return;
        }
        aScript::TScript* Script = pas::list_at<aScript::TScript>(aGalaxy::Galaxy->Scripts, Index);
        Name = pas::concat_wide({u"g_", av[2]->GetString()});
        EC_Expression::TVarEC* Value = Script->InitCode->LocalVar->GetVarNE(Name);
        if (Value == nullptr) {
            Value = Script->TurnCode->LocalVar->GetVarNE(Name);
        }
        if (Value == nullptr || Value->RealVType() != EC_Expression::vkFunction) {
            pas::raise(pas::make_exception<pas::Exception>(static_cast<pas::AnsiString>(pas::concat_wide({u"Error.Script RunFunctionFromScript - function ", Name, u" not found in script ", av[1]->GetString()}))));
        }
        EC_Expression::TCodeEC* CallCode = pas::construct_call<EC_Expression::TCodeEC>(EC_Expression::TCodeEC_Create);
        CallCode->CopyFromFast(Value->GetFunction());
        for (auto cpp_range = pas::for_to<std::int32_t>(3, LastArg); cpp_range.next(I); ) {
            if (EC_Expression::TVarArrayEC_GetItem(CallCode->LocalVar, I - 3)->Kind == EC_Expression::vkRef) {
                EC_Expression::TVarArrayEC_GetItem(CallCode->LocalVar, I - 3)->SetRef(av[I]);
            } else {
                EC_Expression::TVarArrayEC_GetItem(CallCode->LocalVar, I - 3)->Assume(av[I], false);
            }
        }
        aScript::TScript* SavedScript = aScript::CurrentScript;
        try {
            {
                EC_Expression::TVarEC* var = CallCode->LocalVar->GetVar(u"result"_wref.get());
                EC_Expression::TVarEC* cpp_arg = av[0];
                var->SetRef(cpp_arg);
            }
            aScript::CurrentScript = Script;
            CallCode->Run(aScript::ScriptProcess);
        } catch (...) {
            auto cpp_exception = pas::caught_object();
            if (BreakMessageGIException::EBreakMessageGI* E = pas::class_cast_if<BreakMessageGIException::EBreakMessageGI*>(cpp_exception)) {
                pas::free(CallCode);
                throw;
            } else if (pas::Exception* E_2 = pas::class_cast_if<pas::Exception*>(cpp_exception)) {
                pas::raise(pas::make_exception<EC_Expression::ExceptionExpressionEC>(static_cast<pas::AnsiString>(pas::concat_wide({u"Error in function ", Value->Name, u" (", static_cast<pas::WideString>(pas::class_name(pas::class_type(E_2))), u" ", static_cast<pas::WideString>(E_2->message), u")"}))));
            } else {
                throw;
            }
        }
        // Native exceptions bypass context restoration; only EBreakMessageGI frees CallCode.
        aScript::CurrentScript = SavedScript;
        pas::free(CallCode);
    }

