    void SF_CountRewardByNom(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        std::int32_t Index{};
        if (av.length() - 1 < 2) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script SF_CountRewardByNom"_a));
        }
        aShip::TShip* Ship = reinterpret_cast<aShip::TShip*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())));
        std::int32_t Award = av[2]->GetInt();
        if (Ship->AwardIds == nullptr) {
            av[0]->SetInt(0);
            return;
        }
        std::int32_t Count = 0;
        for (auto cpp_range = pas::for_to<std::int32_t>(0, pas::list_count(Ship->AwardIds) - 1); cpp_range.next(Index); ) {
            if (static_cast<std::int32_t>(reinterpret_cast<std::uintptr_t>(pas::list_get(Ship->AwardIds, Index))) == Award) {
                ++Count;
            }
        }
        av[0]->SetInt(Count);
    }

    void SF_DeleteRewardByNom(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        std::int32_t Index{};
        std::int32_t Count{};
        if (av.length() - 1 < 2) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script SF_DeleteRewardByNom"_a));
        }
        aShip::TShip* Ship = reinterpret_cast<aShip::TShip*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())));
        std::int32_t Award = av[2]->GetInt();
        if (av.length() - 1 > 2) {
            Count = av[3]->GetInt();
        } else {
            Count = 1;
        }
        av[0]->SetInt(0);
        if (Ship->AwardIds != nullptr) {
            const std::int32_t cpp_first = pas::list_count(Ship->AwardIds) - 1;
            if (cpp_first >= 0) {
                for (Index = cpp_first; Index >= 0; --Index) {
                    if (static_cast<std::int32_t>(reinterpret_cast<std::uintptr_t>(pas::list_get(Ship->AwardIds, Index))) == Award || Award == -1) {
                        pas::list_delete(Ship->AwardIds, Index);
                        av[0]->SetInt(av[0]->GetInt() + 1);
                        if (av[0]->GetInt() >= Count) {
                            break;
                        }
                    }
                }
            }
        }
    }

    void SF_Rnd(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        std::int32_t LowValue{};
        std::int32_t HighValue{};
        std::uint32_t Seed{};
        if (av.length() - 1 < 2) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script Rnd"_a));
        }
        if (av.length() - 1 > 2) {
            Seed = av[3]->GetDword();
            {
                std::int32_t pasint = av[2]->GetInt();
                std::int32_t pasint_2 = av[1]->GetInt();
                std::int32_t nextRandomIntRange = aMyFunction::NextRandomIntRange(pasint_2, pasint, Seed);
                EC_Expression::TVarEC* cpp_arg = av[0];
                cpp_arg->SetInt(nextRandomIntRange);
            }
        } else if (aGalaxy::Galaxy != nullptr) {
            std::int32_t pasint_3 = av[2]->GetInt();
            std::int32_t pasint_4 = av[1]->GetInt();
            std::int32_t nextRandomIntRange_2 = aMyFunction::NextRandomIntRange(pasint_4, pasint_3, aGalaxy::Galaxy->RandomState);
            EC_Expression::TVarEC* cpp_arg_2 = av[0];
            cpp_arg_2->SetInt(nextRandomIntRange_2);
        } else {
            LowValue = av[1]->GetInt();
            HighValue = av[2]->GetInt();
            {
                std::int32_t cpp_arg_3 = LowValue + pas::random(HighValue - LowValue + 1, &System::RandSeed);
                EC_Expression::TVarEC* cpp_arg_4 = av[0];
                cpp_arg_4->SetInt(cpp_arg_3);
            }
        }
    }

