    void SF_UseTranclucator(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        pas::Object* Obj{};
        aItem::TArtefactTranclucator* Artefact{};
        aTranclucator::TTranclucator* Drone{};
        std::int32_t Index{};
        float Angle{};
        if (av.length() - 1 < 1) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script SF_UseTranclucator"_a));
        }
        av[0]->SetDword(0u);
        aShip::TShip* Ship = reinterpret_cast<aShip::TShip*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())));
        if (!Ship->InHyperspace) {
            Obj = nullptr;
            if (av.length() - 1 > 1) {
                Obj = reinterpret_cast<pas::Object*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[2]->GetDword())));
            } else {
                for (auto cpp_range = pas::for_to<std::int32_t>(0, pas::list_count(Ship->Artefacts) - 1); cpp_range.next(Index); ) {
                    Obj = pas::list_at<pas::Object>(Ship->Artefacts, Index);
                    if (pas::class_cast_if<aItem::TArtefactTranclucator*>(Obj) != nullptr && reinterpret_cast<aItem::TArtefactTranclucator*>(Obj)->BrokenFlag == 0) {
                        break;
                    }
                }
            }
            if (Obj != nullptr && pas::class_cast_if<aItem::TArtefactTranclucator*>(Obj) != nullptr) {
                Artefact = pas::checked_cast<aItem::TArtefactTranclucator*>(Obj);
                Drone = static_cast<aTranclucator::TTranclucator*>(Artefact->Ship);
                Artefact->Ship = nullptr;
                Drone->CurrentStar = Ship->CurrentStar;
                pas::list_add(Ship->CurrentStar->Ships, reinterpret_cast<void*>(Drone));
                if (Ship->InNormalSpace()) {
                    Angle = pas::real_divide(aMyFunction::SeededRandomIntRange(0, 360, Drone->Id * (Ship->CurrentStar->GenerationSeed * static_cast<std::uint32_t>(aGalaxy::Galaxy->CurrentTurn))) * SystemImports::Pi, 1.8E+2L);
                    Drone->Position.X = System::Sin(Angle) * 1.0E+2L + Ship->Position.X;
                    Drone->Position.Y = Ship->Position.Y - System::Cos(Angle) * 1.0E+2L;
                } else if (Ship->CurrentPlanet != nullptr) {
                    Drone->CurrentPlanet = Ship->CurrentPlanet;
                } else if (Ship->DockedTo != nullptr) {
                    Drone->DockedTo = Ship->DockedTo;
                }
                Drone->Graphic->SetPosition(Drone->Position);
                Drone->OwnerShip = Ship;
                Index = pas::list_indexof(Ship->Artefacts, reinterpret_cast<void*>(Artefact));
                if (Index >= 0) {
                    pas::list_delete(Ship->Artefacts, Index);
                }
                Index = pas::list_indexof(Ship->Inventory, reinterpret_cast<void*>(Artefact));
                if (Index >= 0) {
                    pas::list_delete(Ship->Inventory, Index);
                }
                pas::free(Artefact);
                Ship->RefreshDerivedStats(true);
                Drone->NextDay();
                av[0]->SetDword(static_cast<std::uint32_t>(reinterpret_cast<std::uintptr_t>(Drone)));
            }
        }
    }

