    void SF_ConNear(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        std::int32_t I{};
        std::int32_t J{};
        aGalaxy::TConstellation* Neighbor{};
        aGalaxy::TConstellation* Candidate{};
        if (av.length() - 1 < 2) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script ConNear"_a));
        }
        aGalaxy::TConstellation* Constellation = reinterpret_cast<aGalaxy::TConstellation*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())));
        std::int32_t Count = pas::list_count(Constellation->AdjacentConstellations);
        std::int32_t ArgCount = av.length() - 1 - 1;
        for (auto cpp_range = pas::for_to<std::int32_t>(0, Count - 1); cpp_range.next(I); ) {
            Neighbor = pas::list_at<aGalaxy::TConstellation>(Constellation->AdjacentConstellations, I);
            for (auto cpp_range_2 = pas::for_to<std::int32_t>(0, ArgCount - 1); cpp_range_2.next(J); ) {
                Candidate = reinterpret_cast<aGalaxy::TConstellation*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[2 + J]->GetDword())));
                if (Neighbor == Candidate) {
                    av[0]->SetInt(1);
                    return;
                }
            }
        }
        av[0]->SetInt(0);
    }

