    void SF_StarAngleBetween(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        if (av.length() - 1 != 5) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script StarAngleBetween"_a));
        }
        aGalaxy::TStar* Star1 = reinterpret_cast<aGalaxy::TStar*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())));
        aGalaxy::TStar* CenterStar = reinterpret_cast<aGalaxy::TStar*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[2]->GetDword())));
        aGalaxy::TStar* Star2 = reinterpret_cast<aGalaxy::TStar*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[3]->GetDword())));
        float MinAngle = av[4]->GetFloat();
        float MaxAngle = av[5]->GetFloat();
        float Angle = std::fabs(static_cast<pas::Extended>(([&] {
            double pointBearingDegrees = aMyFunction::PointBearingDegrees(CenterStar->Position, Star1->Position);
            double pointBearingDegrees_2 = aMyFunction::PointBearingDegrees(CenterStar->Position, Star2->Position);
            return aMyFunction::HeadingDifferenceDegrees(pointBearingDegrees, pointBearingDegrees_2);
        }())));
        if (Angle >= MinAngle && Angle <= MaxAngle) {
            av[0]->SetInt(1);
        } else {
            av[0]->SetInt(0);
        }
    }

    void SF_FindPlanet(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        aGalaxy::TStar* Star{};
        aPlanet::TPlanet* Planet{};
        pas::WideString Filters{};
        pas::WideString Filter{};
        float MinFraction{};
        float MaxFraction{};
        std::int32_t I{};
        std::int32_t J{};
        if (av.length() - 1 < 2) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script FindPlanet"_a));
        }
        Star = reinterpret_cast<aGalaxy::TStar*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())));
        Filters = av[2]->GetString();
        if (av.length() - 1 >= 3) {
            MinFraction = pas::real_divide(av[3]->GetFloat(), 1.0E+2L);
        } else {
            MinFraction = 0.0f;
        }
        if (av.length() - 1 >= 4) {
            MaxFraction = pas::real_divide(av[4]->GetFloat(), 1.0E+2L);
        } else {
            MaxFraction = 1.0f;
        }
        pas::List* Planets = pas::make_object<pas::List>();
        std::int32_t Count = pas::list_count(Star->Planets);
        std::int32_t FilterCount = EC_Str::CountDelimitedPartsW(Filters, u","_wref.get());
        for (auto cpp_range = pas::for_to<std::int32_t>(0, Count - 1); cpp_range.next(I); ) {
            Planet = pas::list_at<aPlanet::TPlanet>(Star->Planets, I);
            for (auto cpp_range_2 = pas::for_to<std::int32_t>(0, FilterCount - 1); cpp_range_2.next(J); ) {
                Filter = EC_Str::ExtractDelimitedPartW(Filters, J, u","_wref.get());
                if (Filter == u"NotMaloc" && Planet->OwnerId == static_cast<std::uint8_t>(aGalaxyStruct::oiMaloc)) {
                    break;
                }
                if (Filter == u"NotPeleng" && Planet->OwnerId == static_cast<std::uint8_t>(aGalaxyStruct::oiPeleng)) {
                    break;
                }
                if (Filter == u"NotPeople" && Planet->OwnerId == static_cast<std::uint8_t>(aGalaxyStruct::oiHuman)) {
                    break;
                }
                if (Filter == u"NotFei" && Planet->OwnerId == static_cast<std::uint8_t>(aGalaxyStruct::oiFeyan)) {
                    break;
                }
                if (Filter == u"NotGaal" && Planet->OwnerId == static_cast<std::uint8_t>(aGalaxyStruct::oiGaal)) {
                    break;
                }
                if (Filter == u"NotKling" && Planet->OwnerId == static_cast<std::uint8_t>(aGalaxyStruct::oiDominator)) {
                    break;
                }
                if (Filter == u"NotPirateClan" && Planet->OwnerId == static_cast<std::uint8_t>(aGalaxyStruct::oiPirate)) {
                    break;
                }
                if (Filter == u"NotNone" && Planet->OwnerId == static_cast<std::uint8_t>(aGalaxyStruct::oiUninhabited)) {
                    break;
                }
            }
            if (J >= FilterCount) {
                pas::list_add(Planets, reinterpret_cast<void*>(Planet));
            }
        }
        if (pas::list_count(Planets) < 1) {
            av[0]->SetDword(0u);
            pas::free(Planets);
            return;
        }
        I = System::Round(static_cast<long double>(pas::list_count(Planets) - 1) * MinFraction);
        J = System::Round(static_cast<long double>(pas::list_count(Planets) - 1) * MaxFraction);
        I += aMyFunction::NextRandomIntRange(0, J - I, Star->RandomState);
        av[0]->SetDword(static_cast<std::uint32_t>(reinterpret_cast<std::uintptr_t>(pas::list_get(Planets, I))));
        pas::free(Planets);
    }

