    void SF_EtherIdDelete(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        std::int32_t Index{};
        if (av.length() - 1 != 1) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script EtherIdDelete"_a));
        }
        while (true) {
            Index = ([&] {
                const pas::WideString& string = av[1]->GetString();
                EC_Str::TStringsEC* etherIds = aScript::CurrentScript->EtherIds;
                return etherIds->IndexOf(string);
            }());
            if (Index < 0) {
                break;
            }
            aScript::CurrentScript->EtherIds->Delete(Index);
        }
    }

