    void SF_Dialog(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        std::int32_t I{};
        std::int32_t J{};
        std::int32_t ShipCount{};
        pas::Object* Obj{};
        aScript::TScriptShip* Binding{};
        aScript::TScriptContextSnapshot Snapshot{};
        if (av.length() - 1 < 1) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script Dialog"_a));
        }
        av[0]->SetInt(0);
        if (GR_Main::ExitScreenLoop) {
            return;
        }
        if (aPlayer::GetPlayer() == nullptr) {
            return;
        }
        if (av.length() - 1 == 1 && av[1]->GetDword() == 0) {
            return;
        }
        if (!aPlayer::GetPlayer()->InNormalSpace()) {
            return;
        }
        if (GlobalsV::CurrentScreenId != GlobalsV::screenStarMap) {
            return;
        }
        if (fTalk::TalkDialogActive) {
            return;
        }
        std::uint8_t Immediate = pas::is_one_of<ThreadCalc::tcpIdle, ThreadCalc::tcpGalaxyFinished, ThreadCalc::tcpPlayerStarFinished, ThreadCalc::tcpPlayerStarPrepared>(aCalc::TurnCalculationPhase);
        aScript::ScriptSnap(Snapshot);
        if (av.length() - 1 == 1) {
            if (Immediate) {
                Globals::TalkShip = reinterpret_cast<aShip::TShip*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())));
                Globals::TalkScripted = false;
                Globals::ScriptDialogIndex = -1;
                Globals::StarMapScreen->RunTalkDialogs();
                av[0]->SetInt(1);
            } else if (reinterpret_cast<aShip::TShip*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())))->OpenPlayerConversation(false)) {
                av[0]->SetInt(1);
            }
            aScript::ScriptUnSnap(Snapshot);
            return;
        }
        std::int32_t Count = av.length() - 2;
        for (auto cpp_range = pas::for_to<std::int32_t>(0, Count - 1); cpp_range.next(I); ) {
            Obj = reinterpret_cast<pas::Object*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[2 + I]->GetDword())));
            if (static_cast<std::uint32_t>(reinterpret_cast<std::uintptr_t>(Obj)) < 0x00010000) {
                ShipCount = pas::list_count(aScript::CurrentScript->Ships);
                for (auto cpp_range_2 = pas::for_to<std::int32_t>(0, ShipCount - 1); cpp_range_2.next(J); ) {
                    Binding = pas::list_at<aScript::TScriptShip>(aScript::CurrentScript->Ships, J);
                    if (Binding->GroupIndex == static_cast<std::int32_t>(reinterpret_cast<std::uintptr_t>(Obj)) && aPlayer::GetPlayer() != Binding->Ship) {
                        Globals::ScriptDialogIndex = -1;
                        aScript::CurrentScript->CallDialog(av[1]->GetInt());
                        if (Globals::ScriptDialogIndex >= 0) {
                            if (Immediate) {
                                Globals::TalkShip = Binding->Ship;
                                Globals::TalkScripted = false;
                                Globals::StarMapScreen->RunTalkDialogs();
                                av[0]->SetInt(1);
                            } else if (Binding->Ship->OpenPlayerConversation(false)) {
                                av[0]->SetInt(1);
                            }
                            aScript::ScriptUnSnap(Snapshot);
                            return;
                        }
                    }
                }
            } else if (pas::class_cast_if<aShip::TShip*>(Obj) != nullptr) {
                Globals::ScriptDialogIndex = -1;
                aScript::CurrentScript->CallDialog(av[1]->GetInt());
                if (Globals::ScriptDialogIndex >= 0) {
                    if (Immediate) {
                        Globals::TalkShip = reinterpret_cast<aShip::TShip*>(Obj);
                        Globals::TalkScripted = false;
                        Globals::StarMapScreen->RunTalkDialogs();
                        av[0]->SetInt(1);
                    } else if (reinterpret_cast<aShip::TShip*>(Obj)->OpenPlayerConversation(false)) {
                        av[0]->SetInt(1);
                    }
                    aScript::ScriptUnSnap(Snapshot);
                    return;
                }
            } else if (pas::class_cast_if<aPlanet::TPlanet*>(Obj) != nullptr) {
                Globals::ScriptDialogIndex = -1;
                aScript::CurrentScript->CallDialog(av[1]->GetInt());
                if (Globals::ScriptDialogIndex >= 0 && reinterpret_cast<aPlanet::TPlanet*>(Obj)->RequestDialog()) {
                    av[0]->SetInt(1);
                    aScript::ScriptUnSnap(Snapshot);
                    return;
                }
            }
        }
    }

