    void SF_ShipGoods(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        std::int32_t Cost{};
        if (av.length() - 1 < 3) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script ShipGoods"_a));
        }
        aShip::TShip* Ship = reinterpret_cast<aShip::TShip*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())));
        std::uint8_t Kind = av[2]->GetInt();
        std::int32_t Quantity = av[3]->GetInt();
        Quantity = std::max<std::int32_t>(Quantity, -Ship->CargoGoods[Kind].Count);
        if (av.length() - 1 > 3) {
            Cost = av[4]->GetInt();
        } else if (Quantity > 0) {
            Cost = Quantity * aConst::GoodsMarket[Kind].AveragePrice;
        } else {
            Cost = System::Round(pas::real_divide(Quantity * Ship->CargoGoods[Kind].TotalCost, Ship->CargoGoods[Kind].Count));
        }
        Ship->CargoGoods[Kind].Count += Quantity;
        Ship->CargoGoods[Kind].TotalCost += Cost;
    }

