    void SF_CountTurn(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        aShip::TShip* OtherShip{};
        aPlanet::TPlanet* Planet{};
        aScript::TScriptPlace* Place{};
        std::uint8_t Landed{};
        EC_Struct::TPointF Position{};
        aGalaxy::TStar* Star{};
        if (av.length() - 1 != 2) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script CountTurn"_a));
        }
        std::int32_t Turns = 0;
        aShip::TShip* Ship = reinterpret_cast<aShip::TShip*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())));
        pas::Object* Obj = reinterpret_cast<pas::Object*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[2]->GetDword())));
        if (pas::class_cast_if<aScript::TScriptPlace*>(Obj) != nullptr) {
            Place = pas::checked_cast<aScript::TScriptPlace*>(Obj);
            if (Place->PlaceKind == aScript::spkPlanetPosition || Place->PlaceKind == aScript::spkDockedPlanet) {
                Planet = pas::checked_cast<aPlanet::TPlanet*>(reinterpret_cast<pas::Object*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(Place->TargetValue))));
                Position = Planet->GetPosition();
            } else {
                Planet = nullptr;
                Position = Place->GetPoint();
            }
            Landed = Place->PlaceKind == aScript::spkDockedPlanet;
            Star = Place->OriginStar;
        } else if (pas::class_cast_if<aPlanet::TPlanet*>(Obj) != nullptr) {
            Planet = pas::checked_cast<aPlanet::TPlanet*>(Obj);
            Landed = false;
            Position = Planet->GetPosition();
            Star = Planet->CurrentStar;
        } else if (pas::class_cast_if<aShip::TShip*>(Obj) != nullptr) {
            Landed = false;
            Planet = nullptr;
            OtherShip = pas::checked_cast<aShip::TShip*>(Obj);
            while (OtherShip->DockedTo != nullptr) {
                OtherShip = OtherShip->DockedTo;
            }
            if (OtherShip->CurrentPlanet != nullptr) {
                Planet = OtherShip->CurrentPlanet;
                Landed = true;
                Position = Planet->GetPosition();
                Star = Planet->CurrentStar;
            } else {
                Position = OtherShip->Position;
                Star = OtherShip->CurrentStar;
                if (OtherShip->InHyperspace) {
                    Position = OtherShip->GetArrivalPosition(OtherShip->TransitOriginStar);
                }
            }
        } else {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script CountTurn 1"_a));
        }
        if (Ship->CurrentPlanet == Planet && Landed) {
            av[0]->SetInt(0);
            return;
        }
        if (Ship->CurrentPlanet != nullptr) {
            ++Turns;
        }
        if (Landed) {
            ++Turns;
        }
        if (Ship->CurrentPlanet != nullptr && Ship->CurrentPlanet == Planet) {
            av[0]->SetInt(Turns);
            return;
        }
        if (Star == Ship->CurrentStar) {
            if (Ship->CurrentPlanet == nullptr) {
                Turns += MathImports::Ceil(pas::real_divide(aMyFunction::PointDistance(Position, Ship->Position), std::max<std::int32_t>(1, Ship->Speed)));
            } else {
                Turns += MathImports::Ceil(pas::real_divide(aMyFunction::PointDistance(Position, Ship->CurrentPlanet->GetPosition()), std::max<std::int32_t>(1, Ship->Speed)));
            }
        } else {
            if (Ship->CurrentPlanet == nullptr) {
                Turns += ([&] {
                    pas::Extended cpp_right = std::max<std::int32_t>(1, Ship->Speed);
                    EC_Struct::TPointF jumpDeparturePoint = Ship->GetJumpDeparturePoint(Star);
                    EC_Struct::TPointF position = Ship->Position;
                    return MathImports::Ceil(pas::real_divide(aMyFunction::PointDistance(jumpDeparturePoint, position), cpp_right));
                }());
            } else {
                Turns += ([&] {
                    pas::Extended cpp_right_2 = std::max<std::int32_t>(1, Ship->Speed);
                    EC_Struct::TPointF jumpDeparturePoint_2 = Ship->GetJumpDeparturePoint(Star);
                    EC_Struct::TPointF position_2 = Ship->CurrentPlanet->GetPosition();
                    return MathImports::Ceil(pas::real_divide(aMyFunction::PointDistance(jumpDeparturePoint_2, position_2), cpp_right_2));
                }());
            }
            Turns += aShip::TShip::CalculateJumpTravelDays(Ship->CurrentStar, Star);
            Turns += MathImports::Ceil(pas::real_divide(aMyFunction::PointDistance(Position, Ship->GetArrivalPosition(Star)), std::max<std::int32_t>(1, Ship->Speed)));
        }
        av[0]->SetInt(Turns);
    }

    void SF_ShipSetBad(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        if (av.length() - 1 != 2) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script ShipSetBad"_a));
        }
        if (av[1]->GetDword() != 0) {
            reinterpret_cast<aShip::TShip*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())))->EnemyShip = reinterpret_cast<aShip::TShip*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[2]->GetDword())));
        }
    }

    void SF_GroupSetBad(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        std::int32_t I{};
        aScript::TScriptShip* Binding{};
        if (av.length() - 1 != 2) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script GroupSetBad"_a));
        }
        std::int32_t GroupIndex = av[1]->GetInt();
        std::int32_t Count = pas::list_count(aScript::CurrentScript->Ships);
        for (auto cpp_range = pas::for_to<std::int32_t>(0, Count - 1); cpp_range.next(I); ) {
            Binding = pas::list_at<aScript::TScriptShip>(aScript::CurrentScript->Ships, I);
            if (Binding->GroupIndex == GroupIndex) {
                Binding->Ship->EnemyShip = reinterpret_cast<aShip::TShip*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[2]->GetDword())));
            }
        }
    }

    void SF_ShipSetPartner(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        if (av.length() - 1 != 3) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script ShipSetPartner"_a));
        }
        aShip::TShip* Ship = reinterpret_cast<aShip::TShip*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())));
        aShip::TShip* Partner = reinterpret_cast<aShip::TShip*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[2]->GetDword())));
        if (pas::class_cast_if<aPirate::TPirate*>(Ship) != nullptr && Ship->PartnerShip != Partner) {
            if (aPlayer::GetPlayer() == Ship->PartnerShip) {
                pas::list_remove(aPlayer::GetPlayer()->PiratePartners, reinterpret_cast<void*>(Ship));
            }
            if (aPlayer::GetPlayer() == Partner) {
                pas::list_add(aPlayer::GetPlayer()->PiratePartners, reinterpret_cast<void*>(Ship));
            }
        }
        Ship->PartnerShip = Partner;
        Ship->PartnershipDaysRemaining = av[3]->GetInt();
    }

    void SF_ShipJoin(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        aShip::TShip* Ship{};
        std::int32_t StateIndex{};
        std::int32_t I{};
        aScript::TScriptContextSnapshot Snapshot{};
        if (av.length() - 1 < 2) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script ShipJoin"_a));
        }
        Ship = reinterpret_cast<aShip::TShip*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[2]->GetDword())));
        if (Ship == nullptr) {
            return;
        }
        if (Ship != aPlayer::GetPlayer() && Ship->ScriptShip != nullptr) {
            if (reinterpret_cast<aScript::TScriptShip*>(Ship->ScriptShip)->Script != aScript::CurrentScript) {
                GR_Main::AppendLogLineThreadSafe(static_cast<pas::AnsiString>(pas::concat_wide({u"Warning.Script ShipJoin (", aScript::CurrentScript->ScriptFileName, u"): ship ", Ship->GetFullName(u" "_wref.get()), u" was already in another script (", reinterpret_cast<aScript::TScriptShip*>(Ship->ScriptShip)->Script->ScriptFileName, u")"})));
            }
            reinterpret_cast<aScript::TScriptShip*>(Ship->ScriptShip)->Script->UnbindShip(Ship);
            Ship->ScriptShip = nullptr;
        }
        aScript::ScriptSnap(Snapshot);
        aScript::CurrentScript->BindShip(av[1]->GetInt(), Ship);
        aScript::TScriptShip* Binding = aScript::GetScriptShipBindingForContext(Ship, aScript::CurrentScript);
        if (av.length() - 1 >= 3 && av[3]->RealVType() == EC_Expression::vkString) {
            StateIndex = -1;
            if (av[3]->GetString() == u"") {
                StateIndex = pas::list_at<aScript::TScriptGroup>(aScript::CurrentScript->Groups, Binding->GroupIndex)->InitialStateIndex;
            } else {
                for (auto cpp_range = pas::for_to<std::int32_t>(0, pas::list_count(aScript::CurrentScript->States) - 1); cpp_range.next(I); ) {
                    if (([&] {
                        const pas::WideString& cpp_string_ref = pas::list_at<aScript::TScriptState>(aScript::CurrentScript->States, I)->Name;
                        pas::WideString cpp_string = av[3]->GetString();
                        return cpp_string_ref == cpp_string;
                    }())) {
                        StateIndex = I;
                        break;
                    }
                }
            }
            if (StateIndex < 0) {
                pas::raise(pas::make_exception<pas::Exception>(static_cast<pas::AnsiString>(pas::concat_wide({u"Error.Script ShipJoin cant find state ", av[3]->GetString()}))));
            }
        } else if (av.length() - 1 >= 3) {
            StateIndex = -1;
        } else {
            StateIndex = pas::list_at<aScript::TScriptGroup>(aScript::CurrentScript->Groups, Binding->GroupIndex)->InitialStateIndex;
        }
        if (av.length() - 1 >= 4) {
            Binding->Data[0] = av[4]->GetDword();
        }
        if (av.length() - 1 >= 5) {
            Binding->Data[1] = av[5]->GetDword();
        }
        if (av.length() - 1 >= 6) {
            Binding->Data[2] = av[6]->GetDword();
        }
        if (av.length() - 1 >= 7) {
            Binding->Data[3] = av[7]->GetDword();
        }
        if (StateIndex >= 0) {
            aScript::CurrentScript->ChangeState(Binding, StateIndex);
        }
        aScript::ScriptUnSnap(Snapshot);
    }

    void SF_ShipOut(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        aShip::TShip* Ship{};
        if (av.length() - 1 < 1) {
            Ship = aScript::CurrentScript->CurrentShip;
        } else {
            Ship = reinterpret_cast<aShip::TShip*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())));
        }
        if (Ship == nullptr) {
            return;
        }
        if (Ship == aPlayer::GetPlayer()) {
            aScript::CurrentScript->UnbindShip(Ship);
        } else if (Ship->ScriptShip != nullptr) {
            reinterpret_cast<aScript::TScriptShip*>(Ship->ScriptShip)->Script->UnbindShip(Ship);
        }
    }

