    void SF_ShipEqInSlot(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        std::int32_t SlotIndex{};
        if (av.length() - 1 < 2) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script ShipEqInSlot"_a));
        }
        aShip::TShip* Ship = reinterpret_cast<aShip::TShip*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())));
        std::uint8_t ItemType = av[2]->GetInt();
        if (pas::in_range(ItemType, static_cast<std::int32_t>(aConst::t_Hull), static_cast<std::int32_t>(aConst::t_DefGenerator))) {
            av[0]->SetDword(static_cast<std::uint32_t>(reinterpret_cast<std::uintptr_t>(pas::load_unaligned<aItem::TEquipment*>(pas::byte_offset(&reinterpret_cast<aShip::PShipEquipmentCacheView>(Ship)->Slots, (ItemType - 42) * sizeof(aItem::TEquipment*))))));
        } else {
            if (av.length() - 1 < 3) {
                SlotIndex = 0;
            } else {
                SlotIndex = av[3]->GetInt() - 1;
            }
            Ship->RefreshAssignedItemSlots();
            av[0]->SetDword(static_cast<std::uint32_t>(reinterpret_cast<std::uintptr_t>(Ship->FindEquippedItemInSlot(ItemType, SlotIndex))));
        }
    }

    void SF_ArtefactTypeInUse(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        std::uint8_t ItemType{};
        pas::WideString Name{};
        std::int32_t I{};
        std::int32_t Count{};
        if (av.length() - 1 < 2) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script ArtefactTypeInUse"_a));
        }
        aShip::TShip* Ship = reinterpret_cast<aShip::TShip*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())));
        aItem::TArtefact* Item = nullptr;
        if (av[2]->RealVType() == EC_Expression::vkDword && av[2]->GetDword() > 0x0000ffff) {
            Item = reinterpret_cast<aItem::TArtefact*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[2]->GetDword())));
        }
        if (Item != nullptr && pas::is_one_of<aConst::t_Artefact, aConst::t_Artefact2>(Item->GetEffectiveType())) {
            Name = Item->ConfigBlockName;
        } else if (av[2]->RealVType() == EC_Expression::vkString) {
            Name = av[2]->GetString();
        }
        if (Name != u"") {
            Count = 0;
            for (auto cpp_range = pas::for_to<std::int32_t>(0, pas::list_count(Ship->Artefacts) - 1); cpp_range.next(I); ) {
                Item = pas::list_at<aItem::TArtefact>(Ship->Artefacts, I);
                if (pas::is_one_of<aConst::t_Artefact, aConst::t_Artefact2>(Item->ItemType) && Item->ConfigBlockName == Name && Item->BrokenFlag == 0 && Item->EquippedFlag != 0) {
                    ++Count;
                }
            }
            av[0]->SetInt(Count);
        } else {
            if (Item != nullptr) {
                ItemType = reinterpret_cast<aItem::TArtefact*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[2]->GetDword())))->GetEffectiveType();
            } else {
                ItemType = av[2]->GetInt();
            }
            av[0]->SetInt(Ship->CountActiveArtefacts(ItemType));
        }
    }

