    void SF_ShipAverageDamage(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        std::int32_t I{};
        aItem::TWeapon* Weapon{};
        if (av.length() - 1 < 1) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script ShipAverageDamage"_a));
        }
        aShip::TShip* Ship = reinterpret_cast<aShip::TShip*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())));
        std::int32_t MinDamage = 0;
        std::int32_t MaxDamage = 0;
        {
            const std::int32_t cpp_last = static_cast<std::int32_t>(Ship->WeaponCount);
            if (1 <= cpp_last) {
                for (I = 1; I <= cpp_last; ++I) {
                    Weapon = Ship->Weapons[I];
                    if (Ship->IsEquipmentUsable(Weapon)) {
                        if (pas::is_one_of<aGalaxyStruct::wstMissile, aGalaxyStruct::wstRocket>(Weapon->GetWeaponInfo()->ShotType)) {
                            {
                                std::int32_t cpp_left_2 = Ship->GetWeaponMinDamage(Weapon);
                                std::int32_t cpp_left = cpp_left_2 * Weapon->GetAttackCount();
                                MinDamage += cpp_left * Weapon->GetShotCount();
                            }
                            {
                                std::int32_t cpp_left_4 = Ship->GetWeaponMaxDamage(Weapon);
                                std::int32_t cpp_left_3 = cpp_left_4 * Weapon->GetAttackCount();
                                MaxDamage += cpp_left_3 * Weapon->GetShotCount();
                            }
                        } else {
                            {
                                std::int32_t cpp_left_5 = Ship->GetWeaponMinDamage(Weapon);
                                MinDamage += cpp_left_5 * Weapon->GetAttackCount();
                            }
                            {
                                std::int32_t cpp_left_6 = Ship->GetWeaponMaxDamage(Weapon);
                                MaxDamage += cpp_left_6 * Weapon->GetAttackCount();
                            }
                        }
                    }
                }
            }
        }
        if (av.length() - 1 > 1) {
            if (av[2]->GetInt() == 0) {
                av[0]->SetInt(MinDamage);
            } else if (av[2]->GetInt() == 1) {
                av[0]->SetInt(MaxDamage);
            } else {
                av[0]->SetInt(System::Round((MinDamage + MaxDamage) * 0.5L));
            }
        } else {
            av[0]->SetInt(System::Round((MinDamage + MaxDamage) * 0.5L));
        }
    }

    void SF_ShipHealthFactor(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        std::int32_t Duration{};
        if (av.length() - 1 < 2) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script ShipHealthFactor"_a));
        }
        aShip::TShip* Ship = reinterpret_cast<aShip::TShip*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())));
        std::int32_t Index = av[2]->GetInt();
        std::int32_t Remaining = 0;
        if (Ship == nullptr) {
            if (Index == 0) {
                av[0]->SetInt(aConst::RadiationHealthDefinitions[1].Duration);
            } else {
                av[0]->SetInt(aConst::CaptainHealthDefinitions[Index].Duration);
            }
            return;
        }
        if (Index == 0) {
            if (Ship->HasRadiationSickness()) {
                Remaining = Ship->RadiationHealth[1].ExpireTurn - aGalaxy::Galaxy->CurrentTurn;
            }
            if (av.length() - 1 > 2) {
                Duration = av[3]->GetInt();
                if (Duration == -1) {
                    Duration = aConst::RadiationHealthDefinitions[1].Duration;
                }
                if (Duration == 0) {
                    Ship->RadiationHealth[1].Progress = 0.0;
                    Ship->RadiationHealth[1].ExpireTurn = 0;
                }
                if (Remaining == 0 && Duration > 0) {
                    Ship->RadiationHealth[1].Progress = 0.5;
                    Ship->RadiationHealth[1].ExpireTurn = aGalaxy::Galaxy->CurrentTurn + Duration;
                }
                if (Remaining > 0 && Duration > 0) {
                    Ship->RadiationHealth[1].ExpireTurn = aGalaxy::Galaxy->CurrentTurn + Duration;
                }
            }
        } else if (Index > 0 && Index <= 24) {
            if (Ship->IsHealthEffectActive(Index)) {
                Remaining = Ship->CaptainHealth[Index].ExpireTurn - aGalaxy::Galaxy->CurrentTurn;
            }
            if (av.length() - 1 > 2) {
                Duration = av[3]->GetInt();
                if (Duration == -1) {
                    Duration = aConst::CaptainHealthDefinitions[Index].Duration;
                }
                if (Duration == 0) {
                    Ship->CaptainHealth[Index].Progress = 0.0;
                    Ship->CaptainHealth[Index].ExpireTurn = 0;
                }
                if (Remaining == 0 && Duration > 0) {
                    Ship->CaptainHealth[Index].Progress = 1.0E+2;
                    Ship->CaptainHealth[Index].ExpireTurn = aGalaxy::Galaxy->CurrentTurn + Duration;
                }
                if (Remaining > 0 && Duration > 0) {
                    Ship->CaptainHealth[Index].ExpireTurn = aGalaxy::Galaxy->CurrentTurn + Duration;
                }
            }
        }
        av[0]->SetInt(Remaining);
    }

