    void SF_ShipStatusEffect(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        float Strength{};
        aShip::TShip* Source{};
        if (av.length() - 1 < 2) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script ShipStatusEffect"_a));
        }
        aShip::TShip* Ship = reinterpret_cast<aShip::TShip*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())));
        aShip::TCombatStatusEffectType EffectType = static_cast<aShip::TCombatStatusEffectType>(av[2]->GetInt());
        std::int32_t Index = Ship->FindCombatStatusEffect(EffectType);
        if (Index < 0) {
            av[0]->SetFloat(0.0);
        } else {
            av[0]->SetFloat(pas::list_at<aShip::TCombatStatusEffect>(Ship->CombatStatusEffects, Index)->Strength);
        }
        if (av.length() - 1 > 2) {
            Strength = av[3]->GetFloat();
            if (av.length() - 1 > 3) {
                Source = reinterpret_cast<aShip::TShip*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[4]->GetDword())));
            } else {
                Source = nullptr;
            }
            if (Strength > 0.0L) {
                Ship->AddCombatStatusStrength(EffectType, Strength, Source);
            } else if (Strength < 0.0L) {
                Ship->ReduceCombatStatusStrength(EffectType, -Strength);
            }
        }
    }

