    void SF_ShipStatistic(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        aShip::TShip* Ship{};
        std::int32_t I{};
        if (av.length() - 1 < 2) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script ShipStatistic"_a));
        }
        pas::Object* Obj = reinterpret_cast<pas::Object*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())));
        aNormalShip::TNormalShip* NormalShip = nullptr;
        if (pas::class_cast_if<aNormalShip::TNormalShip*>(Obj) != nullptr) {
            NormalShip = reinterpret_cast<aNormalShip::TNormalShip*>(Obj);
            Ship = NormalShip;
        } else if (pas::class_cast_if<aShip::TShip*>(Obj) != nullptr && pas::in_set<10, 11>(av[2]->GetInt())) {
            Ship = reinterpret_cast<aShip::TShip*>(Obj);
        } else {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script ShipStatistic - illegal object type"_a));
        }
        switch (av[2]->GetInt()) {
            case 0: {
                av[0]->SetInt(NormalShip->TotalShipKillCount);
                if (av.length() - 1 > 2) {
                    NormalShip->TotalShipKillCount = av[3]->GetInt();
                }
                break;
            }
            case 1: {
                av[0]->SetInt(NormalShip->PirateKillCount);
                if (av.length() - 1 > 2) {
                    NormalShip->PirateKillCount = av[3]->GetInt();
                }
                break;
            }
            case 2: {
                av[0]->SetInt(NormalShip->DominatorKillCount);
                if (av.length() - 1 > 2) {
                    NormalShip->DominatorKillCount = av[3]->GetInt();
                }
                break;
            }
            case 3: {
                av[0]->SetInt(NormalShip->LiberatedSystemCount);
                if (av.length() - 1 > 2) {
                    NormalShip->LiberatedSystemCount = av[3]->GetInt();
                }
                break;
            }
            case 4: {
                av[0]->SetInt(NormalShip->CivilianKillCount);
                if (av.length() - 1 > 2) {
                    NormalShip->CivilianKillCount = av[3]->GetInt();
                }
                break;
            }
            case 5: {
                av[0]->SetInt(NormalShip->MilitaryKillCount);
                if (av.length() - 1 > 2) {
                    NormalShip->MilitaryKillCount = av[3]->GetInt();
                }
                break;
            }
            case 6: {
                av[0]->SetInt(NormalShip->RangerKillCount);
                if (av.length() - 1 > 2) {
                    NormalShip->RangerKillCount = av[3]->GetInt();
                }
                break;
            }
            case 7: {
                if (aPlayer::GetPlayer() == NormalShip) {
                    av[0]->SetInt(aPlayer::GetPlayer()->BlackHoleKillCount);
                    if (av.length() - 1 > 2) {
                        aPlayer::GetPlayer()->BlackHoleKillCount = av[3]->GetInt();
                    }
                }
                break;
            }
            case 8: {
                if (aPlayer::GetPlayer() == NormalShip) {
                    av[0]->SetInt(aPlayer::GetPlayer()->HyperspaceKillCount);
                    if (av.length() - 1 > 2) {
                        aPlayer::GetPlayer()->HyperspaceKillCount = av[3]->GetInt();
                    }
                }
                break;
            }
            case 9: {
                av[0]->SetInt(NormalShip->TradeLossBalance);
                if (av.length() - 1 > 2) {
                    NormalShip->TradeLossBalance = av[3]->GetInt();
                }
                break;
            }
            case 10: {
                av[0]->SetDword(static_cast<std::uint32_t>(reinterpret_cast<std::uintptr_t>(Ship->HomePlanet)));
                if (av.length() - 1 > 2) {
                    if (pas::class_cast_if<aWarrior::TWarrior*>(Ship) != nullptr) {
                        I = pas::list_indexof(Ship->HomePlanet->Warriors, reinterpret_cast<void*>(Ship));
                        if (I >= 0) {
                            pas::list_delete(Ship->HomePlanet->Warriors, I);
                        }
                        pas::list_add(reinterpret_cast<aPlanet::TPlanet*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[3]->GetDword())))->Warriors, reinterpret_cast<void*>(Ship));
                    } else if (pas::class_cast_if<aTransport::TTransport*>(Ship) != nullptr) {
                        --Ship->HomePlanet->HomeTransportCount;
                        ++reinterpret_cast<aPlanet::TPlanet*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[3]->GetDword())))->HomeTransportCount;
                    } else if (pas::class_cast_if<aRanger::TRanger*>(Ship) != nullptr) {
                        --Ship->HomePlanet->HomeRangerCount;
                        ++reinterpret_cast<aPlanet::TPlanet*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[3]->GetDword())))->HomeRangerCount;
                    }
                    Ship->HomePlanet = reinterpret_cast<aPlanet::TPlanet*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[3]->GetDword())));
                }
                break;
            }
            case 11: {
                av[0]->SetInt(Ship->CreationTurn);
                if (av.length() - 1 > 2) {
                    Ship->CreationTurn = av[3]->GetInt();
                }
                break;
            }
            case 12: av[0]->SetInt(NormalShip->CalculateMass()); break;
            case 13: {
                av[0]->SetInt(NormalShip->ContrabandProfit);
                if (av.length() - 1 > 2) {
                    NormalShip->ContrabandProfit = av[3]->GetInt();
                }
                break;
            }
            default: pas::raise(pas::make_exception<pas::Exception>("Error.Script ShipStatistic"_a));
        }
    }

