    void SF_ChanceToWin(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        if (av.length() - 1 < 2) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script ChanceToWin"_a));
        }
        aShip::TShip* Ship = reinterpret_cast<aShip::TShip*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())));
        aShip::TShip* Target = reinterpret_cast<aShip::TShip*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[2]->GetDword())));
        if (av.length() - 1 > 2 && av[3]->GetInt() != 0) {
            double chanceToWin = Ship->ChanceToWin(Target);
            EC_Expression::TVarEC* cpp_arg = av[0];
            cpp_arg->SetFloat(chanceToWin);
        } else {
            std::int32_t winChancePercent = Ship->GetWinChancePercent(Target);
            EC_Expression::TVarEC* cpp_arg_2 = av[0];
            cpp_arg_2->SetInt(winChancePercent);
        }
    }

    void SF_ShipFind(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        std::uint8_t Kind{};
        aGalaxy::TStar* Star{};
        aShip::TShip* Ship{};
        std::int32_t I{};
        if (av.length() - 1 != 1) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script ShipFind"_a));
        }
        av[0]->SetDword(0u);
        if (aPlayer::GetPlayer() != nullptr) {
            Kind = av[1]->GetInt();
            Star = aPlayer::GetPlayer()->CurrentStar;
            for (auto cpp_range = pas::for_to<std::int32_t>(0, pas::list_count(Star->Ships) - 1); cpp_range.next(I); ) {
                Ship = pas::list_at<aShip::TShip>(Star->Ships, I);
                if (Ship->TypeId == Kind) {
                    av[0]->SetDword(static_cast<std::uint32_t>(reinterpret_cast<std::uintptr_t>(Ship)));
                    return;
                }
            }
        }
    }

    void SF_RangerStatus(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        if (av.length() - 1 < 1) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script RangerStatus"_a));
        }
        pas::Object* Obj = reinterpret_cast<pas::Object*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())));
        if (av.length() - 1 > 1) {
            if (av[2]->GetString() == u"EminentWarrior") {
                av[0]->SetInt(aGalaxy::Galaxy->EminentCareerShips[aGalaxyStruct::rcWarrior] == Obj);
            } else if (av[2]->GetString() == u"EminentTrader") {
                av[0]->SetInt(aGalaxy::Galaxy->EminentCareerShips[aGalaxyStruct::rcTrader] == Obj);
            } else if (av[2]->GetString() == u"EminentPirate") {
                av[0]->SetInt(aGalaxy::Galaxy->EminentCareerShips[aGalaxyStruct::rcPirate] == Obj);
            } else {
                pas::raise(pas::make_exception<pas::Exception>(static_cast<pas::AnsiString>(pas::concat_wide({u"Error.Script RangerStatus - unknown keyword ", av[2]->GetString()}))));
            }
        } else {
            if (!(pas::class_cast_if<aRanger::TRanger*>(Obj) != nullptr)) {
                pas::raise(pas::make_exception<pas::Exception>("Error.Script RangerStatus 2"_a));
            }
            av[0]->SetInt(pas::checked_cast<aRanger::TRanger*>(Obj)->GetDominantCareer());
        }
    }

