    void SF_BuyTransport(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        aTransport::TTransport* Ship{};
        std::uint8_t Kind{};
        if (av.length() - 1 < 1) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script BuyTransport"_a));
        }
        aPlanet::TPlanet* Planet = reinterpret_cast<aPlanet::TPlanet*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())));
        std::int32_t MoneyPercent = 100;
        if (av.length() - 1 > 2) {
            MoneyPercent = av[3]->GetInt();
        }
        if (Planet != nullptr) {
            if (av.length() - 1 > 1) {
                switch (av[2]->GetInt()) {
                    case 0: Kind = 3; break;
                    case 1: Kind = 4; break;
                    case 2: Kind = 5; break;
                    default: Kind = 0; break;
                }
            } else {
                Kind = 0;
            }
            Ship = static_cast<aTransport::TTransport*>(Planet->SpawnTransport(Kind, MoneyPercent));
            av[0]->SetDword(static_cast<std::uint32_t>(reinterpret_cast<std::uintptr_t>(Ship)));
        }
    }

