    void SF_DomikProgramm(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        std::uint8_t ProgramId{};
        std::int32_t Count{};
        if (av.length() - 1 < 1) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script DomikProgramm"_a));
        }
        aKling::TKling* Ship = reinterpret_cast<aKling::TKling*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())));
        av[0]->SetInt(Ship->ActiveProgramId);
        if (av.length() - 1 > 1) {
            ProgramId = av[2]->GetDword();
            Ship->ActiveProgramId = ProgramId;
            switch (ProgramId) {
                case aGalaxyStruct::prgShipwreck: {
                    if (av.length() - 1 > 2) {
                        Count = av[3]->GetInt();
                    } else {
                        Count = aMyFunction::SeededRandomIntRange(1, 3, aGalaxy::Galaxy->CurrentTurn);
                    }
                    Ship->DropItemsForDominatorProgram(Count);
                    break;
                }
                case aGalaxyStruct::prgSelfDestruction: Ship->DestroyQueued = true; break;
                case aGalaxyStruct::prgDisconnection: {
                    Ship->OrderNone(false);
                    Ship->ClearWeaponTargets(nullptr);
                    break;
                }
            }
        }
    }

