    void SF_HoleMamaCreate(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        std::int32_t I{};
        aEFilm::TEFilmObj* Film{};
        aGalaxy::THole* Hole = pas::construct_call<aGalaxy::THole>(aGalaxy::THole_Create);
        Hole->InitializeGraphic(pas::WideString());
        reinterpret_cast<SE_Hole::THoleSE*>(Hole->Graphic)->SetState(1);
        Hole->Star1 = aKling::BlazerShip->CurrentStar;
        Hole->Position1.X = static_cast<long double>(aKling::BlazerShip->Position.X) - aPlayer::GetPlayer()->Position.X;
        Hole->Position1.Y = static_cast<long double>(aKling::BlazerShip->Position.Y) - aPlayer::GetPlayer()->Position.Y;
        float Scale = pas::real_divide(1.0L, System::Sqrt(pas::sqr(static_cast<pas::Extended>(Hole->Position1.X)) + pas::sqr(static_cast<pas::Extended>(Hole->Position1.Y))));
        Hole->Position2.X = static_cast<long double>(Hole->Position1.X) * Scale;
        Hole->Position2.Y = static_cast<long double>(Hole->Position1.Y) * Scale;
        Hole->Position1.X = aKling::BlazerShip->Position.X + Hole->Position2.X * 2.0E+2L;
        Hole->Position1.Y = aKling::BlazerShip->Position.Y + Hole->Position2.Y * 2.0E+2L;
        Scale = System::Sqrt(pas::sqr(static_cast<pas::Extended>(Hole->Position1.X)) + pas::sqr(static_cast<pas::Extended>(Hole->Position1.Y)));
        if (Scale < aKling::BlazerShip->CurrentStar->SafeRadius) {
            Hole->Position1.X = aKling::BlazerShip->Position.X - Hole->Position2.Y * 2.0E+2L;
            Hole->Position1.Y = aKling::BlazerShip->Position.Y + Hole->Position2.X * 2.0E+2L;
            Scale = System::Sqrt(pas::sqr(static_cast<pas::Extended>(Hole->Position1.X)) + pas::sqr(static_cast<pas::Extended>(Hole->Position1.Y)));
            if (Scale < aKling::BlazerShip->CurrentStar->SafeRadius) {
                Hole->Position1.X = aKling::BlazerShip->Position.X + Hole->Position2.Y * 2.0E+2L;
                Hole->Position1.Y = aKling::BlazerShip->Position.Y - Hole->Position2.X * 2.0E+2L;
            }
        }
        Hole->Star2 = nullptr;
        float Angle = 1.0E+20f;
        for (auto cpp_range = pas::for_to<std::int32_t>(0, pas::list_count(aGalaxy::Galaxy->Stars) - 1); cpp_range.next(I); ) {
            Scale = aMyFunction::PointDistanceSquared(aKling::BlazerShip->CurrentStar->Position, pas::list_at<aGalaxy::TStar>(aGalaxy::Galaxy->Stars, I)->Position);
            if (Scale > 5.0L && Scale < Angle) {
                Angle = Scale;
                Hole->Star2 = pas::list_at<aGalaxy::TStar>(aGalaxy::Galaxy->Stars, I);
            }
        }
        Angle = aMyFunction::HeadingDegreesToRadians(aMyFunction::SeededRandomIntRange(0, 359, aGalaxy::Galaxy->RandomState));
        Scale = aMyFunction::SeededRandomIntRange(1000, 2000, aGalaxy::Galaxy->RandomState);
        {
            float cpp_arg = System::Sin(Angle) * Scale;
            float cpp_arg_2 = -System::Cos(Angle) * Scale;
            Hole->Position2 = EC_Struct::MakePointF(cpp_arg, cpp_arg_2);
        }
        Hole->CreatedTurn = aGalaxy::Galaxy->CurrentTurn;
        Hole->HoleType = 2;
        pas::list_add(aGalaxy::Galaxy->Holes, reinterpret_cast<void*>(Hole));
        if (Hole->Star1->RecordingTurnFilm || Hole->Star2->RecordingTurnFilm) {
            Film = Globals::PrimaryFilm->AddObject(Hole->Id, Hole->Graphic, 0, 0);
            Globals::PrimaryFilm->SetObjectPosition(0, Film, Hole->Position1);
            Globals::PrimaryFilm->SetHoleState(0, Film, 1);
            Globals::PrimaryFilm->AttachObject(0, Film);
        }
    }

    void SF_HoleCreate(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        aEFilm::TEFilmObj* Film{};
        if (av.length() - 1 != 2) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script HoleCreate"_a));
        }
        aGalaxy::THole* Hole = pas::construct_call<aGalaxy::THole>(aGalaxy::THole_Create);
        Hole->InitializeGraphic(pas::WideString());
        reinterpret_cast<SE_Hole::THoleSE*>(Hole->Graphic)->SetState(1);
        Hole->CreatedTurn = aGalaxy::Galaxy->CurrentTurn;
        Hole->HoleType = 1;
        aScript::TScriptPlace* Place = reinterpret_cast<aScript::TScriptPlace*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())));
        if (!pas::is_one_of<aScript::spkPolar, aScript::spkPlanetPosition, aScript::spkStarDirection, aScript::spkGroupCentroid, aScript::spkCoordinates>(Place->PlaceKind)) {
            GR_Main::RaiseWideMessage(u"Error.Script HoleCreate place 1"_wref.get());
        }
        Hole->Star1 = Place->OriginStar;
        float Angle = aMyFunction::HeadingDegreesToRadians(aMyFunction::SeededRandomIntRange(0, 359, Hole->Id * Hole->Star1->GenerationSeed));
        Hole->Position1 = Place->GetPoint();
        Hole->Position1.X = Hole->Position1.X + System::Sin(Angle) * Place->Radius;
        Hole->Position1.Y = Hole->Position1.Y - System::Cos(Angle) * Place->Radius;
        Place = reinterpret_cast<aScript::TScriptPlace*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[2]->GetDword())));
        if (!pas::is_one_of<aScript::spkPolar, aScript::spkPlanetPosition, aScript::spkStarDirection, aScript::spkGroupCentroid, aScript::spkCoordinates>(Place->PlaceKind)) {
            GR_Main::RaiseWideMessage(u"Error.Script HoleCreate place 2"_wref.get());
        }
        Hole->Star2 = Place->OriginStar;
        Angle = aMyFunction::HeadingDegreesToRadians(aMyFunction::SeededRandomIntRange(0, 359, Hole->Id * Hole->Star2->GenerationSeed));
        Hole->Position2 = Place->GetPoint();
        Hole->Position2.X = Hole->Position2.X + System::Sin(Angle) * Place->Radius;
        Hole->Position2.Y = Hole->Position2.Y - System::Cos(Angle) * Place->Radius;
        pas::list_add(aGalaxy::Galaxy->Holes, reinterpret_cast<void*>(Hole));
        if (Hole->Star1->RecordingTurnFilm || Hole->Star2->RecordingTurnFilm) {
            Film = Globals::PrimaryFilm->AddObject(Hole->Id, Hole->Graphic, 0, 0);
            Globals::PrimaryFilm->SetObjectPosition(0, Film, Hole->Position1);
            Globals::PrimaryFilm->SetHoleState(0, Film, 1);
            Globals::PrimaryFilm->AttachObject(0, Film);
        } else if (aPlayer::GetPlayer()->InNormalSpace() && (aPlayer::GetPlayer()->CurrentStar == Hole->Star1 || aPlayer::GetPlayer()->CurrentStar == Hole->Star2)) {
            Globals::StarMapScreen->PendingHoleRefresh = Hole;
        }
    }

