    void SF_CT(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        pas::WideString Text{};
        EC_BlockPar::TBlockParEC* Block{};
        if (av.length() - 1 < 1) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script CT"_a));
        }
        if (av.length() - 1 > 1) {
            if (av[2]->RealVType() == EC_Expression::vkEmpty) {
                av[2]->ConvertToKind(EC_Expression::vkArray);
                {
                    EC_Expression::TVarArrayEC* cpp_arg = pas::construct_call<EC_Expression::TVarArrayEC>(EC_Expression::TVarArrayEC_Create);
                    EC_Expression::TVarEC* cpp_arg_2 = av[2];
                    cpp_arg_2->SetArray(cpp_arg);
                }
            } else if (av[2]->RealVType() != EC_Expression::vkArray) {
                pas::raise(pas::make_exception<pas::Exception>("Error.Script CT - 2nd argument is not an array"_a));
            }
            av[2]->GetArray()->Clear();
            if (av[1]->GetString() == u"") {
                Block = GR_Main::LanguageDataConfig;
            } else {
                Block = ([&] {
                    const pas::WideString& string = av[1]->GetString();
                    EC_BlockPar::TBlockParEC* languageDataConfig = GR_Main::LanguageDataConfig;
                    return languageDataConfig->FindBlockByPath(string);
                }());
            }
            if (Block != nullptr) {
                aScriptFun::AddConfigBlock(Block, av[2]);
            }
            av[0]->SetInt(av[2]->GetArray()->Count);
            if (av[2]->GetArray()->Count == 0) {
                EC_Expression::TVarEC* cpp_arg_3 = pas::construct_call<EC_Expression::TVarEC>(EC_Expression::TVarEC_Create, EC_Expression::vkEmpty);
                EC_Expression::TVarArrayEC* array = av[2]->GetArray();
                array->AddItem(cpp_arg_3);
            }
        } else {
            Text = aConst::LocalizedColorText(av[1]->GetString());
            if (EC_Str::FindTextOffsetW(Text, u"<"_wref.get(), 0) >= 0) {
                Text = EC_Str::ReplaceAllWideString(Text, u"<br>"_wref.get(), u"\r\n"_wref.get());
                if (aPlayer::GetPlayer() != nullptr) {
                    Text = ([&] {
                        const pas::WideString& wrapTextInColor = aMyFunction::WrapTextInColor(aPlayer::GetPlayer()->GetFullName(u" "_wref.get()), u"<color=255,240,100>"_w);
                        const pas::WideString& text = Text;
                        return EC_Str::ReplaceAllWideString(text, u"<PlayerFull>"_wref.get(), wrapTextInColor);
                    }());
                }
            }
            av[0]->SetString(EC_Str::ReplaceAllWideString(Text, u"\r\n "_wref.get(), u"\r\n"_wref.get()));
        }
    }

    void SF_BlockExist(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        pas::WideString Path{};
        std::int32_t I{};
        EC_BlockPar::TBlockParEC* Block{};
        if (av.length() - 1 < 1) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script BlockExist"_a));
        }
        Path = av[1]->GetString();
        std::int32_t Count = EC_Str::CountDelimitedPartsW(Path, u"."_wref.get());
        if (av.length() - 1 < 2) {
            Block = GR_Main::LanguageDataConfig;
        } else if (av[2]->GetString() == u"Lang") {
            Block = GR_Main::LanguageDataConfig;
        } else if (av[2]->GetString() == u"Main") {
            Block = GR_Main::MainDataConfig;
        } else if (av[2]->GetString() == u"Config") {
            Block = GR_Main::UserSettingsConfig;
        } else {
            pas::raise(pas::make_exception<pas::Exception>(static_cast<pas::AnsiString>(pas::concat_wide({u"Error.Script BlockExist - unknown type ", av[2]->GetString()}))));
        }
        av[0]->SetInt(0);
        for (auto cpp_range = pas::for_to<std::int32_t>(0, Count - 1); cpp_range.next(I); ) {
            if (Block->CountBlocks(EC_Str::ExtractDelimitedPartW(Path, I, u"."_wref.get())) == 0) {
                return;
            }
            Block = Block->GetBlock(EC_Str::ExtractDelimitedPartW(Path, I, u"."_wref.get()));
        }
        av[0]->SetInt(1);
    }

