    void SF_TranclucatorData(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        aTranclucator::TTranclucator* Ship{};
        std::int32_t Kind{};
        if (av.length() - 1 < 2) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script SF_TranclucatorData"_a));
        }
        Ship = reinterpret_cast<aTranclucator::TTranclucator*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())));
        if (av[2]->RealVType() == EC_Expression::vkString) {
            if (av[2]->GetString() == u"Proprietor") {
                Kind = 0;
            } else if (av[2]->GetString() == u"ArtSize") {
                Kind = 1;
            } else if (av[2]->GetString() == u"ArtSysName") {
                Kind = 2;
            } else if (av[2]->GetString() == u"Docking") {
                Kind = 3;
            } else if (av[2]->GetString() == u"SeekItems") {
                Kind = 4;
            } else if (av[2]->GetString() == u"AutoArrange") {
                Kind = 5;
            } else if (av[2]->GetString() == u"LandStorage") {
                Kind = 6;
            } else if (av[2]->GetString() == u"LandPermitPlanets") {
                Kind = 7;
            } else if (av[2]->GetString() == u"LandPermitRuins") {
                Kind = 8;
            } else if (av[2]->GetString() == u"SeekPermitNone") {
                Kind = 9;
            } else if (av[2]->GetString() == u"SeekPermitArtefact") {
                Kind = 10;
            } else if (av[2]->GetString() == u"SeekPermitMicromodule") {
                Kind = 11;
            } else if (av[2]->GetString() == u"SeekPermitEquipment") {
                Kind = 12;
            } else if (av[2]->GetString() == u"SeekPermitUseless") {
                Kind = 13;
            } else if (av[2]->GetString() == u"SeekPermitGoods") {
                Kind = 14;
            } else if (av[2]->GetString() == u"SeekPermitNode") {
                Kind = 15;
            } else {
                pas::raise(pas::make_exception<pas::Exception>(static_cast<pas::AnsiString>(pas::concat_wide({u"Error.Script SF_TranclucatorData - unknown property ", av[2]->GetString()}))));
            }
        } else {
            Kind = av[2]->GetInt();
        }
        std::uint8_t WriteValue = av.length() - 1 > 2;
        switch (Kind) {
            case 0: {
                av[0]->SetDword(static_cast<std::uint32_t>(reinterpret_cast<std::uintptr_t>(Ship->OwnerShip)));
                if (WriteValue) {
                    Ship->OwnerShip = reinterpret_cast<aShip::TShip*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[3]->GetDword())));
                }
                break;
            }
            case 1: {
                av[0]->SetInt(Ship->ArtefactSize);
                if (WriteValue) {
                    Ship->ArtefactSize = av[3]->GetInt();
                }
                break;
            }
            case 2: {
                av[0]->SetString(Ship->ArtefactSystemName);
                if (WriteValue) {
                    Ship->ArtefactSystemName = av[3]->GetString();
                }
                break;
            }
            case 3: {
                av[0]->SetInt(Ship->FollowOwner);
                if (WriteValue) {
                    Ship->FollowOwner = av[3]->GetInt() != 0;
                }
                break;
            }
            case 4: {
                av[0]->SetInt(Ship->SeekItems);
                if (WriteValue) {
                    Ship->SeekItems = av[3]->GetInt() != 0;
                }
                break;
            }
            case 5: {
                av[0]->SetInt(Ship->AutoArrange);
                if (WriteValue) {
                    Ship->AutoArrange = av[3]->GetInt() != 0;
                }
                break;
            }
            case 6: {
                av[0]->SetInt(Ship->StoreOnLanding);
                if (WriteValue) {
                    Ship->StoreOnLanding = av[3]->GetInt() != 0;
                }
                break;
            }
            case 7: {
                av[0]->SetInt(Ship->StoragePermissions[1]);
                if (WriteValue) {
                    Ship->StoragePermissions[1] = av[3]->GetInt() != 0;
                }
                break;
            }
            case 8: {
                av[0]->SetInt(Ship->StoragePermissions[2]);
                if (WriteValue) {
                    Ship->StoragePermissions[2] = av[3]->GetInt() != 0;
                }
                break;
            }
            case 9: {
                av[0]->SetInt(Ship->CollectionPermissions[0]);
                if (WriteValue) {
                    Ship->CollectionPermissions[0] = av[3]->GetInt() != 0;
                }
                break;
            }
            case 10: {
                av[0]->SetInt(Ship->CollectionPermissions[1]);
                if (WriteValue) {
                    Ship->CollectionPermissions[1] = av[3]->GetInt() != 0;
                }
                break;
            }
            case 11: {
                av[0]->SetInt(Ship->CollectionPermissions[2]);
                if (WriteValue) {
                    Ship->CollectionPermissions[2] = av[3]->GetInt() != 0;
                }
                break;
            }
            case 12: {
                av[0]->SetInt(Ship->CollectionPermissions[3]);
                if (WriteValue) {
                    Ship->CollectionPermissions[3] = av[3]->GetInt() != 0;
                }
                break;
            }
            case 13: {
                av[0]->SetInt(Ship->CollectionPermissions[4]);
                if (WriteValue) {
                    Ship->CollectionPermissions[4] = av[3]->GetInt() != 0;
                }
                break;
            }
            case 14: {
                av[0]->SetInt(Ship->CollectionPermissions[5]);
                if (WriteValue) {
                    Ship->CollectionPermissions[5] = av[3]->GetInt() != 0;
                }
                break;
            }
            case 15: {
                av[0]->SetInt(Ship->CollectionPermissions[6]);
                if (WriteValue) {
                    Ship->CollectionPermissions[6] = av[3]->GetInt() != 0;
                }
                break;
            }
            default: {
                pas::raise(pas::make_exception<pas::Exception>(static_cast<pas::AnsiString>(pas::concat_wide({u"Error.Script SF_TranclucatorData - unknown property ", EC_Str::IntToWideString(Kind)}))));
            }
        }
    }

    void SF_LinkItemToScript(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        aScript::TScriptItem* Binding{};
        std::int32_t I{};
        if (av.length() - 1 < 1) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script SF_LinkItemToScript"_a));
        }
        aItem::TItem* Item = reinterpret_cast<aItem::TItem*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())));
        if (Item->ScriptItem != nullptr) {
            pas::checked_cast<aScript::TScriptItem*>(Item->ScriptItem)->Item = nullptr;
        }
        if (av.length() - 1 < 2) {
            if (aScript::CurrentScript == nullptr) {
                pas::raise(pas::make_exception<pas::Exception>("Error.Script SF_LinkItemToScript - no script"_a));
            }
            Binding = nullptr;
            for (auto cpp_range = pas::for_to<std::int32_t>(0, pas::list_count(aScript::CurrentScript->Items) - 1); cpp_range.next(I); ) {
                Binding = pas::list_at<aScript::TScriptItem>(aScript::CurrentScript->Items, I);
                if (Binding->Name == u"" && Binding->Item == nullptr) {
                    break;
                }
                Binding = nullptr;
            }
            if (Binding == nullptr) {
                Binding = pas::construct_call<aScript::TScriptItem>(aScript::TScriptItem_Create);
                Binding->Script = aScript::CurrentScript;
                pas::list_add(aScript::CurrentScript->Items, reinterpret_cast<void*>(Binding));
            }
            if (Binding->ActionCode != nullptr) {
                pas::free(Binding->ActionCode);
            }
            Binding->ActionCode = nullptr;
            Binding->ActionCodeInitialized = false;
            Binding->OnActionText = pas::WideString();
            Binding->CanSell = true;
        } else {
            Binding = reinterpret_cast<aScript::TScriptItem*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[2]->GetDword())));
        }
        if (Binding->Item != nullptr) {
            Binding->Item->ScriptItem = nullptr;
        }
        Binding->Item = Item;
        Item->ScriptItem = Binding;
    }

