    void SF_RaisePirateRank(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        std::uint32_t Rank{};
        if (av.length() - 1 < 1) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script RaisePirateRank"_a));
        }
        aNormalShip::TNormalShip* Ship = reinterpret_cast<aNormalShip::TNormalShip*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())));
        if (av.length() - 1 > 1) {
            Ship->PirateRank = av[2]->GetInt();
        } else {
            Rank = Ship->PirateRank;
            if (Rank < 7) {
                Ship->PirateRank = Rank + 1;
            }
        }
        if (aPlayer::GetPlayer() == Ship) {
            static_cast<void>(aPlayer::GetPlayer()->AchievementStats), Achievements::TAchievementStats::CheckBaronAchievement();
        }
    }

