    void SF_DropItemInSystem(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        aItem::TItem* Item{};
        EC_Struct::TPointF Destination{};
        EC_Struct::TPointF Position{};
        aGalaxy::PMovingDropItemEntry Entry{};
        std::int32_t StepIndex{};
        if (av.length() - 1 < 4) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script DropItemInSystem"_a));
        }
        aGalaxy::TStar* Star = reinterpret_cast<aGalaxy::TStar*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())));
        pas::Object* Obj = reinterpret_cast<pas::Object*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[2]->GetDword())));
        if (pas::class_cast_if<aScript::TScriptItem*>(Obj) != nullptr) {
            Item = reinterpret_cast<aScript::TScriptItem*>(Obj)->Item;
        } else {
            Item = reinterpret_cast<aItem::TItem*>(Obj);
        }
        Position.X = av[3]->GetInt();
        Position.Y = av[4]->GetInt();
        if (av.length() - 1 < 6) {
            Item->Position = Position;
            pas::list_add(Star->Items, reinterpret_cast<void*>(Item));
            if (Star->RecordingTurnFilm) {
                StepIndex = Star->CurrentStepIndex;
                {
                    SE_Space::TObjectSE* graphObject = Item->GetGraphObject();
                    std::uint32_t id = Item->Id;
                    aEFilm::TEFilm* primaryFilm = Globals::PrimaryFilm;
                    Item->FilmObject = primaryFilm->AddObject(id, graphObject, 0, 0);
                }
                Globals::PrimaryFilm->SetObjectPosition(StepIndex, Item->FilmObject, Item->Position);
                Globals::PrimaryFilm->AttachObject(StepIndex, Item->FilmObject);
            }
        } else {
            Destination.X = av[5]->GetFloat();
            Destination.Y = av[6]->GetFloat();
            av[0]->SetInt(0);
            if (Star != nullptr && Item != nullptr) {
                Item->Position = Position;
                Entry = static_cast<aGalaxy::PMovingDropItemEntry>(EC_Mem::AllocEC(static_cast<std::int32_t>(sizeof(aGalaxy::TMovingDropItemEntry))));
                Entry->Payload = Item;
                pas::store_unaligned<EC_Struct::TPointF>(&Entry->Destination, Destination);
                Entry->SourceShipId = 0;
                Entry->InsertedIntoStar = false;
                Entry->UseFlag = 0;
                {
                    std::int32_t cpp_arg = pas::list_add(Star->MovingDropItems, static_cast<void*>(Entry));
                    EC_Expression::TVarEC* cpp_arg_2 = av[0];
                    cpp_arg_2->SetInt(cpp_arg);
                }
            }
        }
    }

    void SF_StopMovingItem(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        aItem::TItem* Item{};
        aGalaxy::PMovingDropItemEntry Entry{};
        std::int32_t Index{};
        std::int32_t StepIndex{};
        if (av.length() - 1 < 2) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script StopMovingItem"_a));
        }
        aGalaxy::TStar* Star = reinterpret_cast<aGalaxy::TStar*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())));
        pas::Object* Obj = reinterpret_cast<pas::Object*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[2]->GetDword())));
        if (pas::class_cast_if<aScript::TScriptItem*>(Obj) != nullptr) {
            Item = reinterpret_cast<aScript::TScriptItem*>(Obj)->Item;
        } else {
            Item = reinterpret_cast<aItem::TItem*>(Obj);
        }
        av[0]->SetInt(0);
        for (auto cpp_range = pas::for_to<std::int32_t>(0, pas::list_count(Star->MovingDropItems) - 1); cpp_range.next(Index); ) {
            Entry = pas::list_at<aGalaxy::TMovingDropItemEntry>(Star->MovingDropItems, Index);
            if (Entry->Payload == Item) {
                Entry->Payload = nullptr;
                pas::list_delete(Star->MovingDropItems, Index);
                EC_Mem::FreeEC(Entry);
                pas::list_add(Star->Items, reinterpret_cast<void*>(Item));
                if (Star->RecordingTurnFilm) {
                    StepIndex = Star->CurrentStepIndex;
                    {
                        SE_Space::TObjectSE* graphObject = Item->GetGraphObject();
                        std::uint32_t id = Item->Id;
                        aEFilm::TEFilm* primaryFilm = Globals::PrimaryFilm;
                        Item->FilmObject = primaryFilm->AddObject(id, graphObject, 0, 0);
                    }
                    Globals::PrimaryFilm->SetObjectPosition(StepIndex, Item->FilmObject, Item->Position);
                    Globals::PrimaryFilm->AttachObject(StepIndex, Item->FilmObject);
                }
                av[0]->SetInt(1);
                break;
            }
        }
    }

