    void SF_ShopItems(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        std::int32_t Wanted{};
        std::int32_t Index{};
        std::int32_t Count{};
        pas::List* Items{};
        if (av.length() - 1 < 1) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script ShopItems"_a));
        }
        pas::Object* Shop = reinterpret_cast<pas::Object*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())));
        if (Shop == nullptr) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script ShopItems shop=nil"_a));
        }
        if (pas::class_cast_if<aPlanet::TPlanet*>(Shop) != nullptr) {
            Items = reinterpret_cast<aPlanet::TPlanet*>(Shop)->EquipmentShop;
        } else if (pas::class_cast_if<aRuins::TRuins*>(Shop) != nullptr) {
            Items = reinterpret_cast<aRuins::TRuins*>(Shop)->EquipmentShop;
        } else {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script ShopItems obj not a shop"_a));
        }
        if (av.length() - 1 == 1) {
            Count = 0;
            if (fEquipmentShop::TemporaryShopSlots != nullptr && (aPlayer::GetPlayer()->CurrentPlanet == Shop || aPlayer::GetPlayer()->DockedTo == Shop)) {
                for (auto cpp_range = pas::for_to<std::int32_t>(0, pas::list_count(fEquipmentShop::TemporaryShopSlots) - 1); cpp_range.next(Index); ) {
                    if (pas::list_get(fEquipmentShop::TemporaryShopSlots, Index) != nullptr) {
                        if (pas::list_at<fEquipmentShop::TShopSlot>(fEquipmentShop::TemporaryShopSlots, Index)->Item != nullptr) {
                            ++Count;
                        }
                    }
                }
            } else {
                for (auto cpp_range_2 = pas::for_to<std::int32_t>(0, pas::list_count(Items) - 1); cpp_range_2.next(Index); ) {
                    if (pas::list_get(Items, Index) != nullptr) {
                        ++Count;
                    }
                }
            }
            av[0]->SetInt(Count);
        } else {
            Wanted = av[2]->GetInt();
            av[0]->SetDword(0u);
            if (fEquipmentShop::TemporaryShopSlots != nullptr && (aPlayer::GetPlayer()->CurrentPlanet == Shop || aPlayer::GetPlayer()->DockedTo == Shop)) {
                Count = -1;
                for (auto cpp_range_3 = pas::for_to<std::int32_t>(0, pas::list_count(fEquipmentShop::TemporaryShopSlots) - 1); cpp_range_3.next(Index); ) {
                    if (pas::list_get(fEquipmentShop::TemporaryShopSlots, Index) != nullptr) {
                        if (pas::list_at<fEquipmentShop::TShopSlot>(fEquipmentShop::TemporaryShopSlots, Index)->Item != nullptr) {
                            ++Count;
                            if (Count == Wanted) {
                                av[0]->SetDword(static_cast<std::uint32_t>(reinterpret_cast<std::uintptr_t>(pas::list_at<fEquipmentShop::TShopSlot>(fEquipmentShop::TemporaryShopSlots, Index)->Item)));
                                break;
                            }
                        }
                    }
                }
            } else if (Wanted >= 0 && Wanted < pas::list_count(Items)) {
                av[0]->SetDword(static_cast<std::uint32_t>(reinterpret_cast<std::uintptr_t>(pas::list_get(Items, Wanted))));
            }
        }
    }

    void SF_AddDialogOverride(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        aScript::PScriptDialogOverride Entry{};
        pas::WideString DialogName{};
        std::int32_t Index{};
        if (av.length() - 1 < 2) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script AddDialogOverride"_a));
        }
        DialogName = av[1]->GetString();
        if (EC_Str::CountDelimitedPartsW(DialogName, u":"_wref.get()) > 1) {
            Index = Globals::FindScriptTemplateIndex(EC_Str::ExtractDelimitedPartW(DialogName, 0, u":"_wref.get()));
            if (Index < 0) {
                return;
            }
            Index = pas::list_at<Globals::TScriptTemplUnit>(Globals::ScriptTemplates, Index)->ActiveScriptIndex;
            if (Index < 0) {
                return;
            }
            pas::new_value(Entry);
            Entry->Script = pas::list_at<aScript::TScript>(aGalaxy::Galaxy->Scripts, Index);
            Entry->DialogName = EC_Str::ExtractDelimitedPartW(DialogName, 1, u":"_wref.get());
        } else {
            pas::new_value(Entry);
            Entry->Script = aScript::CurrentScript;
            Entry->DialogName = DialogName;
        }
        Entry->Priority = av[2]->GetInt();
        if (av.length() - 1 > 2) {
            Entry->AnswerData = av[3]->GetDword();
        } else {
            Entry->AnswerData = 0u;
        }
        if (aScript::ScriptDialogOverrides == nullptr) {
            aScript::ScriptDialogOverrides = pas::make_object<aMyFunction::TObjectList>();
        }
        pas::list_add(aScript::ScriptDialogOverrides, static_cast<void*>(Entry));
    }

