    void SF_InjectAnswer(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        pas::WideString Text{};
        pas::WideString Mode{};
        std::int32_t Index{};
        aScript::PScriptDialogInjection Entry{};
        if (av.length() - 1 < 3) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script InjectAnswer"_a));
        }
        Text = av[1]->GetString();
        if (EC_Str::CountDelimitedPartsW(Text, u":"_wref.get()) > 1) {
            Index = Globals::FindScriptTemplateIndex(EC_Str::ExtractDelimitedPartW(Text, 0, u":"_wref.get()));
            if (Index < 0) {
                return;
            }
            Index = pas::list_at<Globals::TScriptTemplUnit>(Globals::ScriptTemplates, Index)->ActiveScriptIndex;
            if (Index < 0) {
                return;
            }
            pas::new_value(Entry);
            Entry->Script = pas::list_at<aScript::TScript>(aGalaxy::Galaxy->Scripts, Index);
            Entry->DialogName = EC_Str::ExtractDelimitedPartW(Text, 1, u":"_wref.get());
        } else {
            pas::new_value(Entry);
            Entry->Script = aScript::CurrentScript;
            Entry->DialogName = Text;
        }
        Entry->Text = pas::WideString();
        Entry->Answer = av[2]->GetString();
        Entry->Priority = 0;
        Entry->AnswerData = av[3]->GetDword();
        Entry->ReplaceGreeting = false;
        if (av.length() - 1 > 3) {
            Entry->ActionCode = av[4]->GetString();
            Entry->ActionScript = aScript::CurrentScript;
        } else {
            Entry->ActionCode = pas::WideString();
            Entry->ActionScript = nullptr;
        }
        if (aScript::ScriptDialogInjections == nullptr) {
            aScript::ScriptDialogInjections = pas::make_object<aMyFunction::TObjectList>();
        }
        pas::list_add(aScript::ScriptDialogInjections, static_cast<void*>(Entry));
        Text = Entry->Answer;
        std::int32_t Count = EC_Str::CountDelimitedPartsW(Text, u"~"_wref.get());
        if (Count > 1) {
            Mode = EC_Str::ExtractDelimitedPartW(Text, 0, u"~"_wref.get());
            Text = EC_Str::ExtractDelimitedRangeW(Text, 1, Count - 1, u"~"_wref.get());
        }
        if (aPlayer::GetPlayer()->IsDockedToShip()) {
            if (Mode == u"block") {
                Globals::RuinsTalkScreen->AddChoice(Text, 0, fTalk::ScriptDialogBlockCallback);
            } else if (Mode == u"snap") {
                Globals::RuinsTalkScreen->AddChoice(Text, static_cast<std::int32_t>(reinterpret_cast<std::uintptr_t>(Entry)), pas::bind_method<&fRuinsTalk::TfRuinsTalk::RunInjectedDialogKeepingScroll>(Globals::RuinsTalkScreen));
            } else {
                Globals::RuinsTalkScreen->AddChoice(Entry->Answer, static_cast<std::int32_t>(reinterpret_cast<std::uintptr_t>(Entry)), pas::bind_method<&fRuinsTalk::TfRuinsTalk::RunInjectedDialog>(Globals::RuinsTalkScreen));
            }
        } else if (aPlayer::GetPlayer()->IsOnPlanet()) {
            if (Mode == u"block") {
                Globals::GovernmentScreen->AddChoice(Text, 0, fTalk::ScriptDialogBlockCallback);
            } else if (Mode == u"snap") {
                Globals::GovernmentScreen->AddChoice(Text, static_cast<std::int32_t>(reinterpret_cast<std::uintptr_t>(Entry)), pas::bind_method<&fGov::TfGov::RunInjectedAnswerKeepingScroll>(Globals::GovernmentScreen));
            } else {
                Globals::GovernmentScreen->AddChoice(Entry->Answer, static_cast<std::int32_t>(reinterpret_cast<std::uintptr_t>(Entry)), pas::bind_method<&fGov::TfGov::RunInjectedAnswer>(Globals::GovernmentScreen));
            }
        } else if (Mode == u"block") {
            Globals::TalkScreen->AddChoice(Text, 0, fTalk::ScriptDialogBlockCallback, 0);
        } else if (Mode == u"snap") {
            Globals::TalkScreen->AddChoice(Text, static_cast<std::int32_t>(reinterpret_cast<std::uintptr_t>(Entry)), pas::bind_method<&fTalk::TfTalk::RunInjectedAnswerKeepingScroll>(Globals::TalkScreen), 0);
        } else {
            Globals::TalkScreen->AddChoice(Entry->Answer, static_cast<std::int32_t>(reinterpret_cast<std::uintptr_t>(Entry)), pas::bind_method<&fTalk::TfTalk::RunInjectedAnswer>(Globals::TalkScreen), 0);
        }
    }

    void SF_AddDialogBlock(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        aScript::PScriptDialogBlock Entry{};
        std::int32_t I{};
        if (av.length() - 1 < 1) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script AddDialogBlock"_a));
        }
        if (aScript::ScriptDialogBlocks == nullptr) {
            aScript::ScriptDialogBlocks = pas::make_object<aMyFunction::TObjectList>();
        }
        for (auto cpp_range = pas::for_to<std::int32_t>(0, pas::list_count(aScript::ScriptDialogBlocks) - 1); cpp_range.next(I); ) {
            Entry = pas::list_at<aScript::TDialogBlock>(aScript::ScriptDialogBlocks, I);
            if (Entry->Script == aScript::CurrentScript && ([&] {
                pas::WideString cpp_string = av[1]->GetString();
                return Entry->Text == cpp_string;
            }())) {
                if (av.length() - 1 > 1) {
                    Entry->Mode = av[2]->GetInt();
                } else {
                    Entry->Mode = 2;
                }
                return;
            }
        }
        pas::new_value(Entry);
        Entry->Text = av[1]->GetString();
        Entry->Script = aScript::CurrentScript;
        if (av.length() - 1 > 1) {
            Entry->Mode = av[2]->GetInt();
        } else {
            Entry->Mode = 2;
        }
        pas::list_add(aScript::ScriptDialogBlocks, static_cast<void*>(Entry));
    }

