    void SF_TransferShip(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        pas::Object* Destination{};
        aGalaxy::TStar* OldStar{};
        aGalaxy::TStar* NewStar{};
        aPlanet::TPlanet* Planet{};
        aShip::TShip* Station{};
        std::int32_t Index{};
        if (av.length() - 1 < 2) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script TransferShip"_a));
        }
        aShip::TShip* Ship = reinterpret_cast<aShip::TShip*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())));
        if (Ship != nullptr) {
            OldStar = Ship->CurrentStar;
            if (OldStar != nullptr) {
                Destination = reinterpret_cast<pas::Object*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[2]->GetDword())));
                if (Destination != nullptr) {
                    if (!(pas::class_cast_if<aGalaxy::TStar*>(Destination) != nullptr) && !(pas::class_cast_if<aPlanet::TPlanet*>(Destination) != nullptr) && !(pas::class_cast_if<aShip::TShip*>(Destination) != nullptr)) {
                        pas::raise(pas::make_exception<pas::Exception>("Error.Script TransferShip - invalid destination"_a));
                    }
                    Planet = nullptr;
                    Station = nullptr;
                    if (pas::class_cast_if<aPlanet::TPlanet*>(Destination) != nullptr) {
                        Planet = reinterpret_cast<aPlanet::TPlanet*>(Destination);
                        NewStar = Planet->CurrentStar;
                    } else if (pas::class_cast_if<aShip::TShip*>(Destination) != nullptr) {
                        Station = reinterpret_cast<aShip::TShip*>(Destination);
                        NewStar = Station->CurrentStar;
                    } else {
                        NewStar = reinterpret_cast<aGalaxy::TStar*>(Destination);
                    }
                    Index = pas::list_indexof(OldStar->Ships, reinterpret_cast<void*>(Ship));
                    if (Index >= 0 && pas::list_count(OldStar->Ships) > Index) {
                        pas::list_delete(OldStar->Ships, Index);
                    }
                    pas::list_add(NewStar->Ships, reinterpret_cast<void*>(Ship));
                    Ship->CurrentStar = NewStar;
                    if (Ship->CurrentPlanet != nullptr) {
                        if (pas::class_cast_if<aNormalShip::TNormalShip*>(Ship) != nullptr) {
                            pas::checked_cast<aNormalShip::TNormalShip*>(Ship)->LastDockedPlanet = Ship->CurrentPlanet;
                        }
                    } else if (Ship->DockedTo != nullptr && pas::class_cast_if<aRanger::TRanger*>(Ship) != nullptr) {
                        pas::checked_cast<aRanger::TRanger*>(Ship)->LastDockedNonPlanetLocation = Ship->DockedTo;
                    }
                    if (aPlayer::GetPlayer() == Ship && fEquipmentShop::TemporaryShopSlots != nullptr) {
                        fEquipmentShop::RestoreTemporaryShopStock();
                    }
                    Ship->CurrentPlanet = Planet;
                    Ship->DockedTo = Station;
                    Ship->Order = aShip::soNone;
                    Ship->OrderStateData = 0;
                    Ship->OrderTarget = nullptr;
                    Ship->OrderDestination.X = 0.0f;
                    Ship->OrderDestination.Y = 0.0f;
                    Ship->OrderAbsolute = false;
                    Ship->InHyperspace = false;
                    if (aPlayer::GetPlayer() == Ship) {
                        if (aPlayer::GetPlayer()->IsDocked()) {
                            fEquipmentShop::BuildTemporaryShopSlotGrid();
                            Globals::EquipmentShopScreen->ClearGoodsControls();
                            Globals::EquipmentShopScreen->BuildGoodsControls();
                        }
                    }
                }
            }
        }
    }

    void SF_OrderForsage(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        if (av.length() - 1 < 1) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script OrderForsage"_a));
        }
        aShip::TShip* Ship = reinterpret_cast<aShip::TShip*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())));
        av[0]->SetInt(0);
        if (Ship != nullptr) {
            if (Ship->AfterburnerActive) {
                av[0]->SetInt(1);
            }
            if (av.length() - 1 > 1) {
                if (av[2]->GetInt() != 0) {
                    Ship->AfterburnerActive = Ship->GetSlotCount(aConst::sskAfterburner) > 0 && Ship->IsEquipmentUsable(Ship->GetEngine());
                } else {
                    Ship->AfterburnerActive = false;
                }
                Ship->RefreshDerivedStats(true);
                if (aPlayer::GetPlayer() == Ship && Globals::GetInnermostScreenLoop() == Globals::StarMapScreen && Globals::StarMapScreen->Mode == fStarMap::smmOrders) {
                    Globals::StarMapScreen->ClearPathOverlay(true);
                    aPlayer::GetPlayer()->BuildOrderMovementPath(999999);
                    Globals::StarMapScreen->BuildShipPathOverlay(Ship, false, pas::WideString());
                }
            }
        }
    }

    void SF_OrderNone(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        std::uint8_t SavedOrderLock{};
        if (av.length() - 1 < 1) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script OrderNone"_a));
        }
        aShip::TShip* Ship = reinterpret_cast<aShip::TShip*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())));
        if (Ship != nullptr) {
            SavedOrderLock = Ship->AbsoluteScriptOrder;
            Ship->AbsoluteScriptOrder = 0;
            Ship->OrderNone(false);
            Ship->AbsoluteScriptOrder = SavedOrderLock;
            if (aPlayer::GetPlayer() == Ship) {
                aRanger::PendingPlayerFollowTarget = nullptr;
            }
            if (aPlayer::GetPlayer() == Ship && Globals::GetInnermostScreenLoop() == Globals::StarMapScreen && Globals::StarMapScreen->Mode == fStarMap::smmOrders) {
                Globals::StarMapScreen->ClearPathOverlay(true);
                Globals::StarMapScreen->BuildShipPathOverlay(Ship, false, pas::WideString());
            }
        }
    }

    void SF_OrderMove(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        std::uint8_t Absolute{};
        EC_Struct::TPointF Destination{};
        std::uint8_t SavedOrderLock{};
        if (av.length() - 1 < 2) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script OrderMove"_a));
        }
        aShip::TShip* Ship = reinterpret_cast<aShip::TShip*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())));
        if (Ship != nullptr) {
            SavedOrderLock = Ship->AbsoluteScriptOrder;
            Ship->AbsoluteScriptOrder = 0;
            if (av.length() - 1 > 2) {
                Absolute = false;
                if (av.length() - 1 > 3) {
                    Absolute = av[4]->GetInt() != 0;
                }
                Destination.X = av[2]->GetInt();
                Destination.Y = av[3]->GetInt();
                Ship->OrderMove(Destination, Absolute);
            } else if (av[2]->RealVType() == EC_Expression::vkDword && pas::class_cast_if<aScript::TScriptPlace*>(reinterpret_cast<pas::Object*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[2]->GetDword())))) != nullptr) {
                Absolute = false;
                if (av.length() - 1 > 2) {
                    Absolute = av[3]->GetInt() != 0;
                }
                Ship->OrderMove(reinterpret_cast<aScript::TScriptPlace*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[2]->GetDword())))->GetRandomPoint((Ship->Seed + Ship->CurrentStar->GenerationSeed) * static_cast<std::uint32_t>(aGalaxy::Galaxy->CurrentTurn)), Absolute);
            } else {
                pas::raise(pas::make_exception<pas::Exception>("Error.Script OrderMove invalid place"_a));
            }
            Ship->AbsoluteScriptOrder = SavedOrderLock;
            if (aPlayer::GetPlayer() == Ship) {
                aRanger::PendingPlayerFollowTarget = nullptr;
            }
            if (aPlayer::GetPlayer() == Ship && Globals::GetInnermostScreenLoop() == Globals::StarMapScreen && Globals::StarMapScreen->Mode == fStarMap::smmOrders) {
                Globals::StarMapScreen->ClearPathOverlay(true);
                Globals::StarMapScreen->BuildShipPathOverlay(Ship, false, pas::WideString());
            }
        }
    }

    void SF_OrderTeleport(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        EC_Struct::TPointF Destination{};
        std::uint8_t SavedOrderLock{};
        aShip::TShip* Ship{};
        if (av.length() - 1 < 4) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script OrderTeleport"_a));
        }
        std::uint8_t Absolute = false;
        if (av.length() - 1 > 4) {
            Absolute = av[5]->GetInt() != 0;
        }
        Destination.X = av[3]->GetInt();
        Destination.Y = av[4]->GetInt();
        std::int32_t TransitionData = 10;
        if (av.length() - 1 > 5) {
            TransitionData = av[6]->GetInt();
        }
        if (av[1]->GetDword() != 0) {
            if (av[2]->GetDword() != 0) {
                Ship = reinterpret_cast<aShip::TShip*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())));
                if (Ship != nullptr) {
                    SavedOrderLock = Ship->AbsoluteScriptOrder;
                    Ship->AbsoluteScriptOrder = 0;
                    Ship->OrderTeleport(reinterpret_cast<aGalaxy::TStar*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[2]->GetDword()))), Destination, TransitionData, Absolute);
                    Ship->AbsoluteScriptOrder = SavedOrderLock;
                    if (aPlayer::GetPlayer() == Ship) {
                        aRanger::PendingPlayerFollowTarget = nullptr;
                    }
                    if (aPlayer::GetPlayer() == Ship && Globals::GetInnermostScreenLoop() == Globals::StarMapScreen && Globals::StarMapScreen->Mode == fStarMap::smmOrders) {
                        Globals::StarMapScreen->ClearPathOverlay(true);
                        Globals::StarMapScreen->BuildShipPathOverlay(Ship, false, pas::WideString());
                    }
                }
            }
        }
    }

