    void SF_StarHoles(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        aGalaxy::THole* Hole{};
        std::int32_t I{};
        if (av.length() - 1 < 1) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script StarSeries"_a));
        }
        aGalaxy::TStar* Star = reinterpret_cast<aGalaxy::TStar*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())));
        std::int32_t Wanted = -1;
        std::int32_t Found = -1;
        av[0]->SetDword(0u);
        if (av.length() - 1 > 1) {
            Wanted = av[2]->GetInt();
        }
        for (auto cpp_range = pas::for_to<std::int32_t>(0, pas::list_count(aGalaxy::Galaxy->Holes) - 1); cpp_range.next(I); ) {
            Hole = pas::list_at<aGalaxy::THole>(aGalaxy::Galaxy->Holes, I);
            if (Hole->Star1 == Star || Hole->Star2 == Star) {
                ++Found;
                if (Found == Wanted) {
                    av[0]->SetDword(static_cast<std::uint32_t>(reinterpret_cast<std::uintptr_t>(Hole)));
                    return;
                }
            }
        }
        if (av.length() - 1 == 1) {
            av[0]->SetInt(Found + 1);
        }
    }

