    void SF_StarSetGraph(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        aGalaxy::TStar* Star{};
        if (av.length() - 1 < 2) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script StarSetGraph"_a));
        }
        Star = reinterpret_cast<aGalaxy::TStar*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())));
        SE_Space::ReleaseSpaceObject(pas::Var<SE_Space::TObjectSE*>(&Star->Graphic));
        {
            SE_Space::TObjectSE* createSpaceObjectByName = SE_Process::CreateSpaceObjectByName(u"Star"_wref.get(), av[2]->GetString(), ClassesImports::Point(0, 0));
            pas::Var<SE_Space::TObjectSE*> graphic = pas::Var<SE_Space::TObjectSE*>(&Star->Graphic);
            SE_Space::RetainSpaceObject(graphic, createSpaceObjectByName);
        }
        Star->SystemProcessName = u"Process.Normal"_w;
        Star->Graphic->SetPosition(EC_Struct::MakePointF(0.0f, 0.0f));
    }

    void SF_CreatePlanet(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        std::int32_t I{};
        if (av.length() - 1 < 1) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script CreatePlanet"_a));
        }
        aGalaxy::TStar* Star = reinterpret_cast<aGalaxy::TStar*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())));
        aPlanet::TPlanet* Planet = pas::construct_call<aPlanet::TPlanet>(aPlanet::TPlanet_Create);
        Planet->InitGeneratedUninhabited(Star);
        pas::list_add(aGalaxy::Galaxy->Planets, reinterpret_cast<void*>(Planet));
        av[0]->SetDword(static_cast<std::uint32_t>(reinterpret_cast<std::uintptr_t>(Planet)));
        if (av.length() - 1 < 2) {
            pas::list_add(Star->Planets, reinterpret_cast<void*>(Planet));
        } else {
            Planet->Orbit.Radius = av[2]->GetInt();
            if (static_cast<aPlanet::TPlanet*>(pas::list_last(Star->Planets))->Orbit.Radius < Planet->Orbit.Radius) {
                pas::list_add(Star->Planets, reinterpret_cast<void*>(Planet));
            } else {
                for (auto cpp_range = pas::for_to<std::int32_t>(0, pas::list_count(Star->Planets) - 1); cpp_range.next(I); ) {
                    if (pas::list_at<aPlanet::TPlanet>(Star->Planets, I)->Orbit.Radius > Planet->Orbit.Radius) {
                        pas::list_insert(Star->Planets, I, reinterpret_cast<void*>(Planet));
                        return;
                    }
                }
            }
        }
    }

    void SF_PlanetSetGraph(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        aPlanet::TPlanet* Planet{};
        std::uint16_t RotationInterval{};
        if (av.length() - 1 < 2) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script PlanetSetGraph"_a));
        }
        Planet = reinterpret_cast<aPlanet::TPlanet*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())));
        if (av[2]->RealVType() == EC_Expression::vkString) {
            Planet->GraphName = av[2]->GetString();
            RotationInterval = Planet->Graphic->RotationTimerInterval;
            SE_Space::ReleaseSpaceObject(pas::Var<SE_Space::TObjectSE*>(&Planet->Graphic));
            {
                SE_Space::TObjectSE* createSpaceObjectByName = SE_Process::CreateSpaceObjectByName(u"Planet"_wref.get(), Planet->GraphName, ClassesImports::Point(0, 0));
                pas::Var<SE_Space::TObjectSE*> graphic = pas::Var<SE_Space::TObjectSE*>(&Planet->Graphic);
                SE_Space::RetainSpaceObject(graphic, createSpaceObjectByName);
            }
            Planet->Graphic->SetRotationTimerInterval(RotationInterval);
        } else {
            Planet->SpriteTemplateIndex = av[2]->GetInt();
            SE_Space::ReleaseSpaceObject(pas::Var<SE_Space::TObjectSE*>(&Planet->Graphic));
            {
                SE_Space::TObjectSE* cpp_arg = pas::construct_call<SE_Planet::TPlanetSE>(SE_Planet::TPlanetSE_Create);
                pas::Var<SE_Space::TObjectSE*> graphic_2 = pas::Var<SE_Space::TObjectSE*>(&Planet->Graphic);
                SE_Space::RetainSpaceObject(graphic_2, cpp_arg);
            }
            Globals::PlanetSpaceTemplates[Planet->SpriteTemplateIndex].SpaceObject->CopyTo(Planet->Graphic);
            Planet->GraphName = Planet->Graphic->GraphKey;
        }
        Planet->Graphic->SetPosition(aMyFunction::PolarToPoint(Planet->Orbit));
        Planet->GraphicRadius = Planet->Graphic->Radius;
    }

