    void SF_PlanetTerrain(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        std::int32_t I{};
        aPlanet::PPlanetSurfaceLootEntry Entry{};
        if (av.length() - 1 < 2) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script PlanetTerrain"_a));
        }
        aPlanet::TPlanet* Planet = reinterpret_cast<aPlanet::TPlanet*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())));
        aPlanet::TPlanetTerrainKind Terrain = static_cast<aPlanet::TPlanetTerrainKind>(av[2]->GetInt());
        switch (Terrain) {
            case aPlanet::ptWater: av[0]->SetInt(Planet->WaterTiles); break;
            case aPlanet::ptLand: av[0]->SetInt(Planet->LandTiles); break;
            case aPlanet::ptHill: av[0]->SetInt(Planet->HillTiles); break;
            default: pas::raise(pas::make_exception<pas::Exception>("Error.Script PlanetTerrain ttype"_a));
        }
        if (av.length() - 1 <= 2) {
            return;
        }
        std::int32_t Value = av[3]->GetInt();
        switch (Terrain) {
            case aPlanet::ptWater: Planet->WaterTiles = Value; break;
            case aPlanet::ptLand: Planet->LandTiles = Value; break;
            case aPlanet::ptHill: Planet->HillTiles = Value; break;
        }
        if (Planet->SurfaceLootEntries != nullptr) {
            for (auto cpp_range = pas::for_to<std::int32_t>(0, pas::list_count(Planet->SurfaceLootEntries) - 1); cpp_range.next(I); ) {
                Entry = pas::list_at<aPlanet::TPlanetSurfaceLootEntry>(Planet->SurfaceLootEntries, I);
                if (Entry->TerrainKind == Terrain) {
                    Entry->SurfaceTileIndex = std::min<std::int32_t>(Entry->SurfaceTileIndex, Value);
                }
            }
        }
    }

