        std::int32_t Total{};
        if (av.length() - 1 > 0) {
            av[0]->SetInt((aGalaxy::Galaxy->DifficultyLevels[av[1]->GetInt() & 0x0000007f] + 1) * 50);
        } else {
            Total = 0;
            for (I = 0; I <= 7; ++I) {
                Total += (aGalaxy::Galaxy->DifficultyLevels[static_cast<std::uint8_t>(I)] + 1) * 50;
            }
            av[0]->SetInt(System::Round(Total * 0.125L));
        }
