    void SF_ArraySort(pas::OpenArray<EC_Expression::TVarEC*> Args, EC_Expression::TCodeEC* Code) {
        auto cpp_array_copy = pas::copy_open_array(Args);
        Args = pas::open_array(cpp_array_copy);
        std::int32_t I{};
        std::int32_t ElementIndex{};
        std::int32_t ArrayIndex{};
        EC_Expression::TVarEC* SwapValue{};
        std::int32_t ArrayCount = Args.length() - 1;
        if (ArrayCount < 1) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script ArraySort"_a));
        }
        if (Args[1]->RealVType() != EC_Expression::vkArray) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script ArraySort - not array"_a));
        }
        std::int32_t ElementCount = Args[1]->GetArray()->Count;
        if (ElementCount < 2) {
            return;
        }
        if (ArrayCount > 1) {
            for (auto cpp_range = pas::for_to<std::int32_t>(2, ArrayCount); cpp_range.next(I); ) {
                if (Args[I]->RealVType() != EC_Expression::vkArray) {
                    pas::raise(pas::make_exception<pas::Exception>("Error.Script ArraySort - type mismatch"_a));
                }
                if (Args[I]->GetArray()->Count != ElementCount) {
                    pas::raise(pas::make_exception<pas::Exception>("Error.Script ArraySort - size mismatch"_a));
                }
            }
        }
        for (auto cpp_range_2 = pas::for_to<std::int32_t>(1, ElementCount - 1); cpp_range_2.next(I); ) {
            for (auto cpp_range_3 = pas::for_downto<std::int32_t>(ElementCount - 1, I); cpp_range_3.next(ElementIndex); ) {
                std::int32_t cpp_left = EC_Expression::TVarArrayEC_GetItem(Args[1]->GetArray(), ElementIndex)->GetInt();
                if (cpp_left < EC_Expression::TVarArrayEC_GetItem(Args[1]->GetArray(), ElementIndex - 1)->GetInt()) {
                    for (auto cpp_range_4 = pas::for_to<std::int32_t>(1, ArrayCount); cpp_range_4.next(ArrayIndex); ) {
                        SwapValue = EC_Expression::TVarArrayEC_GetItem(Args[ArrayIndex]->GetArray(), ElementIndex);
                        {
                            EC_Expression::TVarEC* item = EC_Expression::TVarArrayEC_GetItem(Args[ArrayIndex]->GetArray(), ElementIndex - 1);
                            EC_Expression::TVarArrayEC* array = Args[ArrayIndex]->GetArray();
                            EC_Expression::TVarArrayEC_SetItem(array, ElementIndex, item);
                        }
                        EC_Expression::TVarArrayEC_SetItem(Args[ArrayIndex]->GetArray(), ElementIndex - 1, SwapValue);
                    }
                }
            }
        }
    }

    void SF_ArraySortPartial(pas::OpenArray<EC_Expression::TVarEC*> Args, EC_Expression::TCodeEC* Code) {
        auto cpp_array_copy = pas::copy_open_array(Args);
        Args = pas::open_array(cpp_array_copy);
        std::int32_t I{};
        std::int32_t ElementIndex{};
        std::int32_t ArrayIndex{};
        EC_Expression::TVarEC* SwapValue{};
        std::int32_t ArrayCount = Args.length() - 1 - 1;
        if (ArrayCount < 1) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script ArraySortPartial"_a));
        }
        if (Args[2]->RealVType() != EC_Expression::vkArray) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script ArraySortPartial - not array"_a));
        }
        std::int32_t ElementCount = Args[2]->GetArray()->Count;
        std::int32_t MinIndex = Args[1]->GetInt();
        if (ElementCount < 2) {
            return;
        }
        if (ArrayCount > 1) {
            for (auto cpp_range = pas::for_to<std::int32_t>(2, ArrayCount); cpp_range.next(I); ) {
                if (Args[I + 1]->RealVType() != EC_Expression::vkArray) {
                    pas::raise(pas::make_exception<pas::Exception>("Error.Script ArraySortPartial - type mismatch"_a));
                }
                if (Args[I + 1]->GetArray()->Count != ElementCount) {
                    pas::raise(pas::make_exception<pas::Exception>("Error.Script ArraySortPartial - size mismatch"_a));
                }
            }
        }
        // Native operation: one backward adjacent-swap pass. MinIndex is unchecked;
        // each comparison also reads ElementIndex - 1.
        for (auto cpp_range_2 = pas::for_downto<std::int32_t>(ElementCount - 1, MinIndex); cpp_range_2.next(ElementIndex); ) {
            std::int32_t cpp_left = EC_Expression::TVarArrayEC_GetItem(Args[2]->GetArray(), ElementIndex)->GetInt();
            if (cpp_left < EC_Expression::TVarArrayEC_GetItem(Args[2]->GetArray(), ElementIndex - 1)->GetInt()) {
                for (auto cpp_range_3 = pas::for_to<std::int32_t>(1, ArrayCount); cpp_range_3.next(ArrayIndex); ) {
                    SwapValue = EC_Expression::TVarArrayEC_GetItem(Args[ArrayIndex + 1]->GetArray(), ElementIndex);
                    {
                        EC_Expression::TVarEC* item = EC_Expression::TVarArrayEC_GetItem(Args[ArrayIndex + 1]->GetArray(), ElementIndex - 1);
                        EC_Expression::TVarArrayEC* array = Args[ArrayIndex + 1]->GetArray();
                        EC_Expression::TVarArrayEC_SetItem(array, ElementIndex, item);
                    }
                    EC_Expression::TVarArrayEC_SetItem(Args[ArrayIndex + 1]->GetArray(), ElementIndex - 1, SwapValue);
                }
            }
        }
    }

    void SF_ArrayRandomize(pas::OpenArray<EC_Expression::TVarEC*> Args, EC_Expression::TCodeEC* Code) {
        auto cpp_array_copy = pas::copy_open_array(Args);
        Args = pas::open_array(cpp_array_copy);
        std::int32_t I{};
        std::int32_t SwapIndex1{};
        std::int32_t SwapIndex2{};
        std::int32_t ArrayArgIndex{};
        std::uint32_t Seed{};
        EC_Expression::TVarEC* SwapValue{};
        std::int32_t LastArgIndex = Args.length() - 1;
        if (LastArgIndex < 2) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script ArrayRandomize"_a));
        }
        if (Args[2]->RealVType() != EC_Expression::vkArray) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script ArrayRandomize - not array"_a));
        }
        std::int32_t ElementCount = Args[2]->GetArray()->Count;
        if (ElementCount < 2) {
            return;
        }
        std::int32_t SwapCount = Args[1]->GetInt();
        std::uint8_t HasSeed = false;
        if (Args[LastArgIndex]->RealVType() != EC_Expression::vkArray) {
            Seed = Args[LastArgIndex]->GetDword();
            HasSeed = true;
            --LastArgIndex;
        }
        for (auto cpp_range = pas::for_to<std::int32_t>(3, LastArgIndex); cpp_range.next(I); ) {
            if (Args[I]->RealVType() != EC_Expression::vkArray) {
                pas::raise(pas::make_exception<pas::Exception>("Error.Script ArrayRandomize - type mismatch"_a));
            }
            if (Args[I]->GetArray()->Count != ElementCount) {
                pas::raise(pas::make_exception<pas::Exception>("Error.Script ArrayRandomize - size mismatch"_a));
            }
        }
        for (auto cpp_range_2 = pas::for_to<std::int32_t>(1, SwapCount); cpp_range_2.next(I); ) {
            if (HasSeed) {
                SwapIndex1 = aMyFunction::NextRandomIntRange(0, ElementCount - 1, Seed);
                SwapIndex2 = aMyFunction::NextRandomIntRange(0, ElementCount - 1, Seed);
            } else if (aGalaxy::Galaxy == nullptr) {
                SwapIndex1 = aMyFunction::RandomIntRange(0, ElementCount - 1);
                SwapIndex2 = aMyFunction::RandomIntRange(0, ElementCount - 1);
            } else {
                SwapIndex1 = aMyFunction::NextRandomIntRange(0, ElementCount - 1, aGalaxy::Galaxy->RandomState);
                SwapIndex2 = aMyFunction::NextRandomIntRange(0, ElementCount - 1, aGalaxy::Galaxy->RandomState);
            }
            if (SwapIndex1 != SwapIndex2) {
                for (auto cpp_range_3 = pas::for_to<std::int32_t>(2, LastArgIndex); cpp_range_3.next(ArrayArgIndex); ) {
                    SwapValue = EC_Expression::TVarArrayEC_GetItem(Args[ArrayArgIndex]->GetArray(), SwapIndex1);
                    {
                        EC_Expression::TVarEC* item = EC_Expression::TVarArrayEC_GetItem(Args[ArrayArgIndex]->GetArray(), SwapIndex2);
                        EC_Expression::TVarArrayEC* array = Args[ArrayArgIndex]->GetArray();
                        EC_Expression::TVarArrayEC_SetItem(array, SwapIndex1, item);
                    }
                    EC_Expression::TVarArrayEC_SetItem(Args[ArrayArgIndex]->GetArray(), SwapIndex2, SwapValue);
                }
            }
        }
    }

    void SF_ArrayFind(pas::OpenArray<EC_Expression::TVarEC*> Args, EC_Expression::TCodeEC* Code) {
        auto cpp_array_copy = pas::copy_open_array(Args);
        Args = pas::open_array(cpp_array_copy);
        std::int32_t ElementIndex{};
        if (Args.length() - 1 < 2) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script ArrayFind"_a));
        }
        if (Args[1]->RealVType() != EC_Expression::vkArray) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script ArrayFind - not array"_a));
        }
        Args[0]->SetInt(-1);
        if (Args[2]->RealVType() == EC_Expression::vkInt) {
            for (auto cpp_range = pas::for_to<std::int32_t>(0, Args[1]->GetArray()->Count - 1); cpp_range.next(ElementIndex); ) {
                std::int32_t cpp_left = EC_Expression::TVarArrayEC_GetItem(Args[1]->GetArray(), ElementIndex)->GetInt();
                if (cpp_left == Args[2]->GetInt()) {
                    Args[0]->SetInt(ElementIndex);
                    return;
                }
            }
        } else if (Args[2]->RealVType() == EC_Expression::vkDword) {
            for (auto cpp_range_2 = pas::for_to<std::int32_t>(0, Args[1]->GetArray()->Count - 1); cpp_range_2.next(ElementIndex); ) {
                std::uint32_t cpp_left_2 = EC_Expression::TVarArrayEC_GetItem(Args[1]->GetArray(), ElementIndex)->GetDword();
                if (cpp_left_2 == Args[2]->GetDword()) {
                    Args[0]->SetInt(ElementIndex);
                    return;
                }
            }
        } else if (Args[2]->RealVType() == EC_Expression::vkString) {
            for (auto cpp_range_3 = pas::for_to<std::int32_t>(0, Args[1]->GetArray()->Count - 1); cpp_range_3.next(ElementIndex); ) {
                if (([&] {
                    pas::WideString cpp_string = EC_Expression::TVarArrayEC_GetItem(Args[1]->GetArray(), ElementIndex)->GetString();
                    pas::WideString cpp_string_2 = Args[2]->GetString();
                    return cpp_string == cpp_string_2;
                }())) {
                    Args[0]->SetInt(ElementIndex);
                    return;
                }
            }
        } else if (Args[2]->RealVType() == EC_Expression::vkFloat) {
            for (auto cpp_range_4 = pas::for_to<std::int32_t>(0, Args[1]->GetArray()->Count - 1); cpp_range_4.next(ElementIndex); ) {
                pas::Extended cpp_left_3 = EC_Expression::TVarArrayEC_GetItem(Args[1]->GetArray(), ElementIndex)->GetFloat();
                if (cpp_left_3 == Args[2]->GetFloat()) {
                    Args[0]->SetInt(ElementIndex);
                    return;
                }
            }
        }
    }

    void SF_ArrayFindInSorted(pas::OpenArray<EC_Expression::TVarEC*> Args, EC_Expression::TCodeEC* Code) {
        auto cpp_array_copy = pas::copy_open_array(Args);
        Args = pas::open_array(cpp_array_copy);
        std::int32_t ProbeValue{};
        std::int32_t Pass{};
        std::int32_t ScanDirection{};
        if (Args.length() - 1 < 2) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script ArrayFindInSorted"_a));
        }
        if (Args[1]->RealVType() != EC_Expression::vkArray) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script ArrayFindInSorted - not array"_a));
        }
        std::int32_t ProbeIndex = 0;
        std::int32_t ElementCount = Args[1]->GetArray()->Count;
        std::int32_t TargetValue = Args[2]->GetInt();
        std::int32_t LowIndex = 0;
        // The native search reads both endpoints without an empty-array check.
        std::int32_t LowValue = EC_Expression::TVarArrayEC_GetItem(Args[1]->GetArray(), 0)->GetInt();
        std::int32_t HighIndex = ElementCount - 1;
        std::int32_t HighValue = EC_Expression::TVarArrayEC_GetItem(Args[1]->GetArray(), ElementCount - 1)->GetInt();
        std::int32_t InterpolationPassCount = 3;
        if (TargetValue > HighValue || TargetValue < LowValue) {
            Args[0]->SetInt(-1);
            return;
        }
        if (TargetValue == HighValue) {
            Args[0]->SetInt(HighIndex);
            return;
        }
        if (TargetValue == LowValue) {
            Args[0]->SetInt(LowIndex);
            return;
        }
        if (HighValue == LowValue) {
            Args[0]->SetInt(-1);
            return;
        }
        for (auto cpp_range = pas::for_to<std::int32_t>(1, InterpolationPassCount); cpp_range.next(Pass); ) {
            ProbeIndex = System::Round(pas::real_divide((TargetValue - LowValue) * (HighIndex - LowIndex), HighValue - LowValue) + LowIndex);
            ProbeValue = EC_Expression::TVarArrayEC_GetItem(Args[1]->GetArray(), ProbeIndex)->GetInt();
            if (ProbeValue > TargetValue) {
                HighIndex = ProbeIndex;
                HighValue = ProbeValue;
            } else {
                LowIndex = ProbeIndex;
                LowValue = ProbeValue;
            }
            if (TargetValue == HighValue) {
                Args[0]->SetInt(HighIndex);
                return;
            }
            if (TargetValue == LowValue) {
                Args[0]->SetInt(LowIndex);
                return;
            }
            if (HighValue == LowValue) {
                Args[0]->SetInt(-1);
                return;
            }
        }
        if (ProbeIndex == HighIndex) {
            ScanDirection = -1;
        } else {
            ScanDirection = 1;
        }
        ProbeIndex += ScanDirection;
        ProbeValue = EC_Expression::TVarArrayEC_GetItem(Args[1]->GetArray(), ProbeIndex)->GetInt();
        while (ProbeValue != TargetValue && ProbeIndex < HighIndex && ProbeIndex > LowIndex && (TargetValue - ProbeValue) * ScanDirection > 0) {
            ProbeIndex += ScanDirection;
            ProbeValue = EC_Expression::TVarArrayEC_GetItem(Args[1]->GetArray(), ProbeIndex)->GetInt();
        }
        if (ProbeValue == TargetValue) {
            Args[0]->SetInt(ProbeIndex);
        } else {
            Args[0]->SetInt(-1);
        }
    }

    void SF_DistToNearestEnemySystem(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        aGalaxy::TStar* Other{};
        if (av.length() - 1 < 1) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script DistToNearestEnemySystem"_a));
        }
        aGalaxy::TStar* Star = reinterpret_cast<aGalaxy::TStar*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())));
        std::int32_t I = 0;
        while (I < pas::list_count(aGalaxy::Galaxy->Stars)) {
            Other = pas::checked_cast<aGalaxy::TStar*>(static_cast<pas::Object*>(Star->StarDistances[I].Star));
            if (Other->Status.ControlFaction == aGalaxyStruct::sfDominators || Other->Status.CustomFaction != u"") {
                break;
            }
            ++I;
        }
        if (I == pas::list_count(aGalaxy::Galaxy->Stars)) {
            av[0]->SetInt(-1);
        } else {
            av[0]->SetInt(Star->StarDistances[I].Distance);
        }
    }

    void SF_StarEnemyThreatLevel(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        aGalaxy::TStar* Other{};
        aShip::TShip* Ship{};
        std::int32_t I{};
        std::int32_t J{};
        aGalaxyStruct::TShipTypeMask Standings{};
        if (av.length() - 1 < 1) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script StarEnemyThreatLeve"_a));
        }
        aGalaxy::TStar* Star = reinterpret_cast<aGalaxy::TStar*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())));
        std::uint8_t IncludePirates = av.length() - 1 > 1 && av[2]->GetInt() == 1;
        if (Star == nullptr) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script StarEnemyThreatLevel"_a));
        }
        if (Star->Status.ControlFaction == aGalaxyStruct::sfDominators || Star->Status.CustomFaction != u"" || IncludePirates && Star->Status.ControlFaction == aGalaxyStruct::sfPirates) {
            av[0]->SetInt(3);
            return;
        }
        if (Star->Status.Battle != 0) {
            av[0]->SetInt(2);
            return;
        }
        if (aGalaxy::Galaxy->KellerTargetStar == Star) {
            av[0]->SetInt(1);
            return;
        }
        Standings = pas::constant_set<aGalaxyStruct::TShipTypeMask>({{aGalaxyStruct::ssDominator}, {aGalaxyStruct::ssCustom}});
        if (IncludePirates) {
            Standings = Standings + pas::constant_set<aGalaxyStruct::TShipTypeMask>({{aGalaxyStruct::ssPirateActive}, {aGalaxyStruct::ssPirateMilitary}});
        }
        for (auto cpp_range = pas::for_to<std::int32_t>(0, pas::list_count(Star->Ships) - 1); cpp_range.next(J); ) {
            Ship = pas::list_at<aShip::TShip>(Star->Ships, J);
            if ((Ship->CurrentPlanet == nullptr || Ship->CurrentPlanet->OwnerId != static_cast<std::uint8_t>(aGalaxyStruct::oiUninhabited)) && pas::contains(Standings, Ship->CurrentStanding)) {
                av[0]->SetInt(1);
                return;
            }
        }
        for (auto cpp_range_2 = pas::for_to<std::int32_t>(1, pas::list_count(aGalaxy::Galaxy->Stars) - 1); cpp_range_2.next(I); ) {
            Other = Star->StarDistances[I].Star;
            // Native code tests the original star's custom/pirate fields here.
            if (Other->Status.ControlFaction == aGalaxyStruct::sfDominators || Star->Status.CustomFaction != u"" || IncludePirates && Star->Status.ControlFaction == aGalaxyStruct::sfPirates) {
                for (auto cpp_range_3 = pas::for_to<std::int32_t>(0, pas::list_count(Other->Ships) - 1); cpp_range_3.next(J); ) {
                    Ship = pas::list_at<aShip::TShip>(Other->Ships, J);
                    if (Ship->OrderTarget == Star && pas::contains(Standings, Ship->CurrentStanding)) {
                        av[0]->SetInt(1);
                        return;
                    }
                    if (pas::class_cast_if<aRuins::TRuins*>(Ship) != nullptr && reinterpret_cast<aRuins::TRuins*>(Ship)->FlyToStar == Star && pas::contains(Standings, Ship->CurrentStanding)) {
                        av[0]->SetInt(1);
                        return;
                    }
                }
            }
        }
        av[0]->SetInt(0);
    }

    void SF_BuildListOfQuestPossibleLocations(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        std::int32_t J{};
        std::int32_t K{};
        aGalaxy::TStar* Candidate{};
        std::uint8_t Allowed{};
        EC_Expression::TVarEC* Value{};
        if (av.length() - 1 < 4) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script BuildListOfQuestPossibleLocations"_a));
        }
        if (av[1]->RealVType() == EC_Expression::vkEmpty) {
            av[1]->ConvertToKind(EC_Expression::vkArray);
            {
                EC_Expression::TVarArrayEC* cpp_arg = pas::construct_call<EC_Expression::TVarArrayEC>(EC_Expression::TVarArrayEC_Create);
                EC_Expression::TVarEC* cpp_arg_2 = av[1];
                cpp_arg_2->SetArray(cpp_arg);
            }
        } else if (av[1]->RealVType() != EC_Expression::vkArray) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script BuildListOfQuestPossibleLocations - not array"_a));
        }
        aGalaxy::TStar* Star = reinterpret_cast<aGalaxy::TStar*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[2]->GetDword())));
        std::int32_t MinDistance = av[3]->GetInt();
        std::int32_t MaxDistance = av[4]->GetInt();
        av[1]->GetArray()->Clear();
        std::int32_t I = 1;
        while (I < pas::list_count(aGalaxy::Galaxy->Stars) && Star->StarDistances[I].Distance <= MaxDistance) {
            Candidate = Star->StarDistances[I].Star;
            if (Star->StarDistances[I].Distance >= MinDistance && Candidate->Status.ControlFaction == aGalaxyStruct::sfCoalition && Candidate->Status.CustomFaction == u"" && Candidate->Status.Battle == 0 && aGalaxy::Galaxy->KellerTargetStar != Candidate && Candidate->IsConstellationVisible()) {
                Allowed = true;
                if (av.length() - 1 > 4) {
                    const std::int32_t cpp_last = av.length() - 1;
                    if (5 <= cpp_last) {
                        for (J = 5; J <= cpp_last; ++J) {
                            if (reinterpret_cast<aGalaxy::TStar*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[J]->GetDword()))) == Candidate) {
                                Allowed = false;
                            }
                        }
                    }
                }
                if (Allowed) {
                    Value = pas::construct_call<EC_Expression::TVarEC>(EC_Expression::TVarEC_Create, EC_Expression::vkDword);
                    Value->SetDword(static_cast<std::uint32_t>(reinterpret_cast<std::uintptr_t>(Candidate)));
                    av[1]->GetArray()->AddItem(Value);
                }
            }
            ++I;
        }
        std::int32_t Count = av[1]->GetArray()->Count;
        {
            const std::int32_t cpp_first = Count - 1;
            if (cpp_first >= 0) {
                for (I = cpp_first; I >= 0; --I) {
                    Star = reinterpret_cast<aGalaxy::TStar*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(EC_Expression::TVarArrayEC_GetItem(av[1]->GetArray(), I)->GetDword())));
                    J = 0;
                    Allowed = true;
                    while (Allowed && J < pas::list_count(Star->Ships)) {
                        if (pas::list_at<aShip::TShip>(Star->Ships, J)->TypeId == aGalaxyStruct::stKling) {
                            Allowed = false;
                            av[1]->GetArray()->Delete(I);
                        } else {
                            ++J;
                        }
                    }
                }
            }
        }
        Count = av[1]->GetArray()->Count;
        I = 0;
        while (I < pas::list_count(aGalaxy::Galaxy->Stars) && Count > 0) {
            Star = pas::list_at<aGalaxy::TStar>(aGalaxy::Galaxy->Stars, I);
            if (Star->Status.ControlFaction == aGalaxyStruct::sfDominators) {
                for (auto cpp_range = pas::for_to<std::int32_t>(0, pas::list_count(Star->Ships) - 1); cpp_range.next(J); ) {
                    if (pas::list_at<aShip::TShip>(Star->Ships, J)->TypeId == aGalaxyStruct::stKling && pas::class_cast_if<aGalaxy::TStar*>(pas::list_at<aShip::TShip>(Star->Ships, J)->OrderTarget) != nullptr) {
                        Candidate = pas::checked_cast<aGalaxy::TStar*>(pas::list_at<aShip::TShip>(Star->Ships, J)->OrderTarget);
                        {
                            const std::int32_t cpp_first_2 = av[1]->GetArray()->Count - 1;
                            if (cpp_first_2 >= 0) {
                                for (K = cpp_first_2; K >= 0; --K) {
                                    if (reinterpret_cast<aGalaxy::TStar*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(EC_Expression::TVarArrayEC_GetItem(av[1]->GetArray(), K)->GetDword()))) == Candidate) {
                                        av[1]->GetArray()->Delete(K);
                                        Count = av[1]->GetArray()->Count;
                                    }
                                }
                            }
                        }
                    }
                }
            }
            ++I;
        }
        Count = av[1]->GetArray()->Count;
        av[0]->SetInt(Count);
        if (Count == 0) {
            EC_Expression::TVarEC* cpp_arg_3 = pas::construct_call<EC_Expression::TVarEC>(EC_Expression::TVarEC_Create, EC_Expression::vkEmpty);
            EC_Expression::TVarArrayEC* array = av[1]->GetArray();
            array->AddItem(cpp_arg_3);
        }
    }

    void SF_FindItemInShip(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        if (av.length() - 1 < 2) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script FindItemInShip"_a));
        }
        aShip::TShip* Ship = reinterpret_cast<aShip::TShip*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())));
        pas::Object* Obj = reinterpret_cast<pas::Object*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[2]->GetDword())));
        aItem::TItem* Item = nullptr;
        if (pas::class_cast_if<aItem::TItem*>(Obj) != nullptr) {
            Item = reinterpret_cast<aItem::TItem*>(Obj);
        }
        if (pas::class_cast_if<aScript::TScriptItem*>(Obj) != nullptr) {
            Item = reinterpret_cast<aScript::TScriptItem*>(Obj)->Item;
        }
        av[0]->SetInt(-1);
        if (Item != nullptr) {
            av[0]->SetInt(pas::list_indexof(Ship->Inventory, reinterpret_cast<void*>(Item)));
            if (av[0]->GetInt() < 0) {
                av[0]->SetInt(pas::list_indexof(Ship->Artefacts, reinterpret_cast<void*>(Item)));
            }
        }
    }

