    void SF_StarListToPlanetList(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        std::int32_t I{};
        std::int32_t J{};
        std::int32_t Priority{};
        std::int32_t EnemyDistance{};
        double Score{};
        double OtherScore{};
        aGalaxy::TStar* Star{};
        aPlanet::TPlanet* Planet{};
        aPlanet::TPlanet* BestPlanet{};
        EC_Expression::TVarEC* Temp{};
        WindowsSdk::PDouble ScorePtr{};
        pas::List* Scores{};
        pas::Array<std::int32_t, 0, 4> Weights{};
        if (av.length() - 1 < 6) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script StarListToPlanetList"_a));
        }
        if (av[1]->RealVType() != EC_Expression::vkArray) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script StarListToPlanetList - not array"_a));
        }
        if (av.length() - 1 > 6 && av[7]->RealVType() != EC_Expression::vkArray) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script StarListToPlanetList - not array"_a));
        }
        double Penalty = 0.0;
        if (av.length() - 1 > 7) {
            Penalty = pas::real_divide(av[8]->GetInt(), 1.0E+2L);
        }
        Weights[0] = av[2]->GetInt();
        Weights[1] = av[3]->GetInt();
        Weights[2] = av[4]->GetInt();
        Weights[3] = av[5]->GetInt();
        Weights[4] = av[6]->GetInt();
        std::int32_t Count = av[1]->GetArray()->Count;
        {
            const std::int32_t cpp_first = Count - 1;
            if (cpp_first >= 0) {
                for (I = cpp_first; I >= 0; --I) {
                    Star = reinterpret_cast<aGalaxy::TStar*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(EC_Expression::TVarArrayEC_GetItem(av[1]->GetArray(), I)->GetDword())));
                    Priority = 0;
                    BestPlanet = nullptr;
                    for (auto cpp_range = pas::for_to<std::int32_t>(0, pas::list_count(Star->Planets) - 1); cpp_range.next(J); ) {
                        Planet = pas::list_at<aPlanet::TPlanet>(Star->Planets, J);
                        if (pas::in_range(Planet->OwnerId, static_cast<std::int32_t>(aGalaxyStruct::oiMaloc), static_cast<std::int32_t>(aGalaxyStruct::oiGaal)) && Weights[Planet->OwnerId] > Priority) {
                            BestPlanet = Planet;
                            Priority = Weights[Planet->OwnerId];
                        }
                    }
                    if (Priority > 0) {
                        EC_Expression::TVarArrayEC_GetItem(av[1]->GetArray(), I)->SetDword(static_cast<std::uint32_t>(reinterpret_cast<std::uintptr_t>(BestPlanet)));
                    } else {
                        av[1]->GetArray()->Delete(I);
                    }
                }
            }
        }
        Count = av[1]->GetArray()->Count;
        if (Count > 0) {
            Scores = pas::make_object<pas::List>();
            for (auto cpp_range_2 = pas::for_to<std::int32_t>(0, Count - 1); cpp_range_2.next(I); ) {
                Planet = reinterpret_cast<aPlanet::TPlanet*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(EC_Expression::TVarArrayEC_GetItem(av[1]->GetArray(), I)->GetDword())));
                Star = Planet->CurrentStar;
                J = 0;
                while (J < pas::list_count(aGalaxy::Galaxy->Stars) && pas::checked_cast<aGalaxy::TStar*>(static_cast<pas::Object*>(Star->StarDistances[J].Star))->Status.ControlFaction != aGalaxyStruct::sfDominators && pas::checked_cast<aGalaxy::TStar*>(static_cast<pas::Object*>(Star->StarDistances[J].Star))->Status.CustomFaction == u"") {
                    ++J;
                }
                if (J == pas::list_count(aGalaxy::Galaxy->Stars)) {
                    EnemyDistance = 1;
                } else {
                    EnemyDistance = Star->StarDistances[J].Distance;
                }
                Score = EnemyDistance * Weights[Planet->OwnerId];
                if (av.length() - 1 > 6) {
                    for (auto cpp_range_3 = pas::for_to<std::int32_t>(0, av[7]->GetArray()->Count - 1); cpp_range_3.next(J); ) {
                        if (reinterpret_cast<aGalaxy::TStar*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(EC_Expression::TVarArrayEC_GetItem(av[7]->GetArray(), J)->GetDword()))) == Star || EC_Expression::TVarArrayEC_GetItem(av[7]->GetArray(), J)->GetDword() == Star->Id) {
                            Score = static_cast<long double>(Score) * Penalty;
                        }
                    }
                }
                pas::new_value(ScorePtr);
                pas::store_unaligned<double>(ScorePtr, Score);
                pas::list_add(Scores, static_cast<void*>(ScorePtr));
            }
            for (auto cpp_range_4 = pas::for_to<std::int32_t>(1, Count - 1); cpp_range_4.next(I); ) {
                for (auto cpp_range_5 = pas::for_downto<std::int32_t>(Count - 1, I); cpp_range_5.next(J); ) {
                    pas::Extended cpp_left = pas::load_unaligned<double>(pas::list_at<double>(Scores, J));
                    if (cpp_left > pas::load_unaligned<double>(pas::list_at<double>(Scores, J - 1))) {
                        Temp = EC_Expression::TVarArrayEC_GetItem(av[1]->GetArray(), J);
                        {
                            EC_Expression::TVarEC* item = EC_Expression::TVarArrayEC_GetItem(av[1]->GetArray(), J - 1);
                            EC_Expression::TVarArrayEC* array = av[1]->GetArray();
                            EC_Expression::TVarArrayEC_SetItem(array, J, item);
                        }
                        EC_Expression::TVarArrayEC_SetItem(av[1]->GetArray(), J - 1, Temp);
                        Score = pas::load_unaligned<double>(pas::list_at<double>(Scores, J));
                        OtherScore = pas::load_unaligned<double>(pas::list_at<double>(Scores, J - 1));
                        pas::store_unaligned<double>(pas::list_at<double>(Scores, J), OtherScore);
                        pas::store_unaligned<double>(pas::list_at<double>(Scores, J - 1), Score);
                    }
                }
            }
            // The native routine leaves the allocated score cells unreleased.
            pas::free(Scores);
        }
        av[0]->SetInt(Count);
        if (Count == 0) {
            EC_Expression::TVarEC* cpp_arg = pas::construct_call<EC_Expression::TVarEC>(EC_Expression::TVarEC_Create, EC_Expression::vkEmpty);
            EC_Expression::TVarArrayEC* array_2 = av[1]->GetArray();
            array_2->AddItem(cpp_arg);
        }
    }

