    void SF_StartVideo(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        aScript::PScriptVDRequest Request{};
        pas::WideString SavedCategory{};
        GI_XviD::TxvidGI* Video{};
        if (av.length() - 1 == 0) {
            av[0]->SetInt(pas::list_count(aScript::QueuedVideos));
            return;
        }
        if (av.length() - 1 < 2) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script StartVideo"_a));
        }
        if (Globals::GetInnermostScreenLoop() == Globals::ShipScreen) {
            Globals::ShipScreen->ShipLoopSound->SetVolume(0.0f);
            Video = pas::checked_cast<GI_XviD::TxvidGI*>(Globals::ShipScreen->GetByName(u"Film"_wref.get()));
            Video->SetActive(true);
            if (!Video->ImageOpen(av[1]->GetString(), false)) {
                Globals::ShipScreen->StopScriptVideo();
                return;
            }
            if (GlobalsV::MusicEnabled) {
                GR_Main::MusicManager->StopImmediately();
                while (GR_Main::MusicManager->IsPlaying()) {
                    SysUtilsImports::Sleep(1u);
                }
            }
            if (GlobalsV::MusicEnabled) {
                SavedCategory = GR_Main::MusicManager->CategoryOverride;
                GR_Main::MusicManager->CategoryOverride = pas::WideString();
                {
                    const pas::WideString& string = av[2]->GetString();
                    GR_Music::TMusicControl* musicManager = GR_Main::MusicManager;
                    musicManager->PlayCategory(string);
                }
                while (!GR_Main::MusicManager->IsPlaying()) {
                    SysUtilsImports::Sleep(1u);
                }
                GR_Main::MusicManager->CategoryOverride = SavedCategory;
            }
            Globals::ShipScreen->ScriptVideoStartedAt = MMSystem::timeGetTime();
            if (Globals::ShipScreen->ScriptVideoTimer != nullptr) {
                Globals::ShipScreen->CancelCallbackTimer(Globals::ShipScreen->ScriptVideoTimer);
                Globals::ShipScreen->ScriptVideoTimer = nullptr;
            }
            Globals::ShipScreen->ScriptVideoTimer = Globals::ShipScreen->ScheduleCallbackTimer(5, 5, pas::bind_method<&fShip2::TfShip2::AdvanceScriptVideo>(Globals::ShipScreen), 0);
        } else {
            pas::new_value(Request);
            Request->Video = av[1]->GetString();
            Request->Soundtrack = av[2]->GetString();
            Request->Script = aScript::CurrentScript;
            pas::list_add(aScript::QueuedVideos, static_cast<void*>(Request));
            if (aScript::CurrentScript != nullptr) {
                aScript::CurrentScript->InitCode->LocalVar->GetVar(u"GVideoStatus"_wref.get())->SetInt(1);
            }
            GlobalsV::RequestedScreenId = GlobalsV::CurrentScreenId;
            reinterpret_cast<GI_MessageLoop::TMessageLoopGI*>(GlobalsV::RegisteredScreens[GlobalsV::CurrentScreenId])->RequestClose(1);
        }
    }

    void SF_StartMusic(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        pas::WideString SavedCategory{};
        if (av.length() - 1 < 1) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script StartMusic"_a));
        }
        if (GlobalsV::MusicEnabled) {
            if (Globals::GetInnermostScreenLoop() == Globals::StarMapScreen) {
                Globals::StarMapScreen->BattleMusicSelected = true;
            }
            GR_Main::MusicManager->StopImmediately();
            while (GR_Main::MusicManager->IsPlaying()) {
                SysUtilsImports::Sleep(1u);
            }
            if (EC_Str::CountDelimitedPartsW(av[1]->GetString(), u"."_wref.get()) > 1) {
                const pas::WideString& string = av[1]->GetString();
                GR_Music::TMusicControl* musicManager = GR_Main::MusicManager;
                musicManager->PlayFile(string);
            } else {
                SavedCategory = GR_Main::MusicManager->CategoryOverride;
                GR_Main::MusicManager->CategoryOverride = pas::WideString();
                {
                    const pas::WideString& string_2 = av[1]->GetString();
                    GR_Music::TMusicControl* musicManager_2 = GR_Main::MusicManager;
                    musicManager_2->PlayCategory(string_2);
                }
                GR_Main::MusicManager->CategoryOverride = SavedCategory;
            }
        }
    }

