    void SF_DomiksDefeated(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        std::uint8_t Kind{};
        if (av.length() - 1 < 1) {
            if (!aGalaxy::Galaxy->HasUnresolvedDominatorSeries(pas::constant_set<aGalaxy::TDominatorSeriesSet>({{aGalaxyStruct::dsBlazer}, {aGalaxyStruct::dsKeller}, {aGalaxyStruct::dsTerron}}))) {
                av[0]->SetInt(1);
            } else {
                av[0]->SetInt(0);
            }
        } else {
            Kind = av[1]->GetInt();
            switch (Kind) {
                case 0: {
                    if (aGalaxy::Galaxy->BlazerSeriesResolvedTurn == 0) {
                        av[0]->SetInt(0);
                    } else if (aGalaxy::Galaxy->BlazerLandingPlanetId != 0 && aKling::BlazerShip != nullptr) {
                        av[0]->SetInt(3);
                    } else if (aGalaxy::Galaxy->BlazerSelfDestructTurn != 0) {
                        av[0]->SetInt(2);
                    } else {
                        av[0]->SetInt(1);
                    }
                    break;
                }
                case 1: {
                    if (aGalaxy::Galaxy->KellerSeriesResolvedTurn == 0) {
                        av[0]->SetInt(0);
                    } else if (aGalaxy::Galaxy->KellerLeaveTurn != 0) {
                        av[0]->SetInt(2);
                    } else if (aGalaxy::Galaxy->KellerResearchTargetStarId != 0) {
                        av[0]->SetInt(3);
                    } else {
                        av[0]->SetInt(1);
                    }
                    break;
                }
                case 2: {
                    if (aGalaxy::Galaxy->TerronSeriesResolvedTurn == 0) {
                        av[0]->SetInt(0);
                    } else if (aGalaxy::Galaxy->TerronToStarTurn != 0) {
                        av[0]->SetInt(2);
                    } else if (aGalaxy::Galaxy->TerronLandingLockTurn != 0) {
                        av[0]->SetInt(3);
                    } else {
                        av[0]->SetInt(1);
                    }
                    break;
                }
                default: av[0]->SetInt(0); break;
            }
        }
    }

