    void SF_GetNodesFromShip(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        std::int32_t Index{};
        aItem::TItem* Item{};
        aItem::TProtoplasm* Nodes{};
        if (av.length() - 1 < 1) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script GetNodesFromShip"_a));
        }
        aShip::TShip* Ship = reinterpret_cast<aShip::TShip*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())));
        std::int32_t Remaining = 0;
        std::int32_t Total = 0;
        std::int32_t Series = -1;
        if (av.length() - 1 > 1) {
            Remaining = av[2]->GetInt();
        }
        if (av.length() - 1 > 2) {
            Series = av[3]->GetInt();
        }
        {
            const std::int32_t cpp_first = pas::list_count(Ship->Inventory) - 1;
            if (cpp_first >= 0) {
                for (Index = cpp_first; Index >= 0; --Index) {
                    Item = pas::list_at<aItem::TItem>(Ship->Inventory, Index);
                    if (!(pas::class_cast_if<aItem::TProtoplasm*>(Item) != nullptr)) {
                        continue;
                    }
                    Nodes = pas::checked_cast<aItem::TProtoplasm*>(Item);
                    if (Series < 0 || Nodes->DominatorSeries == Series) {
                        Total += Nodes->StackCount;
                        if (Remaining >= Nodes->StackCount) {
                            Remaining -= Nodes->StackCount;
                            pas::list_delete(Ship->Inventory, Index);
                            pas::free(Nodes);
                        } else {
                            Nodes->StackCount -= Remaining;
                            Nodes->Weight = Nodes->StackCount;
                            Nodes->Cost = 10 * Nodes->StackCount;
                            Remaining = 0;
                        }
                    }
                }
            }
        }
        if (av.length() - 1 > 1 && av[2]->GetInt() > 0) {
            av[0]->SetInt(Remaining);
        } else {
            av[0]->SetInt(Total);
        }
    }

    void SF_GetNodesFromStorage(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        std::int32_t NewCount{};
        aPlayer::PStorageEntry Entry{};
        aItem::TProtoplasm* Nodes{};
        // The + 0 expressions retain native DCC32 load/store ordering; no arithmetic is emitted.
        pas::Object* Location = nullptr;
        if (av.length() - 1 >= 1) {
            Location = reinterpret_cast<pas::Object*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())));
        }
        av[0]->SetInt(0);
        std::int32_t Remaining = 0;
        std::int32_t Series = -1;
        if (av.length() - 1 > 1) {
            Remaining = av[2]->GetInt();
        }
        if (av.length() - 1 > 2) {
            Series = av[3]->GetInt();
        }
        std::int32_t Index = 0;
        while (Index < pas::list_count(aPlayer::GetPlayer()->StorageEntries)) {
            Entry = pas::list_at<aPlayer::TStorageEntry>(aPlayer::GetPlayer()->StorageEntries, Index);
            if ((Entry->LocationOwner == Location || Location == nullptr) && static_cast<std::uint8_t>(Entry->Item->ItemType) == static_cast<std::uint8_t>(aConst::t_Protoplasm)) {
                Nodes = reinterpret_cast<aItem::TProtoplasm*>(Entry->Item);
                // Native does not advance Index when the series differs.
                if (Series < 0 || Nodes->DominatorSeries == Series) {
                    av[0]->SetInt(av[0]->GetInt() + Nodes->Weight);
                    if (Remaining <= 0) {
                        ++Index;
                    } else if (Remaining + 0 < Nodes->StackCount) {
                        NewCount = Nodes->StackCount - Remaining;
                        Nodes->Cost = System::Round(pas::real_divide(Nodes->Cost, Nodes->StackCount) * NewCount);
                        Nodes->StackCount = NewCount + 0;
                        Nodes->Weight = NewCount + 0;
                        Remaining = 0;
                        ++Index;
                    } else {
                        Remaining -= Nodes->Weight;
                        pas::list_delete(aPlayer::GetPlayer()->StorageEntries, Index);
                        pas::free(Entry->Item);
                        pas::dispose(Entry);
                    }
                }
            } else {
                ++Index;
            }
        }
    }

