    void SF_PlayerQuestInProgress(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        aRanger::PQuest Quest{};
        std::int32_t Index{};
        aPlanet::TPlanet* Planet{};
        if (aPlayer::GetPlayer()->Quests != nullptr) {
            if (av.length() - 1 > 0) {
                Planet = reinterpret_cast<aPlanet::TPlanet*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())));
            } else {
                Planet = nullptr;
            }
            for (auto cpp_range = pas::for_to<std::int32_t>(0, pas::list_count(aPlayer::GetPlayer()->Quests) - 1); cpp_range.next(Index); ) {
                Quest = pas::list_at<aRanger::TQuest>(aPlayer::GetPlayer()->Quests, Index);
                if ((Planet == nullptr || Quest->Planet == Planet) && static_cast<std::uint8_t>(Quest->Successful ^ 1)) {
                    av[0]->SetInt(1);
                    return;
                }
            }
        }
        av[0]->SetInt(0);
    }

    void SF_PlayerQuestsCompleted(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        aRanger::PPlayerOldQuest Quest{};
        std::int32_t Index{};
        av[0]->SetInt(0);
        if (aRanger::PlayerOldQuests != nullptr && pas::list_count(aRanger::PlayerOldQuests) > 0) {
            for (auto cpp_range = pas::for_to<std::int32_t>(0, pas::list_count(aRanger::PlayerOldQuests) - 1); cpp_range.next(Index); ) {
                Quest = pas::list_at<aRanger::TPlayerOldQuest>(aRanger::PlayerOldQuests, Index);
                if (av.length() - 1 < 1 || static_cast<aGalaxyStruct::TQuestType>(av[1]->GetInt()) == Quest->QuestType) {
                    if (Quest->Successful) {
                        av[0]->SetInt(av[0]->GetInt() + 1);
                    }
                }
            }
        }
    }

    void SF_QuestsStatusByNom(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        std::int32_t Index{};
        aRanger::PPlayerOldQuest OldQuest{};
        aRanger::PQuest Quest{};
        if (av.length() - 1 < 2) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script QuestsStatusByNom"_a));
        }
        aGalaxyStruct::TQuestType Kind = static_cast<aGalaxyStruct::TQuestType>(av[1]->GetInt());
        std::int32_t Number = av[2]->GetInt();
        if (aRanger::PlayerOldQuests != nullptr && pas::list_count(aRanger::PlayerOldQuests) > 0) {
            for (auto cpp_range = pas::for_to<std::int32_t>(0, pas::list_count(aRanger::PlayerOldQuests) - 1); cpp_range.next(Index); ) {
                OldQuest = pas::list_at<aRanger::TPlayerOldQuest>(aRanger::PlayerOldQuests, Index);
                if (OldQuest->QuestType == Kind && OldQuest->QuestNumber == Number) {
                    if (OldQuest->Successful) {
                        av[0]->SetInt(3);
                    } else {
                        av[0]->SetInt(4);
                    }
                    return;
                }
            }
        }
        if (aPlayer::GetPlayer()->Quests != nullptr && pas::list_count(aPlayer::GetPlayer()->Quests) > 0) {
            for (auto cpp_range_2 = pas::for_to<std::int32_t>(0, pas::list_count(aPlayer::GetPlayer()->Quests) - 1); cpp_range_2.next(Index); ) {
                Quest = pas::list_at<aRanger::TQuest>(aPlayer::GetPlayer()->Quests, Index);
                if (Quest->QuestType == Kind && Quest->QuestNumber == Number) {
                    if (Quest->Successful) {
                        av[0]->SetInt(2);
                    } else {
                        av[0]->SetInt(1);
                    }
                    return;
                }
            }
        }
        av[0]->SetInt(0);
    }

