    void SF_ShipAddCustomShipInfo(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        aShip::PCustomShipInfo Info{};
        if (av.length() - 1 < 2) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script ShipAddCustomShipInfo"_a));
        }
        pas::new_value(Info);
        pas::list_add(reinterpret_cast<aShip::TShip*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())))->CustomShipInfos, static_cast<void*>(Info));
        Info->ActionCode = nullptr;
        Info->TypeName = av[2]->GetString();
        Info->ActionCodeInitialized = false;
        Info->DeleteQueued = false;
        if (av.length() - 1 > 2) {
            Info->Description = av[3]->GetString();
        } else {
            Info->Description = pas::WideString();
        }
        if (av.length() - 1 > 3) {
            pas::store_unaligned<std::int32_t>(pas::byte_offset(&Info->Data, (1 - 1) * sizeof(std::int32_t)), av[4]->GetInt());
        } else {
            pas::store_unaligned<std::int32_t>(pas::byte_offset(&Info->Data, (1 - 1) * sizeof(std::int32_t)), 0);
        }
        if (av.length() - 1 > 4) {
            pas::store_unaligned<std::int32_t>(pas::byte_offset(&Info->Data, (2 - 1) * sizeof(std::int32_t)), av[5]->GetInt());
        } else {
            pas::store_unaligned<std::int32_t>(pas::byte_offset(&Info->Data, (2 - 1) * sizeof(std::int32_t)), 0);
        }
        if (av.length() - 1 > 5) {
            pas::store_unaligned<std::int32_t>(pas::byte_offset(&Info->Data, (3 - 1) * sizeof(std::int32_t)), av[6]->GetInt());
        } else {
            pas::store_unaligned<std::int32_t>(pas::byte_offset(&Info->Data, (3 - 1) * sizeof(std::int32_t)), 0);
        }
        if (av.length() - 1 > 6) {
            Info->TextData1 = av[7]->GetString();
        } else {
            Info->TextData1 = pas::WideString();
        }
        if (av.length() - 1 > 7) {
            Info->TextData2 = av[8]->GetString();
        } else {
            Info->TextData2 = pas::WideString();
        }
        if (av.length() - 1 > 8) {
            Info->TextData3 = av[9]->GetString();
        } else {
            Info->TextData3 = pas::WideString();
        }
        Info->StatusEffect = GR_Main::LanguageDataConfig->GetBlock(u"ShipInfo"_wref.get())->GetBlock(u"AddInfo"_wref.get())->GetBlock(u"CustomInfos"_wref.get())->GetBlock(Info->TypeName)->CountParams(u"StatusEffect"_wref.get()) > 0;
        av[0]->SetDword(static_cast<std::uint32_t>(reinterpret_cast<std::uintptr_t>(Info)));
    }

    void SF_ShipDeleteCustomShipInfo(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        std::int32_t Index{};
        std::int32_t I{};
        aShip::PCustomShipInfo Info{};
        if (av.length() - 1 < 2) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script ShipDeleteCustomShipInfo"_a));
        }
        aShip::TShip* Ship = reinterpret_cast<aShip::TShip*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())));
        if (av[2]->RealVType() == EC_Expression::vkString) {
            for (auto cpp_range = pas::for_to<std::int32_t>(0, pas::list_count(Ship->CustomShipInfos) - 1); cpp_range.next(I); ) {
                Info = pas::list_at<aShip::TCustomShipInfo>(Ship->CustomShipInfos, I);
                if (static_cast<std::uint8_t>(Info->DeleteQueued ^ 1) && ([&] {
                    pas::WideString cpp_string = av[2]->GetString();
                    return Info->TypeName == cpp_string;
                }())) {
                    Info->DeleteQueued = true;
                    return;
                }
            }
        } else if (av[2]->GetDword() > 10000 && av[2]->GetInt() != -1) {
            if (Ship == nullptr || pas::list_indexof(Ship->CustomShipInfos, reinterpret_cast<void*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[2]->GetDword())))) >= 0) {
                reinterpret_cast<aShip::PCustomShipInfo>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[2]->GetDword())))->DeleteQueued = true;
            }
        } else {
            Index = av[2]->GetInt();
            if (Index < 0) {
                return;
            }
            Info = nullptr;
            for (auto cpp_range_2 = pas::for_to<std::int32_t>(0, pas::list_count(Ship->CustomShipInfos) - 1); cpp_range_2.next(I); ) {
                Info = pas::list_at<aShip::TCustomShipInfo>(Ship->CustomShipInfos, I);
                if (!Info->DeleteQueued) {
                    --Index;
                    if (Index < 0) {
                        break;
                    }
                }
            }
            if (Index < 0 && Info != nullptr) {
                Info->DeleteQueued = true;
            }
        }
    }

