    void SF_ItemLevel(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        std::int32_t NewLevel{};
        aItem::TEquipment* OldBase{};
        aItem::TEquipment* NewBase{};
        if (av.length() - 1 < 1) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script ItemLevel"_a));
        }
        pas::Object* Obj = reinterpret_cast<pas::Object*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())));
        aItem::TItem* Item = nullptr;
        std::int32_t OldLevel = 0;
        if (pas::class_cast_if<aItem::TItem*>(Obj) != nullptr) {
            Item = reinterpret_cast<aItem::TItem*>(Obj);
        }
        if (pas::class_cast_if<aScript::TScriptItem*>(Obj) != nullptr) {
            Item = reinterpret_cast<aScript::TScriptItem*>(Obj)->Item;
        }
        if (Item != nullptr) {
            if (pas::in_range(static_cast<std::uint8_t>(Item->ItemType), static_cast<std::int32_t>(aConst::t_Hull), static_cast<std::int32_t>(aConst::t_CustomWeapon))) {
                OldLevel = pas::checked_cast<aItem::TEquipment*>(Item)->GetLevel();
                if (av.length() - 1 > 1) {
                    NewLevel = std::max<std::int32_t>(1, av[2]->GetInt());
                    if (pas::class_cast_if<aItem::TWeapon*>(Item) != nullptr) {
                        OldBase = aItem::CreateGeneratedWeapon(reinterpret_cast<aItem::TWeapon*>(Item)->GetWeaponInfo(), Item->Weight, OldLevel, Item->OwnerId);
                        NewBase = aItem::CreateGeneratedWeapon(reinterpret_cast<aItem::TWeapon*>(Item)->GetWeaponInfo(), Item->Weight, NewLevel, Item->OwnerId);
                    } else {
                        OldBase = aItem::CreateGeneratedEquipment(Item->ItemType, Item->Weight, OldLevel, Item->OwnerId);
                        NewBase = aItem::CreateGeneratedEquipment(Item->ItemType, Item->Weight, NewLevel, Item->OwnerId);
                    }
                    switch (Item->ItemType) {
                        case aConst::t_Hull: {
                            reinterpret_cast<aItem::THull*>(Item)->TechLevel = NewLevel;
                            reinterpret_cast<aItem::THull*>(Item)->Armor = reinterpret_cast<aItem::THull*>(Item)->Armor + reinterpret_cast<aItem::THull*>(NewBase)->Armor - reinterpret_cast<aItem::THull*>(OldBase)->Armor;
                            break;
                        }
                        case aConst::t_FuelTanks: {
                            reinterpret_cast<aItem::TFuelTanks*>(Item)->TechLevel = NewLevel;
                            reinterpret_cast<aItem::TFuelTanks*>(Item)->Capacity = reinterpret_cast<aItem::TFuelTanks*>(Item)->Capacity + reinterpret_cast<aItem::TFuelTanks*>(NewBase)->Capacity - reinterpret_cast<aItem::TFuelTanks*>(OldBase)->Capacity;
                            reinterpret_cast<aItem::TFuelTanks*>(Item)->Fuel = std::max<std::int32_t>(0, std::min<std::int32_t>(reinterpret_cast<aItem::TFuelTanks*>(Item)->Fuel, static_cast<std::int32_t>(reinterpret_cast<aItem::TFuelTanks*>(Item)->Capacity)));
                            break;
                        }
                        case aConst::t_Engine: {
                            reinterpret_cast<aItem::TEngine*>(Item)->TechLevel = NewLevel;
                            reinterpret_cast<aItem::TEngine*>(Item)->Speed = reinterpret_cast<aItem::TEngine*>(Item)->Speed + reinterpret_cast<aItem::TEngine*>(NewBase)->Speed - reinterpret_cast<aItem::TEngine*>(OldBase)->Speed;
                            reinterpret_cast<aItem::TEngine*>(Item)->JumpRange = reinterpret_cast<aItem::TEngine*>(Item)->JumpRange + reinterpret_cast<aItem::TEngine*>(NewBase)->JumpRange - reinterpret_cast<aItem::TEngine*>(OldBase)->JumpRange;
                            break;
                        }
                        case aConst::t_Radar: {
                            reinterpret_cast<aItem::TRadar*>(Item)->TechLevel = NewLevel;
                            reinterpret_cast<aItem::TRadar*>(Item)->Range = reinterpret_cast<aItem::TRadar*>(Item)->Range + reinterpret_cast<aItem::TRadar*>(NewBase)->Range - reinterpret_cast<aItem::TRadar*>(OldBase)->Range;
                            break;
                        }
                        case aConst::t_Scaner: {
                            reinterpret_cast<aItem::TScaner*>(Item)->TechLevel = NewLevel;
                            reinterpret_cast<aItem::TScaner*>(Item)->ScanPower = reinterpret_cast<aItem::TScaner*>(Item)->ScanPower + reinterpret_cast<aItem::TScaner*>(NewBase)->ScanPower - reinterpret_cast<aItem::TScaner*>(OldBase)->ScanPower;
                            break;
                        }
                        case aConst::t_RepairRobot: {
                            reinterpret_cast<aItem::TRepairRobot*>(Item)->TechLevel = NewLevel;
                            reinterpret_cast<aItem::TRepairRobot*>(Item)->RepairPoints = reinterpret_cast<aItem::TRepairRobot*>(Item)->RepairPoints + reinterpret_cast<aItem::TRepairRobot*>(NewBase)->RepairPoints - reinterpret_cast<aItem::TRepairRobot*>(OldBase)->RepairPoints;
                            break;
                        }
                        case aConst::t_CargoHook: {
                            reinterpret_cast<aItem::TCargoHook*>(Item)->TechLevel = NewLevel;
                            reinterpret_cast<aItem::TCargoHook*>(Item)->PickupPower = reinterpret_cast<aItem::TCargoHook*>(Item)->PickupPower + reinterpret_cast<aItem::TCargoHook*>(NewBase)->PickupPower - reinterpret_cast<aItem::TCargoHook*>(OldBase)->PickupPower;
                            reinterpret_cast<aItem::TCargoHook*>(Item)->Range = reinterpret_cast<aItem::TCargoHook*>(Item)->Range + reinterpret_cast<aItem::TCargoHook*>(NewBase)->Range - reinterpret_cast<aItem::TCargoHook*>(OldBase)->Range;
                            reinterpret_cast<aItem::TCargoHook*>(Item)->MinPullSpeed = static_cast<long double>(reinterpret_cast<aItem::TCargoHook*>(Item)->MinPullSpeed) + reinterpret_cast<aItem::TCargoHook*>(NewBase)->MinPullSpeed - reinterpret_cast<aItem::TCargoHook*>(OldBase)->MinPullSpeed;
                            reinterpret_cast<aItem::TCargoHook*>(Item)->MaxPullSpeed = static_cast<long double>(reinterpret_cast<aItem::TCargoHook*>(Item)->MaxPullSpeed) + reinterpret_cast<aItem::TCargoHook*>(NewBase)->MaxPullSpeed - reinterpret_cast<aItem::TCargoHook*>(OldBase)->MaxPullSpeed;
                            break;
                        }
                        case aConst::t_DefGenerator: {
                            reinterpret_cast<aItem::TDefGenerator*>(Item)->TechLevel = NewLevel;
                            reinterpret_cast<aItem::TDefGenerator*>(Item)->DamageFactor = static_cast<long double>(reinterpret_cast<aItem::TDefGenerator*>(Item)->DamageFactor) + reinterpret_cast<aItem::TDefGenerator*>(NewBase)->DamageFactor - reinterpret_cast<aItem::TDefGenerator*>(OldBase)->DamageFactor;
                            break;
                        }
                        default: {
                            if (pas::in_range(static_cast<std::uint8_t>(Item->ItemType), static_cast<std::int32_t>(aConst::t_Weapon1), static_cast<std::int32_t>(aConst::t_CustomWeapon))) {
                                reinterpret_cast<aItem::TWeapon*>(Item)->TechLevel = NewLevel;
                                reinterpret_cast<aItem::TWeapon*>(Item)->Range = reinterpret_cast<aItem::TWeapon*>(Item)->Range + reinterpret_cast<aItem::TWeapon*>(NewBase)->Range - reinterpret_cast<aItem::TWeapon*>(OldBase)->Range;
                                reinterpret_cast<aItem::TWeapon*>(Item)->MinDamage = reinterpret_cast<aItem::TWeapon*>(Item)->MinDamage + reinterpret_cast<aItem::TWeapon*>(NewBase)->MinDamage - reinterpret_cast<aItem::TWeapon*>(OldBase)->MinDamage;
                                reinterpret_cast<aItem::TWeapon*>(Item)->MaxDamage = reinterpret_cast<aItem::TWeapon*>(Item)->MaxDamage + reinterpret_cast<aItem::TWeapon*>(NewBase)->MaxDamage - reinterpret_cast<aItem::TWeapon*>(OldBase)->MaxDamage;
                                reinterpret_cast<aItem::TWeapon*>(Item)->AmmoCapacity = reinterpret_cast<aItem::TWeapon*>(Item)->AmmoCapacity + reinterpret_cast<aItem::TWeapon*>(NewBase)->AmmoCapacity - reinterpret_cast<aItem::TWeapon*>(OldBase)->AmmoCapacity;
                                reinterpret_cast<aItem::TWeapon*>(Item)->Ammo = std::max<std::int32_t>(0, reinterpret_cast<aItem::TWeapon*>(Item)->Ammo + reinterpret_cast<aItem::TWeapon*>(NewBase)->Ammo - reinterpret_cast<aItem::TWeapon*>(OldBase)->Ammo);
                            }
                            break;
                        }
                    }
                    pas::free(OldBase);
                    pas::free(NewBase);
                }
            }
        }
        av[0]->SetInt(OldLevel);
    }

