    void SF_ItemExtraSpecialsAddByType(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        std::int32_t Index{};
        std::int32_t Count{};
        if (av.length() - 1 < 2) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script SF_ItemExtraSpecialsAddByType"_a));
        }
        aItem::TEquipment* Item = reinterpret_cast<aItem::TEquipment*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())));
        std::int32_t ModuleIndex = av[2]->GetInt() + 1;
        if (ModuleIndex <= 0) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script SF_ItemExtraSpecialsAddByType invalid bonus"_a));
        }
        if (av.length() - 1 > 2) {
            Count = av[3]->GetInt();
        } else {
            Count = 1;
        }
        if (Item->ExtraSpecials == nullptr) {
            if (Count <= 0) {
                return;
            }
            Item->ExtraSpecials = pas::make_object<pas::List>();
        }
        aItem::PExtraSpecial Entry = nullptr;
        std::int32_t Found = -1;
        for (auto cpp_range = pas::for_to<std::int32_t>(0, pas::list_count(Item->ExtraSpecials) - 1); cpp_range.next(Index); ) {
            if (pas::list_at<aItem::TExtraSpecial>(Item->ExtraSpecials, Index)->ModuleIndexPlusOne == ModuleIndex) {
                Entry = pas::list_at<aItem::TExtraSpecial>(Item->ExtraSpecials, Index);
                Found = Index;
                break;
            }
        }
        if (Entry != nullptr) {
            Entry->Count += Count;
            if (Entry->Count <= 0) {
                pas::dispose(Entry);
                pas::list_delete(Item->ExtraSpecials, Found);
                if (pas::list_count(Item->ExtraSpecials) == 0) {
                    pas::free(Item->ExtraSpecials);
                    Item->ExtraSpecials = nullptr;
                }
            }
        } else {
            pas::new_value(Entry);
            pas::list_add(Item->ExtraSpecials, static_cast<void*>(Entry));
            Entry->ModuleIndexPlusOne = ModuleIndex;
            Entry->Count = Count;
        }
    }

