    void SF_ExecuteCodeFromString(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        pas::WideString SourceText{};
        EC_Expression::TCodeEC* RunCode{};
        aScript::TScript* SavedScript{};
        std::int32_t I{};
        std::int32_t Count{};
        if (av.length() - 1 < 1) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script SF_ExecuteCodeFromString"_a));
        }
        SourceText = av[1]->GetString();
        if (av.length() - 1 == 1) {
            if (code != nullptr) {
                aScript::ExecuteScriptText(SourceText, code->LocalVar);
            } else {
                aScript::ExecuteScriptText(SourceText, nullptr);
            }
        } else {
            SavedScript = aScript::CurrentScript;
            RunCode = aScript::CompileScriptText(SourceText);
            RunCode->LinkAll(Globals::SharedScriptVariables, false);
            RunCode->LinkAll(aScript::ScriptFunctionScope, false);
            RunCode->ScriptFunLinked = true;
            if (code != nullptr) {
                RunCode->LinkAll(code->LocalVar, false);
            }
            Count = (av.length() - 1 - 1) / 2;
            for (auto cpp_range = pas::for_to<std::int32_t>(1, Count); cpp_range.next(I); ) {
                EC_Expression::TVarEC* add = ([&] {
                    EC_Expression::TVarKind realVType = av[I * 2 + 1]->RealVType();
                    const pas::WideString& string = av[I * 2]->GetString();
                    EC_Expression::TVarArrayEC* localVar = RunCode->LocalVar;
                    return localVar->Add(string, realVType);
                }());
                EC_Expression::TVarEC* cpp_arg = av[I * 2 + 1];
                add->Assume(cpp_arg, true);
            }
            try {
                RunCode->Run(aScript::ScriptProcess);
            } catch (...) {
                auto cpp_exception = pas::caught_object();
                if (BreakMessageGIException::EBreakMessageGI* E = pas::class_cast_if<BreakMessageGIException::EBreakMessageGI*>(cpp_exception)) {
                } else if (pas::Exception* E_2 = pas::class_cast_if<pas::Exception*>(cpp_exception)) {
                    GR_Main::AppendLogLineThreadSafe(pas::concat_ansi({static_cast<pas::AnsiString>(pas::class_name(pas::class_type(E_2))), " ", E_2->message}));
                    aScript::LogScriptCallHistory();
                    GR_Main::AppendLogLineThreadSafe("Error while executing code from string: "_a);
                    if (SourceText.length() <= 256) {
                        GR_Main::AppendLogLineThreadSafe(static_cast<pas::AnsiString>(SourceText));
                    } else {
                        GR_Main::AppendLogLineThreadSafe(static_cast<pas::AnsiString>(pas::concat_wide({pas::copy(SourceText, 1, 256), u" ..."})));
                    }
                    throw;
                } else {
                    throw;
                }
            }
            if ((av.length() - 1) % 2 == 0) {
                EC_Expression::TVarEC* var = ([&] {
                    const pas::WideString& string_2 = av[av.length() - 1]->GetString();
                    EC_Expression::TVarArrayEC* localVar_2 = RunCode->LocalVar;
                    return localVar_2->GetVar(string_2);
                }());
                EC_Expression::TVarEC* cpp_arg_2 = av[0];
                cpp_arg_2->Assume(var, true);
            }
            aScript::CurrentScript = SavedScript;
            pas::free(RunCode);
        }
    }

    void SF_GenerateCodeStringFromBlock(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        pas::WideString Path{};
        std::int32_t I{};
        EC_BlockPar::TBlockParEC* Block{};
        if (av.length() - 1 < 1) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script SF_GenerateCodeStringFromBlock"_a));
        }
        av[0]->SetString(u""_wref.get());
        Path = av[1]->GetString();
        std::int32_t Count = EC_Str::CountDelimitedPartsW(Path, u"."_wref.get());
        if (av.length() - 1 > 1 && av[2]->GetInt() != 0) {
            Block = GR_Main::MainDataConfig;
        } else {
            Block = GR_Main::LanguageDataConfig;
        }
        for (auto cpp_range = pas::for_to<std::int32_t>(0, Count - 1); cpp_range.next(I); ) {
            Block = Block->FindBlockByPath(EC_Str::ExtractDelimitedPartW(Path, I, u"."_wref.get()));
            if (Block == nullptr) {
                GR_Main::AppendLogLineThreadSafe(static_cast<pas::AnsiString>(pas::concat_wide({u"Warning.Script SF_GenerateCodeStringFromBlock - cant find block ", av[1]->GetString(), u" [", pas::wide_int_to_str(I), u"]"})));
                return;
            }
        }
        av[0]->SetString(Block->ConcatenateValues());
        if (av[0]->GetString() == u"") {
            GR_Main::AppendLogLineThreadSafe(static_cast<pas::AnsiString>(pas::concat_wide({u"Warning.Script SF_GenerateCodeStringFromBlock - no code at ", av[1]->GetString()})));
        }
    }

