                                const pas::WideString& extractDelimitedPartW_2 = EC_Str::ExtractDelimitedPartW(av[3]->GetString(), 1, u"|"_wref.get());
                                GI_GAI::TgaiGI* control_3 = reinterpret_cast<GI_GAI::TgaiGI*>(Control);
