    void SF_FormShipCurItem(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        std::int32_t Query{};
        pas::Object* Item{};
        if (Globals::GetInnermostScreenLoop() != Globals::ShipScreen) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script FormShipCurItem"_a));
        }
        if (av.length() - 1 < 1) {
            if (!pas::is_one_of<fShip2::phkEquipment, fShip2::phkArtefact>(Globals::ShipScreen->SelectedHoldKind)) {
                av[0]->SetDword(0u);
            } else {
                av[0]->SetDword(static_cast<std::uint32_t>(reinterpret_cast<std::uintptr_t>(Globals::ShipScreen->SelectedHoldItem)));
            }
            return;
        }
        if (av[1]->RealVType() == EC_Expression::vkString) {
            if (av[1]->GetString() == u"MoveType") {
                Query = 0;
            } else if (av[1]->GetString() == u"StackableType") {
                Query = 1;
            } else if (av[1]->GetString() == u"StackableCount") {
                Query = 2;
            } else if (av[1]->GetString() == u"StackableCost") {
                Query = 3;
            } else if (av[1]->GetString() == u"PutBack") {
                Query = 4;
            } else if (av[1]->GetString() == u"Destroy") {
                Query = 5;
            } else if (av[1]->GetString() == u"Detach") {
                Query = 6;
            } else if (av[1]->GetString() == u"Replace") {
                Query = 7;
            } else {
                pas::raise(pas::make_exception<pas::Exception>(static_cast<pas::AnsiString>(pas::concat_wide({u"Error.Script FormShipCurItem - query not recognized: ", av[1]->GetString()}))));
            }
        } else {
            Query = av[3]->GetInt();
        }
        switch (Query) {
            case 0: av[0]->SetInt(static_cast<std::int32_t>(Globals::ShipScreen->SelectedHoldKind)); break;
            case 1: av[0]->SetInt(Globals::ShipScreen->SelectedGoodsIndex); break;
            case 2: av[0]->SetInt(Globals::ShipScreen->SelectedGoodsQuantity); break;
            case 3: av[0]->SetInt(Globals::ShipScreen->SelectedGoodsCost); break;
            case 4: Globals::ShipScreen->ReturnSelectedHoldEntry(); break;
            case 5: {
                if (Globals::ShipScreen->SelectedHoldItem != nullptr) {
                    pas::free(Globals::ShipScreen->SelectedHoldItem);
                }
                Globals::ShipScreen->SelectedHoldItem = nullptr;
                Globals::ShipScreen->SelectedHoldKind = fShip2::phkEmpty;
                fShip2::PlayerHoldShip->RefreshDerivedStats(true);
                if (!Globals::ShipScreen->IsCursorImageSelected(u"Main"_wref.get())) {
                    Globals::ShipScreen->SetCursorByName(u"Main"_wref.get());
                }
                Globals::ShipScreen->RefreshShipView();
                break;
            }
            case 6: {
                av[0]->SetDword(static_cast<std::uint32_t>(reinterpret_cast<std::uintptr_t>(Globals::ShipScreen->SelectedHoldItem)));
                Globals::ShipScreen->SelectedHoldItem = nullptr;
                Globals::ShipScreen->SelectedHoldKind = fShip2::phkEmpty;
                fShip2::PlayerHoldShip->RefreshDerivedStats(true);
                if (!Globals::ShipScreen->IsCursorImageSelected(u"Main"_wref.get())) {
                    Globals::ShipScreen->SetCursorByName(u"Main"_wref.get());
                }
                Globals::ShipScreen->RefreshShipView();
                break;
            }
            case 7: {
                if (av.length() - 1 < 2 || av[2]->GetDword() == 0) {
                    pas::raise(pas::make_exception<pas::Exception>("Error.Script FormShipCurItem no replacing item"_a));
                }
                if (Globals::ShipScreen->SelectedHoldItem == nullptr || static_cast<std::uint8_t>(pas::is_one_of<fShip2::phkEquipment, fShip2::phkArtefact>(Globals::ShipScreen->SelectedHoldKind) ^ 1)) {
                    pas::raise(pas::make_exception<pas::Exception>("Error.Script FormShipCurItem no item to replace"_a));
                }
                Item = reinterpret_cast<pas::Object*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[2]->GetDword())));
                av[0]->SetDword(static_cast<std::uint32_t>(reinterpret_cast<std::uintptr_t>(Globals::ShipScreen->SelectedHoldItem)));
                Globals::ShipScreen->SelectedHoldItem = reinterpret_cast<aItem::TItem*>(Item);
                if (pas::class_cast_if<aItem::TArtefact*>(Item) != nullptr) {
                    Globals::ShipScreen->SelectedHoldKind = fShip2::phkArtefact;
                } else {
                    Globals::ShipScreen->SelectedHoldKind = fShip2::phkEquipment;
                }
                fShip2::PlayerHoldShip->RefreshDerivedStats(true);
                Globals::ShipScreen->UpdateActionCursor(true);
                Globals::ShipScreen->RefreshShipView();
                break;
            }
            default: {
                // Native creates this exception without raising or freeing it.
                pas::make_exception<pas::Exception>(static_cast<pas::AnsiString>(pas::concat_wide({u"Error.Script FormShipCurItem - query not recognized: ", EC_Str::IntToWideString(Query)})));
                break;
            }
        }
    }

