    void SF_FormChange(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        GlobalsV::TGameScreenId Id{};
        pas::WideString Name{};
        if (av.length() - 1 < 1) {
            if (reinterpret_cast<GI_MessageLoop::TMessageLoopGI*>(GlobalsV::RegisteredScreens[GlobalsV::RequestedScreenId]) == nullptr) {
                av[0]->SetString(u""_wref.get());
            } else {
                av[0]->SetString(reinterpret_cast<GI_MessageLoop::TMessageLoopGI*>(GlobalsV::RegisteredScreens[GlobalsV::RequestedScreenId])->RegisteredLoopName);
            }
            return;
        }
        Name = av[1]->GetString();
        for (auto cpp_range = pas::for_to<GlobalsV::TGameScreenId>(GlobalsV::screenNone, GlobalsV::screenAchievements); cpp_range.next(Id); ) {
            if (reinterpret_cast<GI_MessageLoop::TMessageLoopGI*>(GlobalsV::RegisteredScreens[Id]) != nullptr && pas::class_cast_if<GI_MessageLoop::TMessageLoopGI*>(GlobalsV::RegisteredScreens[Id]) != nullptr && pas::checked_cast<GI_MessageLoop::TMessageLoopGI*>(GlobalsV::RegisteredScreens[Id])->RegisteredLoopName == Name) {
                GlobalsV::RequestedScreenId = Id;
                if (reinterpret_cast<GI_MessageLoop::TMessageLoopGI*>(GlobalsV::RegisteredScreens[Id]) == Globals::ShipScreen) {
                    if (av.length() - 1 >= 2) {
                        Globals::ShipScreen->ShipToInspect = reinterpret_cast<aShip::TShip*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[2]->GetDword())));
                    }
                    GlobalsV::ShipReturnScreenId = GlobalsV::CurrentScreenId;
                    if (!(GlobalsV::CurrentScreenId != GlobalsV::screenStarMap && pas::class_cast_if<fPanelMain::TMessageLoopGIWithMainPanel*>(reinterpret_cast<GI_MessageLoop::TMessageLoopGI*>(GlobalsV::RegisteredScreens[GlobalsV::CurrentScreenId])) != nullptr && reinterpret_cast<fPanelMain::TMessageLoopGIWithMainPanel*>(reinterpret_cast<GI_MessageLoop::TMessageLoopGI*>(GlobalsV::RegisteredScreens[GlobalsV::CurrentScreenId]))->MainPanel != nullptr)) {
                        GlobalsV::ShipReturnScreenId = GlobalsV::CurrentScreenId;
                        Globals::GetInnermostScreenLoop()->RequestClose(1);
                    } else {
                        reinterpret_cast<fPanelMain::TMessageLoopGIWithMainPanel*>(reinterpret_cast<GI_MessageLoop::TMessageLoopGI*>(GlobalsV::RegisteredScreens[GlobalsV::CurrentScreenId]))->MainPanel->ShipClicked(nullptr);
                    }
                } else {
                    if (reinterpret_cast<GI_MessageLoop::TMessageLoopGI*>(GlobalsV::RegisteredScreens[Id]) == Globals::ScannerScreen) {
                        if (av.length() - 1 >= 2) {
                            Globals::ScannerTarget = reinterpret_cast<pas::Object*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[2]->GetDword())));
                        } else {
                            Globals::ScannerTarget = nullptr;
                        }
                        GlobalsV::ScannerReturnScreenId = GlobalsV::FormToId(Globals::GetInnermostScreenLoop());
                    }
                    Globals::GetInnermostScreenLoop()->RequestClose(1);
                }
                return;
            }
        }
        pas::raise(pas::make_exception<pas::Exception>("Error.Script FormChange - ML not found"_a));
    }

    void SF_RunChildForm(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        GlobalsV::TGameScreenId Id{};
        pas::WideString Name{};
        GI_MessageLoop::TMessageLoopGI* Parent{};
        GI_MessageLoop::TMessageLoopGI* Root{};
        GI_MessageLoop::TMessageLoopGI* Child{};
        GI_MessageLoop::TObjectGI* Background{};
        GI_MessageLoop::TObjectGI* ChildBackground{};
        GI_MessageLoop::TCursorStateGI State{};
        if (av.length() - 1 < 1) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script RunChildForm"_a));
        }
        Name = av[1]->GetString();
        for (auto cpp_range = pas::for_to<GlobalsV::TGameScreenId>(GlobalsV::screenNone, GlobalsV::screenAchievements); cpp_range.next(Id); ) {
            if (reinterpret_cast<GI_MessageLoop::TMessageLoopGI*>(GlobalsV::RegisteredScreens[Id]) != nullptr && pas::class_cast_if<GI_MessageLoop::TMessageLoopGI*>(GlobalsV::RegisteredScreens[Id]) != nullptr && pas::checked_cast<GI_MessageLoop::TMessageLoopGI*>(GlobalsV::RegisteredScreens[Id])->RegisteredLoopName == Name) {
                Child = reinterpret_cast<GI_MessageLoop::TMessageLoopGI*>(GlobalsV::RegisteredScreens[Id]);
                Parent = Globals::GetInnermostScreenLoop();
                ChildBackground = nullptr;
                Background = Child->FindControlByPath(u"BGBuf"_wref.get());
                if (Background != nullptr) {
                    GR_Main::CaptureScreenBackground(true, 0);
                    pas::checked_cast<GI_GraphBuf::TGraphBufGI*>(Background)->BindExternalGraphBuf(GR_Main::AuxRenderBuffer);
                } else {
                    ChildBackground = Child->FindControlByPath(u"BGBufChild"_wref.get());
                    if (ChildBackground != nullptr) {
                        GR_Main::CaptureScreenBackground(true, 0);
                        pas::checked_cast<GI_GraphBuf::TGraphBufGI*>(ChildBackground)->BindExternalGraphBuf(GR_Main::AuxRenderBuffer);
                        ChildBackground->SetActive(true);
                    }
                }
                Parent->RootUiObject->NativeHook50();
                Parent->CaptureCursorState(&State);
                Parent->SetCursorActive(false);
                Parent->DrawQueuedUpdateRects();
                // The identity expression preserves native RHS-first register allocation.
                Child->ParentLoop = reinterpret_cast<GI_MessageLoop::TMessageLoopGI*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(static_cast<std::uint32_t>(reinterpret_cast<std::uintptr_t>(Parent)) * 1)));
                Parent->ChildLoop = Child;
                if (Child == Globals::GalaxyScreen && av.length() - 1 >= 2) {
                    Globals::GalaxyScreen->ViewMode = av[2]->GetInt();
                }
                if (Child->Run() == 1) {
                    av[0]->SetInt(1);
                } else {
                    av[0]->SetInt(0);
                }
                if (ChildBackground != nullptr) {
                    ChildBackground->SetActive(false);
                }
                Child->ParentLoop = nullptr;
                Parent->ChildLoop = nullptr;
                if ((Background != nullptr || ChildBackground != nullptr) && Parent->ParentLoop != nullptr) {
                    Root = Parent->ParentLoop;
                    while (Root->ParentLoop != nullptr) {
                        Root = Root->ParentLoop;
                    }
                    GR_Main::FullFrameRedrawRequested = true;
                    Root->DrawFrame();
                    GR_Main::CaptureScreenBackground(true, 0);
                }
                Parent->InvalidateViewport();
                Parent->RestoreCursorState(&State);
                Parent->UpdateCursorPosition();
                Parent->RootUiObject->NativeHook48();
                Parent->Present();
                GR_Main::PostMouseMoveMessage();
                return;
            }
        }
        pas::raise(pas::make_exception<pas::Exception>("Error.Script RunChildForm - ML not found"_a));
    }

