    void SF_InventNewCustomWeapon(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        std::uint8_t Kind{};
        std::int32_t I{};
        if (av.length() - 1 < 1) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script InventNewCustomWeapon"_a));
        }
        aConst::PWeaponInfo Info = ([&] {
            pas::WideString string = av[1]->GetString();
            aGalaxy::TGalaxy* galaxy = aGalaxy::Galaxy;
            return galaxy->GetOrCreateCustomWeaponInfo(std::move(string));
        }());
        av[0]->SetDword(static_cast<std::uint32_t>(reinterpret_cast<std::uintptr_t>(Info)));
        if (av.length() - 1 > 1) {
            Kind = av[2]->GetInt();
        } else {
            Kind = aConst::t_Weapon1;
        }
        if (!pas::in_range(Kind, static_cast<std::int32_t>(aConst::t_Weapon1), static_cast<std::int32_t>(aConst::t_Weapon18))) {
            pas::raise(pas::make_exception<pas::Exception>(static_cast<pas::AnsiString>(pas::concat_wide({u"Error.Script InventNewCustomWeapon - invalid type ", av[2]->GetString()}))));
        }
        aConst::PWeaponInfo Base = &aConst::WeaponInfos[Kind];
        Info->TechLevel = Base->TechLevel;
        Info->InventionIndex = Base->InventionIndex;
        Info->CostFactor = Base->CostFactor;
        Info->MinDamage = Base->MinDamage;
        Info->MaxDamage = Base->MaxDamage;
        Info->AverageSize = Base->AverageSize;
        Info->AverageRange = Base->AverageRange;
        Info->ShotSpeedPercent = Base->ShotSpeedPercent;
        Info->MissileRange = Base->MissileRange;
        Info->MissileMaxSpeed = Base->MissileMaxSpeed;
        Info->MissileMinSpeed = Base->MissileMinSpeed;
        Info->MissileChanceToBeHit = Base->MissileChanceToBeHit;
        Info->DamageFlags = Base->DamageFlags;
        Info->ShotType = Base->ShotType;
        Info->ShotCount = Base->ShotCount;
        Info->AttackCount = Base->AttackCount;
        Info->SecondaryDamageRadius = Base->SecondaryDamageRadius;
        Info->MiningFactor = Base->MiningFactor;
        Info->PrimarySE = Base->PrimarySE;
        Info->SecondarySE = Base->SecondarySE;
        Info->AreaSE = Base->AreaSE;
        Info->DefaultPalette = Base->DefaultPalette;
        Info->Availability = Base->Availability;
        Info->ArcadeWeaponType = Base->ArcadeWeaponType;
        for (I = 1; I <= 8; ++I) {
            pas::store_unaligned<float>(pas::byte_offset(&Info->DamageScaleByLevel, (I - 1) * sizeof(float)), pas::load_unaligned<float>(pas::byte_offset(&Base->DamageScaleByLevel, (I - 1) * sizeof(float))));
        }
    }

