    void SF_GetCustomWeaponData(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        aConst::PWeaponInfo Info{};
        pas::WideString Key{};
        if (av.length() - 1 < 2) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script GetCustomWeaponStats"_a));
        }
        if (av[1]->RealVType() == EC_Expression::vkString) {
            Info = ([&] {
                pas::WideString string = av[1]->GetString();
                aGalaxy::TGalaxy* galaxy = aGalaxy::Galaxy;
                return galaxy->RequireCustomWeaponInfo(std::move(string));
            }());
        } else {
            Info = &aConst::WeaponInfos[av[1]->GetInt() & 0x0000007f];
        }
        Key = av[2]->GetString();
        if (Key == u"TechLevel") {
            av[0]->SetInt(Info->TechLevel);
        } else if (Key == u"AverageSize") {
            av[0]->SetInt(Info->AverageSize);
        } else if (Key == u"AverageRadius") {
            av[0]->SetInt(Info->AverageRange);
        } else if (Key == u"MissileRadius") {
            av[0]->SetInt(Info->MissileRange);
        } else if (Key == u"SecondaryDamageRadius") {
            av[0]->SetFloat(Info->SecondaryDamageRadius);
        } else if (Key == u"MaxDamage") {
            av[0]->SetInt(Info->MaxDamage);
        } else if (Key == u"MinDamage") {
            av[0]->SetInt(Info->MinDamage);
        } else if (Key == u"DamageType") {
            av[0]->SetDword(Info->DamageFlags);
        } else if (Key == u"kCost") {
            av[0]->SetFloat(Info->CostFactor);
        } else if (Key == u"AttackCount") {
            av[0]->SetInt(Info->AttackCount);
        } else if (Key == u"ShotCount") {
            av[0]->SetInt(Info->ShotCount);
        } else if (Key == u"ShotType") {
            switch (Info->ShotType) {
                case aGalaxyStruct::wstNormal: av[0]->SetString(u"Normal"_wref.get()); break;
                case aGalaxyStruct::wstSplash: av[0]->SetString(u"Splash"_wref.get()); break;
                case aGalaxyStruct::wstExploder: av[0]->SetString(u"Exploder"_wref.get()); break;
                case aGalaxyStruct::wstAreaDamage: av[0]->SetString(u"AreaDamage"_wref.get()); break;
                case aGalaxyStruct::wstTorpedo: av[0]->SetString(u"Torpedo"_wref.get()); break;
                case aGalaxyStruct::wstMissile: av[0]->SetString(u"Missile"_wref.get()); break;
                case aGalaxyStruct::wstRocket: av[0]->SetString(u"Rocket"_wref.get()); break;
                case aGalaxyStruct::wstChain: av[0]->SetString(u"Chain"_wref.get()); break;
            }
        } else if (Key == u"Availability") {
            switch (Info->Availability) {
                case aGalaxyStruct::waFree: av[0]->SetString(u"Free"_wref.get()); break;
                case aGalaxyStruct::waCoalitionOnly: av[0]->SetString(u"CoalitionOnly"_wref.get()); break;
                case aGalaxyStruct::waPirateOnly: av[0]->SetString(u"PirateOnly"_wref.get()); break;
                case aGalaxyStruct::waNotSold: av[0]->SetString(u"NotSold"_wref.get()); break;
                case aGalaxyStruct::waNotSoldAndNodeRepair: av[0]->SetString(u"NotSoldAndNodeRepair"_wref.get()); break;
                case aGalaxyStruct::waMalocOnly: av[0]->SetString(u"MalocOnly"_wref.get()); break;
                case aGalaxyStruct::waPelengOnly: av[0]->SetString(u"PelengOnly"_wref.get()); break;
                case aGalaxyStruct::waPeopleOnly: av[0]->SetString(u"PeopleOnly"_wref.get()); break;
                case aGalaxyStruct::waFeiOnly: av[0]->SetString(u"FeiOnly"_wref.get()); break;
                case aGalaxyStruct::waGaalOnly: av[0]->SetString(u"GaalOnly"_wref.get()); break;
                case aGalaxyStruct::waSystemOnly: av[0]->SetString(u"SystemOnly"_wref.get()); break;
                default: {
                    pas::raise(pas::make_exception<pas::Exception>("Error.Script GetCustomWeaponStats - unknown availability type"_a));
                }
            }
        } else {
            pas::raise(pas::make_exception<pas::Exception>(static_cast<pas::AnsiString>(pas::concat_wide({u"Error.Script GetCustomWeaponStats - unknown stat ", Key}))));
        }
    }

