    void SF_SetCustomWeaponDamageData(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        static const pas::Set<0, 255> EmptyFlags = pas::constant_set<pas::Set<0, 255>>({});
        std::uint8_t Flag{};
        TWeaponDamageFlags Flags{};
        std::int32_t I{};
        std::int32_t Count{};
        pas::WideString Text{};
        if (av.length() - 1 < 4) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script SetCustomWeaponDamageData"_a));
        }
        aConst::PWeaponInfo Info = reinterpret_cast<aConst::PWeaponInfo>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())));
        av[0]->SetDword(static_cast<std::uint32_t>(reinterpret_cast<std::uintptr_t>(Info)));
        Info->MinDamage = av[2]->GetInt();
        Info->MaxDamage = av[3]->GetInt();
        Flags = static_cast<TWeaponDamageFlags>(EmptyFlags);
        if (av[4]->RealVType() == EC_Expression::vkString) {
            Text = pas::concat_wide({u",", av[4]->GetString(), u","});
            for (Flag = static_cast<std::uint8_t>(0); Flag <= static_cast<std::uint8_t>(20); ++Flag) {
                if (pas::pos(pas::concat_wide({u",", aConst::WeaponDamageFlagNames[Flag], u","}), Text) > 0) {
                    pas::include_at(&Flags, Flag);
                }
            }
        } else {
            pas::store_unaligned<std::uint32_t>(&Flags, av[4]->GetDword());
        }
        Info->DamageFlags = pas::load_unaligned<std::uint32_t>(&Flags);
        if (av.length() - 1 > 4 && av[5]->RealVType() == EC_Expression::vkString) {
            Text = av[5]->GetString();
            Count = EC_Str::CountDelimitedPartsW(Text, u","_wref.get());
            for (auto cpp_range = pas::for_to<std::int32_t>(1, std::min<std::int32_t>(8, Count)); cpp_range.next(I); ) {
                pas::store_unaligned<float>(pas::byte_offset(&Info->DamageScaleByLevel, (I - 1) * sizeof(float)), EC_Str::ExtractDecimalToSingleW(EC_Str::ExtractDelimitedPartW(Text, I - 1, u","_wref.get())));
            }
        } else {
            for (auto cpp_range_2 = pas::for_to<std::int32_t>(1, std::min<std::int32_t>(8, av.length() - 1 - 4)); cpp_range_2.next(I); ) {
                if (static_cast<std::uint8_t>(pas::is_one_of<EC_Expression::vkInt, EC_Expression::vkDword>(av[4 + I]->RealVType()) ^ 1) || av[4 + I]->GetInt() != 0) {
                    pas::store_unaligned<float>(pas::byte_offset(&Info->DamageScaleByLevel, (I - 1) * sizeof(float)), static_cast<float>(av[4 + I]->GetFloat()));
                }
            }
        }
    }

    void SF_SetCustomWeaponShotData(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        pas::WideString Text{};
        if (av.length() - 1 < 2) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script SetCustomWeaponShotData"_a));
        }
        aConst::PWeaponInfo Info = reinterpret_cast<aConst::PWeaponInfo>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())));
        av[0]->SetDword(static_cast<std::uint32_t>(reinterpret_cast<std::uintptr_t>(Info)));
        Text = av[2]->GetString();
        Info->ShotType = aGalaxyStruct::wstNormal;
        Info->ShotCount = 1;
        if (pas::pos(u"Normal", Text) <= 0) {
            if (pas::pos(u"Splash", Text) > 0) {
                Info->ShotType = aGalaxyStruct::wstSplash;
            } else if (pas::pos(u"Exploder", Text) > 0) {
                Info->ShotType = aGalaxyStruct::wstExploder;
            } else if (pas::pos(u"AreaDamage", Text) > 0) {
                Info->ShotType = aGalaxyStruct::wstAreaDamage;
            } else if (pas::pos(u"Torpedo", Text) > 0) {
                Info->ShotType = aGalaxyStruct::wstTorpedo;
            } else if (pas::pos(u"Missile", Text) > 0) {
                Info->ShotType = aGalaxyStruct::wstMissile;
            } else if (pas::pos(u"Rocket", Text) > 0) {
                Info->ShotType = aGalaxyStruct::wstRocket;
            } else if (pas::pos(u"Chain", Text) > 0) {
                Info->ShotType = aGalaxyStruct::wstChain;
            }
        }
        if (pas::is_one_of<aGalaxyStruct::wstChain, aGalaxyStruct::wstMissile, aGalaxyStruct::wstRocket>(Info->ShotType)) {
            Info->ShotCount = EC_Str::ExtractDigitsToIntW(Text);
        }
        if (av.length() - 1 > 2) {
            Info->ShotSpeedPercent = av[3]->GetInt();
        }
        if (av.length() - 1 > 3) {
            Info->AverageRange = av[4]->GetInt();
        }
        if (av.length() - 1 > 4) {
            Info->SecondaryDamageRadius = av[5]->GetInt();
        }
        if (av.length() - 1 > 5) {
            Info->MiningFactor = av[6]->GetFloat();
        }
        if (av.length() - 1 > 6) {
            Info->AttackCount = av[7]->GetInt();
        }
    }

