    void SF_ShipCustomFaction(pas::OpenArray<EC_Expression::TVarEC*> av, EC_Expression::TCodeEC* code) {
        auto cpp_array_copy = pas::copy_open_array(av);
        av = pas::open_array(cpp_array_copy);
        aShip::TShip* Ship{};
        if (av.length() - 1 < 1) {
            pas::raise(pas::make_exception<pas::Exception>("Error.Script ShipCustomFaction"_a));
        }
        Ship = reinterpret_cast<aShip::TShip*>(static_cast<std::uintptr_t>(static_cast<std::uint32_t>(av[1]->GetDword())));
        if (aPlayer::GetPlayer() == Ship) {
            if (av.length() - 1 > 1) {
                pas::raise(pas::make_exception<pas::Exception>("Error.Script ShipCustomFaction Player"_a));
            }
            av[0]->SetString(u""_wref.get());
        } else if (Ship->ScriptShip == nullptr) {
            if (av.length() - 1 > 1) {
                pas::raise(pas::make_exception<pas::Exception>("Error.Script ShipCustomFaction non-script ship"_a));
            }
            av[0]->SetString(u""_wref.get());
        } else {
            av[0]->SetString(reinterpret_cast<aScript::TScriptShip*>(Ship->ScriptShip)->StateText);
            if (av.length() - 1 > 1) {
                reinterpret_cast<aScript::TScriptShip*>(Ship->ScriptShip)->StateText = av[2]->GetString();
                Ship->RefreshCurrentStanding();
            }
        }
    }

