        Scope->Add(u"GRun"_wref.get(), EC_Expression::vkExternFun)->SetExternFun(reinterpret_cast<void*>(pas::callback_address(pas::Proc<void(pas::OpenArray<EC_Expression::TVarEC*>, EC_Expression::TCodeEC*)>(SF_GRun))));
