        Scope->Add(u"t_ArtBlackHole"_wref.get(), EC_Expression::vkInt)->SetInt(aConst::t_ArtBlackHole);
        Scope->Add(u"t_ArtDefToArms1"_wref.get(), EC_Expression::vkInt)->SetInt(aConst::t_ArtDefToArms1);
        Scope->Add(u"t_ArtDefToArms2"_wref.get(), EC_Expression::vkInt)->SetInt(aConst::t_ArtDefToArms2);
