    void AddConfigBlock(EC_BlockPar::TBlockParEC* Block, EC_Expression::TVarEC* Dest) {
        std::int32_t I{};
        EC_Expression::TVarEC* Value{};
        for (auto cpp_range = pas::for_to<std::int32_t>(0, Block->GetParamCount() - 1); cpp_range.next(I); ) {
            Value = pas::construct_call<EC_Expression::TVarEC>(EC_Expression::TVarEC_Create, EC_Expression::vkString);
            Value->SetString(Block->GetParamValue(I));
            Value->Name = Block->GetParamName(I);
            Dest->GetArray()->AddItem(Value);
        }
        for (auto cpp_range_2 = pas::for_to<std::int32_t>(0, Block->GetBlockCount() - 1); cpp_range_2.next(I); ) {
            Value = pas::construct_call<EC_Expression::TVarEC>(EC_Expression::TVarEC_Create, EC_Expression::vkArray);
            Value->SetArray(pas::construct_call<EC_Expression::TVarArrayEC>(EC_Expression::TVarArrayEC_Create));
            Value->Name = Block->GetBlockNameByIndex(I);
            aScriptFun::AddConfigBlock(Block->GetBlockByIndex(I), Value);
            if (Value->GetArray()->Count == 0) {
                EC_Expression::TVarEC* cpp_arg = pas::construct_call<EC_Expression::TVarEC>(EC_Expression::TVarEC_Create, EC_Expression::vkEmpty);
                EC_Expression::TVarArrayEC* array = Value->GetArray();
                array->AddItem(cpp_arg);
            }
            Dest->GetArray()->AddItem(Value);
        }
    }

