    void LogArray(pas::WideString Prefix, EC_Expression::TVarEC* Value) {
        std::int32_t I{};
        EC_Expression::TVarEC* Item{};
        pas::WideString Path{};
        for (auto cpp_range = pas::for_to<std::int32_t>(0, Value->GetArray()->Count - 1); cpp_range.next(I); ) {
            Item = EC_Expression::TVarArrayEC_GetItem(Value->GetArray(), I);
            if (Item->Name != u"") {
                Path = pas::concat_wide({Prefix, u"'", Item->Name, u"'"});
            } else {
                Path = pas::concat_wide({Prefix, EC_Str::IntToWideString(I)});
            }
            if (Item->RealVType() != EC_Expression::vkArray) {
                GR_Main::AppendLogLineThreadSafe(static_cast<pas::AnsiString>(pas::concat_wide({Path, u"]=", Item->GetString()})));
            } else {
                aScriptFun::LogArray(pas::concat_wide({Path, u","}), Item);
            }
        }
    }

    void CheckShip(aShip::TShip* Ship, pas::OpenArray<EC_Expression::TVarEC*>& av, std::uint32_t& MinimumId, aGalaxyStruct::TShipTypeMask& Mask, std::uint8_t& IncludeScripted, std::int32_t& FactionCount, pas::DynArray<pas::WideString>& Factions, std::int32_t& TypeCount, pas::DynArray<pas::WideString>& CustomTypes, pas::WideString& Text, EC_Expression::TVarEC*& Value) {
        std::uint8_t Found{};
        std::int32_t I{};
        if (static_cast<std::uint32_t>(Ship->Id) < MinimumId) {
            return;
        }
        if (!pas::contains(Mask, Ship->TypeId)) {
            return;
        }
        if ((Ship->ScriptShip != nullptr || Ship->AbsoluteScriptOrder != 0) && static_cast<std::uint8_t>(IncludeScripted ^ 1)) {
            return;
        }
        if (FactionCount >= 0) {
            if (Ship->ScriptShip != nullptr) {
                Text = reinterpret_cast<aScript::TScriptShip*>(Ship->ScriptShip)->StateText;
            } else {
                Text = pas::WideString();
            }
            if (FactionCount == 0 && Text != u"") {
                return;
            }
            Found = FactionCount == 0;
            for (auto cpp_range = pas::for_to<std::int32_t>(0, FactionCount - 1); cpp_range.next(I); ) {
                if (Text == Factions[I]) {
                    Found = true;
                    break;
                }
            }
            if (!Found) {
                return;
            }
            // The native custom-type filter is nested inside the enabled faction filter.
            if (TypeCount >= 0) {
                Text = Ship->TypeNameOverrideKey;
                if (TypeCount == 0 && Text != u"") {
                    return;
                }
                Found = TypeCount == 0;
                for (auto cpp_range_2 = pas::for_to<std::int32_t>(0, TypeCount - 1); cpp_range_2.next(I); ) {
                    if (Text == CustomTypes[I]) {
                        Found = true;
                        break;
                    }
                }
                if (!Found) {
                    return;
                }
            }
        }
        Value = pas::construct_call<EC_Expression::TVarEC>(EC_Expression::TVarEC_Create, EC_Expression::vkInt);
        Value->SetDword(static_cast<std::uint32_t>(reinterpret_cast<std::uintptr_t>(Ship)));
        av[1]->GetArray()->AddItem(Value);
    }

